/// Slash handling for the session chat endpoints (hermes desktop slash
/// passthrough): `/skill-name` + `/<bundle>` invocations expand into
/// scaffolded agent turns (hermes gateway/run.py shares skill_commands
/// with the CLI for exactly this), while a small session-scoped command
/// set runs without an LLM turn.
enum GatewaySlash {
    /// Expanded text to run through the agent as the user turn.
    AgentTurn(String),
    /// Reply directly — no LLM turn.
    Direct(String),
}

const GATEWAY_SLASH_HELP: &str = "Gateway slash commands:
  /help            this list (/commands is an alias)
  /status          session + agent status
  /context [all]   context-window breakdown (grid + categories; all = per-toolset/skill costs)
  /whoami          process identity (claimer id, home, provider, model)
  /version         ulnclaw version
  /profile         list configured profiles
  /model [P M]     show the model, or persist provider+model
  /reasoning [L]   show or persist the reasoning effort (none|minimal|low|medium|high|xhigh|max|ultra, or clear)
  /fast [on|off] [--global]  Priority Processing toggle (service_tier=priority)
  /memory          memory store status (files, entries, sizes)
  /sessions [N]    list the N most recent sessions (default 10)
  /stop            request a stop for this session's running run
  /restart         drain active runs and exit (code 75) for the supervisor to restart
  /retry           truncate the transcript to the last user turn and re-run it
  /undo [N]        drop the last N user turns (default 1), echoing what was removed
  /verbose [on|off] show or persist agent.verbose
  /yolo [on|off]   show or persist approvals.mode=off (auto-approve; deny rules still bind)
  /personality [name|none]  list or activate a personality (agent.personalities)
  /runs            list the tracked runs (newest first)
  /goal [text|status|show|pause|resume|clear]  standing goal (Ralph loop) control
  /learn <what>      learn a reusable skill from anything you describe
  /moa <prompt>      one-shot Mixture-of-Agents synthesis (default preset)
  /reload            reload <home>/.env vars into the running gateway
  /history [N]       recent transcript of this session (tool chatter collapsed)
  /handoff [platform]  hand this session off to a platform home channel
  /platform [list|pause|resume] [name]   gateway platform retry controls
  /subgoal [text|remove N|clear]  extra criteria on the active goal
  /reload-mcp [confirm]  rebuild the MCP tool surface (confirm when gated)
  /skills          list skills (invoke one: /<skill-name> [instruction])
  /tools           list enabled tools
  /recap           recap this session
  /title [text]    show or set the session title
  /retitle         regenerate this session's title via the LLM
  /usage           this session's token usage
  /kanban <title>  add a task to the current kanban board
  /blueprint [name] [slot=val…]  automation blueprints: catalog, guided setup, or direct create
  /cron [list|show|pause|resume|run|remove|status]  manage scheduled jobs
  /suggestions [accept N|dismiss N|catalog|clear]  review suggested automations
  /background <prompt>  run a prompt in a background tracked run
  /image <path>      attach a local image to your next prompt
  /approvals [manual|smart|off]  show or persist the dangerous-command approval mode
  /debug [no-redact]   write a redacted debug bundle under <home>/debug-bundles
  /queue [clear|<prompt>]  queue a prompt for the next turn (no interrupt)
  /steer <prompt>    inject a message after the next tool call (no interrupt)
  /approve [once|session|always] [run-id]  approve a pending dangerous command
  /deny [run-id]     deny a pending dangerous command
  /init [notes]      generate or update AGENTS.md from a project scan
  /agents            active agents + recent delegations
  /journey           the learning timeline (skills + memory cards)
  /snapshot [create [label]|list|restore <id>|prune [keep]]  state snapshots
  /platforms         messaging-platform connection posture
  /curator [status|run [--dry-run]|pause|resume|pin|unpin|archive|restore|list-archived]  skill maintenance
  /bundles [list|show <name>]  skill bundles (/<slug> invokes one)
  /toolsets          list the toolset catalog (✓ = registered here)
  /insights [N] [--days N] [--source S]   usage analytics across sessions
  /compress        compress this session's context now (summary of older turns)
  /branch [name]   fork this session into a child branch
  /diff [working|staged|all|session] [--stat]  git changes in the session cwd
  /rollback [N|hash]  list or restore filesystem checkpoints for the session cwd
  /<bundle>        invoke a skill bundle (ulnclaw bundles)";

/// A user message that counts as a real conversational turn for slash
/// surgery (`/retry`, `/undo`): not a tool result, not empty, and not
/// a slash invocation (those rows are bookkeeping, not user turns —
/// hermes display_kind filtering parity).
fn is_real_user_turn(message: &Message) -> bool {
    message.role == Role::User
        && message.tool_call_id.is_none()
        && message
            .content
            .as_deref()
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .map(|text| !text.starts_with('/'))
            .unwrap_or(false)
}

/// Collapse a transcript message into one display line (hermes
/// /history preview semantics): whitespace runs become single spaces,
/// capped at 300 chars + ellipsis.
fn flatten_for_history(content: Option<&str>) -> String {
    let flat: String = content
        .unwrap_or_default()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    match flat.char_indices().nth(300) {
        Some((idx, _)) => format!("{}…", &flat[..idx]),
        None => flat,
    }
}

/// `/moa` no-args digest: configured presets (lean `print_moa_presets`
/// twin for chat surfaces).
fn moa_presets_digest(config: &crate::config::UlncLawConfig) -> String {
    let moa = &config.moa;
    if moa.presets.is_empty() {
        return "no MoA presets configured — add [moa.presets.<name>] to config.toml.\n                usage: /moa <prompt>  (runs one prompt through the default preset)"
            .to_string();
    }
    let default_name = moa
        .default_preset
        .clone()
        .filter(|name| moa.presets.contains_key(name))
        .unwrap_or_else(|| "default".to_string());
    let mut names: Vec<&String> = moa.presets.keys().collect();
    names.sort();
    let mut lines = vec!["MoA presets:".to_string()];
    for name in names {
        let preset = &moa.presets[name];
        let marker = if *name == default_name { "*" } else { " " };
        lines.push(format!(
            "{marker} {name}: {} reference(s), aggregator {}",
            preset
                .reference_models
                .iter()
                .filter(|slot| slot.enabled)
                .count(),
            preset.aggregator.label()
        ));
    }
    lines.push("usage: /moa <prompt>  (runs one prompt through the default preset)".to_string());
    lines.join("\n")
}

async fn resolve_gateway_slash(
    state: &Arc<GatewayState>,
    session_id: &str,
    message: &str,
) -> Option<GatewaySlash> {
    let trimmed = message.trim();
    let stripped = trimmed.strip_prefix('/')?;
    if stripped.is_empty() {
        return None;
    }
    let mut parts = trimmed.splitn(2, ' ');
    let cmd = parts.next().unwrap_or("");
    let rest = parts.next().unwrap_or("").trim();
    let skills_dir = state.agent.context().home.join("skills");
    match cmd {
        "/help" | "/commands" => Some(GatewaySlash::Direct(GATEWAY_SLASH_HELP.to_string())),
        "/skills" => {
            let skills = crate::skills::list_skills(&skills_dir);
            if skills.is_empty() {
                Some(GatewaySlash::Direct(
                    "no skills installed (<home>/skills).".to_string(),
                ))
            } else {
                let mut text = String::new();
                for skill in &skills {
                    text.push_str(&format!("  {} — {}\n", skill.name, skill.description));
                }
                Some(GatewaySlash::Direct(text.trim_end().to_string()))
            }
        }
        "/tools" => Some(GatewaySlash::Direct(state.agent.tool_names().join(", "))),
        "/recap" => {
            let row = state.store.get_session_row(session_id).ok().flatten();
            let messages = state.store.load_messages(session_id).unwrap_or_default();
            let recap = crate::session::recap::build_recap(
                &messages,
                row.as_ref().and_then(|r| r.title.as_deref()),
                Some(session_id),
            );
            Some(GatewaySlash::Direct(recap))
        }
        "/title" => {
            if rest.is_empty() {
                let title = state
                    .store
                    .get_session_row(session_id)
                    .ok()
                    .flatten()
                    .and_then(|row| row.title.clone())
                    .filter(|t| !t.is_empty())
                    .unwrap_or_else(|| "(untitled)".to_string());
                Some(GatewaySlash::Direct(format!("title: {title}")))
            } else {
                match state.store.set_session_title(session_id, rest) {
                    Ok(()) => Some(GatewaySlash::Direct(format!("title set: {rest}"))),
                    Err(e) => Some(GatewaySlash::Direct(format!("title set failed: {e}"))),
                }
            }
        }
        "/retitle" => {
            // P570: regenerate this session's title through the LLM
            // titler — the slash twin of POST /api/sessions/:id/retitle.
            let Some(row) = state.store.get_session_row(session_id).ok().flatten() else {
                return Some(GatewaySlash::Direct("session not found.".to_string()));
            };
            let user_text = state
                .store
                .get_first_user_text(session_id)
                .unwrap_or_default();
            if user_text.trim().is_empty() {
                return Some(GatewaySlash::Direct(
                    "no user message to title from.".to_string(),
                ));
            }
            let first_reply = state
                .store
                .get_first_assistant_text(session_id)
                .unwrap_or_default();
            let provider = state.agent.provider();
            let context = state.agent.context();
            let Some(new_title) = crate::title_generator::generate_title_forced(
                &context.config,
                provider.clone(),
                &user_text,
                &first_reply,
            )
            .await
            else {
                return Some(GatewaySlash::Direct(
                    "title generation failed (provider unreachable?).".to_string(),
                ));
            };
            let old_title = row.title.clone().unwrap_or_default();
            if !crate::session::retitle::is_titlelike(&new_title) {
                return Some(GatewaySlash::Direct(format!(
                    "kept \"{old_title}\" \u{2014} got \"{new_title}\" (rejected)"
                )));
            }
            if new_title == old_title {
                return Some(GatewaySlash::Direct(format!(
                    "title already up to date: \"{old_title}\""
                )));
            }
            let final_title = match state.store.set_session_title(session_id, &new_title) {
                Ok(()) => new_title,
                Err(_) => match state.store.get_next_title_in_lineage(&new_title) {
                    Ok(deduped) if state.store.set_session_title(session_id, &deduped).is_ok() => {
                        deduped
                    }
                    _ => {
                        return Some(GatewaySlash::Direct(
                            "title set failed (collision).".to_string(),
                        ))
                    }
                },
            };
            crate::desktop_bridge::publish(
                session_id,
                "session.updated",
                &json!({"session_id": session_id}),
            );
            Some(GatewaySlash::Direct(format!(
                "title: \"{old_title}\" \u{2192} \"{final_title}\""
            )))
        }
        "/usage" => {
            let Some(row) = state.store.get_session_row(session_id).ok().flatten() else {
                return Some(GatewaySlash::Direct("session not found.".to_string()));
            };
            Some(GatewaySlash::Direct(format!(
                "messages: {}  tokens: {} in / {} out",
                row.message_count, row.input_tokens, row.output_tokens
            )))
        }
        "/kanban" => {
            // P369: quick-action composer command — add a card to the
            // current board without leaving the conversation (hermes
            // kanban quick-add parity).
            if rest.is_empty() {
                return Some(GatewaySlash::Direct(
                    "usage: /kanban <task title>".to_string(),
                ));
            }
            let store = match crate::kanban::KanbanStore::open_default() {
                Ok(store) => store,
                Err(e) => return Some(GatewaySlash::Direct(format!("kanban failed: {e}"))),
            };
            match store.create_task(&crate::kanban::NewTask {
                title: rest.to_string(),
                body: String::new(),
                assignee: None,
                priority: 0,
                tenant: None,
                model: None,
                created_by: "slash".to_string(),
                skills: None,
                max_runtime_seconds: None,
                provider: None,
                reasoning_effort: None,
                project_id: None,
                idempotency_key: None,
                triage: false,
                max_retries: None,
                initial_status: None,
                workflow_template_id: None,
                current_step_key: None,
                goal_mode: false,
                goal_max_turns: None,
                workspace_kind: Some("scratch".to_string()),
                workspace_path: None,
                branch_name: None,
                session_id: Some(session_id.to_string()),
            }) {
                Ok(task) => Some(GatewaySlash::Direct(format!(
                    "kanban task added: {} — {}",
                    task.id, task.title
                ))),
                Err(e) => Some(GatewaySlash::Direct(format!("kanban failed: {e}"))),
            }
        }
        "/insights" => {
            let mut days: u32 = 30;
            let mut source: Option<String> = None;
            let mut tokens = rest.split_whitespace();
            while let Some(token) = tokens.next() {
                if token == "--days" {
                    if let Some(value) = tokens.next() {
                        if let Ok(parsed) = value.parse::<u32>() {
                            days = parsed;
                        }
                    }
                } else if token == "--source" {
                    source = tokens.next().map(String::from);
                } else if let Ok(parsed) = token.parse::<u32>() {
                    days = parsed;
                }
            }
            let provider_hint = state.provider_name.as_str();
            let result = match crate::insights::InsightsEngine::open_default() {
                Ok(engine) => match engine.generate(days, source.as_deref(), Some(provider_hint)) {
                    Ok(report) => crate::insights::format_gateway(&report),
                    Err(e) => format!("insights failed: {e}"),
                },
                Err(e) => format!("insights failed: {e}"),
            };
            Some(GatewaySlash::Direct(result))
        }
        "/compress" => {
            let history: Vec<Message> = state
                .store
                .load_messages(session_id)
                .unwrap_or_default()
                .into_iter()
                .filter(|m| m.role != Role::System)
                .collect();
            let compressor =
                crate::context::ContextCompressor::new(state.agent.context_budget_tokens())
                    .with_timezone(state.agent.context().config.timezone.clone());
            let before_messages = history.len();
            if before_messages <= compressor.keep_recent + 2 {
                return Some(GatewaySlash::Direct(format!(
                    "nothing to compress — only {before_messages} message(s); needs more than {}.",
                    compressor.keep_recent + 2
                )));
            }
            let before_tokens = crate::context::ContextCompressor::estimate_tokens(&history);
            // Same auxiliary routing as the agent loop's auto-compression.
            let provider = state.agent.provider();
            let compressed = match crate::provider::auxiliary::resolve_aux_task(
                &state.agent.context().config,
                crate::provider::auxiliary::TASK_COMPRESSION,
                provider.clone(),
            ) {
                Ok(aux) => {
                    compressor
                        .compress_with_model(history.clone(), aux.provider.as_ref(), &aux.model)
                        .await
                }
                Err(e) => {
                    tracing::warn!(
                        "auxiliary compression routing failed: {}; using main provider",
                        e
                    );
                    compressor
                        .compress_with_provider(history.clone(), provider.as_ref())
                        .await
                }
            };
            let Some(compressed) = compressed else {
                return Some(GatewaySlash::Direct(
                    "compression failed or found nothing to summarize.".to_string(),
                ));
            };
            let after_messages = compressed.len();
            let after_tokens = crate::context::ContextCompressor::estimate_tokens(&compressed);
            if let Err(e) = state.store.replace_messages(session_id, &compressed) {
                return Some(GatewaySlash::Direct(format!(
                    "compression failed to persist: {e}"
                )));
            }
            Some(GatewaySlash::Direct(format!(
                "compressed session context: {before_messages} → {after_messages} messages, ~{before_tokens} → ~{after_tokens} tokens."
            )))
        }
        "/status" => {
            // Cockpit-style status (hermes /status parity, lean): the
            // session's persisted totals are the source of truth.
            let row = state.store.get_session_row(session_id).ok().flatten();
            let run_status = {
                let runs = state.runs.lock().await;
                runs.values()
                    .find(|run| run.session_id.as_deref() == Some(session_id))
                    .map(|run| run.status.clone())
                    .unwrap_or_else(|| "idle".to_string())
            };
            let uptime = state.started_at.elapsed().as_secs();
            let (hours, rem) = (uptime / 3600, uptime % 3600);
            let (minutes, seconds) = (rem / 60, rem % 60);
            let mut lines = vec![
                format!("session: {session_id}"),
                format!("run status: {run_status}"),
                format!("model: {} ({})", state.model_name, state.provider_name),
            ];
            if let Some(row) = &row {
                if let Some(title) = row.title.as_deref().filter(|t| !t.is_empty()) {
                    lines.push(format!("title: {title}"));
                }
                lines.push(format!(
                    "messages: {}  tokens: {} in / {} out",
                    row.message_count, row.input_tokens, row.output_tokens
                ));
            }
            lines.push(format!(
                "context budget: {} tokens",
                state.agent.context_budget_tokens()
            ));
            lines.push(format!("gateway uptime: {hours}h {minutes}m {seconds}s"));
            Some(GatewaySlash::Direct(lines.join("\n")))
        }
        "/context" => {
            // Hermes /context parity (P624): glyph grid + per-category
            // table + window summary; `/context all` appends per-toolset
            // and per-skill costs via the prompt-size attribution.
            let history: Vec<Message> = state
                .store
                .load_messages(session_id)
                .unwrap_or_default()
                .into_iter()
                .filter(|m| m.role != Role::System)
                .collect();
            let conversation_tokens = crate::context::ContextCompressor::estimate_tokens(&history);
            let parts = state.agent.context_breakdown_parts().await;
            let budget = state.agent.context_budget_tokens();
            let payload = crate::context::breakdown::compute(&parts, conversation_tokens, budget);
            let mut lines = crate::context::breakdown::render_breakdown_lines(&payload, true);
            if rest.eq_ignore_ascii_case("all") {
                let config = state.agent.context().config.clone();
                let details = tokio::task::spawn_blocking(move || {
                    let home = crate::config::ulnclaw_home();
                    let mut registry = crate::tools::ToolRegistry::new();
                    crate::tools::builtin::register_builtin_tools(&mut registry);
                    crate::toolsets::apply_toolset_policy(
                        &mut registry,
                        &config.enabled_toolsets,
                        &config.disabled_toolsets,
                    );
                    let cwd =
                        std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
                    crate::prompt_size::compute_prompt_breakdown(&config, &home, &cwd, &registry)
                })
                .await
                .ok();
                if let Some(data) = details {
                    const DETAILS_TABLE_LIMIT: usize = 15;
                    if !data.toolsets.is_empty() {
                        lines.push(String::new());
                        lines.push("Toolsets by schema cost (largest first)".to_string());
                        for group in data.toolsets.iter().take(DETAILS_TABLE_LIMIT) {
                            lines.push(format!(
                                "  {:<24} {:>3} tools {:>8} tokens",
                                group.toolset,
                                group.tools,
                                (group.json_bytes + 3) / 4
                            ));
                        }
                        if data.toolsets.len() > DETAILS_TABLE_LIMIT {
                            lines.push(format!(
                                "  \u{2026} and {} more",
                                data.toolsets.len() - DETAILS_TABLE_LIMIT
                            ));
                        }
                    }
                    if !data.skills.is_empty() {
                        lines.push(String::new());
                        lines.push("Skills by cost (SKILL.md = cost when loaded)".to_string());
                        for skill in data.skills.iter().take(DETAILS_TABLE_LIMIT) {
                            let mut name = skill.name.clone();
                            if name.chars().count() > 28 {
                                let clipped: String = name.chars().take(27).collect();
                                name = format!("{clipped}\u{2026}");
                            }
                            lines.push(format!(
                                "  {:<28} SKILL.md {:>8} tokens",
                                name,
                                (skill.skill_md_bytes + 3) / 4
                            ));
                        }
                        if data.skills.len() > DETAILS_TABLE_LIMIT {
                            lines.push(format!(
                                "  \u{2026} and {} more",
                                data.skills.len() - DETAILS_TABLE_LIMIT
                            ));
                        }
                    }
                }
            } else {
                lines.push(String::new());
                lines.push(
                    "Use /context all for per-skill and per-toolset costs; /compress summarizes older turns."
                        .to_string(),
                );
            }
            Some(GatewaySlash::Direct(lines.join("\n")))
        }
        "/whoami" => {
            let context = state.agent.context();
            Some(GatewaySlash::Direct(format!(
                "claimer: {}\nhome: {}\nprovider: {}\nmodel: {}",
                crate::kanban::KanbanStore::claimer_id(),
                context.home.display(),
                state.provider_name,
                state.model_name
            )))
        }
        "/version" => Some(GatewaySlash::Direct(format!(
            "ulnclaw {}",
            env!("CARGO_PKG_VERSION")
        ))),
        "/profile" => {
            // Hermes /profile switches profiles; the gateway process is
            // pinned to its startup profile, so list + point at --profile.
            match crate::profiles_cmd::list_profiles() {
                Ok(profiles) if profiles.is_empty() => Some(GatewaySlash::Direct(
                    "no profiles configured ([profiles.<name>] in config.toml)".to_string(),
                )),
                Ok(profiles) => {
                    let mut lines = vec!["profiles:".to_string()];
                    for (name, profile) in profiles {
                        let model = profile
                            .model
                            .as_ref()
                            .map(|m| format!(" \u{2014} {}/{}", m.provider, m.model))
                            .unwrap_or_default();
                        lines.push(format!("  - {name}{model}"));
                    }
                    lines.push("restart the gateway with --profile <name> to switch".to_string());
                    Some(GatewaySlash::Direct(lines.join("\n")))
                }
                Err(e) => Some(GatewaySlash::Direct(format!("profiles failed: {e}"))),
            }
        }
        "/model" => {
            if rest.is_empty() {
                return Some(GatewaySlash::Direct(format!(
                    "model: {} ({})",
                    state.model_name, state.provider_name
                )));
            }
            let mut tokens = rest.split_whitespace();
            let (Some(provider), Some(model), extra) =
                (tokens.next(), tokens.next(), tokens.next())
            else {
                return Some(GatewaySlash::Direct(
                    "usage: /model <provider> <model>".to_string(),
                ));
            };
            if extra.is_some() {
                return Some(GatewaySlash::Direct(
                    "usage: /model <provider> <model>".to_string(),
                ));
            }
            let path = crate::config_cmd::config_path();
            let mut doc = match crate::config_cmd::load_toml(&path) {
                Ok(v) => v,
                Err(e) => return Some(GatewaySlash::Direct(format!("config load failed: {e}"))),
            };
            if let Err(e) = crate::model_cmd::apply_model_choice(&mut doc, provider, model) {
                return Some(GatewaySlash::Direct(format!("model switch failed: {e}")));
            }
            if let Err(e) = crate::config_cmd::save_toml(&path, &doc) {
                return Some(GatewaySlash::Direct(format!("config save failed: {e}")));
            }
            Some(GatewaySlash::Direct(format!(
                "model set to {provider}/{model} \u{2014} applies to new sessions; restart the gateway to change the running process"
            )))
        }
        "/reasoning" => {
            // Twin of hermes /reasoning: show or persist
            // agent.reasoning_effort. clear/default/inherit remove the
            // pin so the endpoint default applies.
            let path = crate::config_cmd::config_path();
            if rest.is_empty() {
                let current = crate::config::UlncLawConfig::load(Some(&path))
                    .map(|c| c.agent.reasoning_effort)
                    .unwrap_or_default();
                let shown = if current.trim().is_empty() {
                    "endpoint default".to_string()
                } else {
                    current
                };
                return Some(GatewaySlash::Direct(format!(
                    "reasoning effort: {shown}\nusage: /reasoning none|minimal|low|medium|high|xhigh|max|ultra | clear"
                )));
            }
            let lower = rest.trim().to_ascii_lowercase();
            let effort = if matches!(lower.as_str(), "clear" | "default" | "inherit") {
                None
            } else {
                Some(rest.trim())
            };
            let normalized = match persist_reasoning_effort(effort) {
                Ok(v) => v,
                Err(e) => return Some(GatewaySlash::Direct(e)),
            };
            Some(GatewaySlash::Direct(match &normalized {
                Some(level) => format!(
                    "reasoning effort set to {level} \u{2014} applies to new runs; restart the gateway to change this process"
                ),
                None => "reasoning effort cleared \u{2014} the endpoint default applies to new runs"
                    .to_string(),
            }))
        }
        "/fast" => {
            // Hermes /fast parity (Priority Processing toggle). The
            // gateway process is shared by all sessions, so the switch
            // applies process-wide (same adaptation as /profile);
            // --global persists agent.service_tier to config.toml.
            let provider = state.agent.provider();
            let supported = provider.supports_service_tier()
                && crate::model_cmd::model_supports_fast_mode(&state.model_name);
            let lower = rest.trim().to_ascii_lowercase();
            let persist = lower.contains("--global");
            let choice = lower.replace("--global", "");
            let choice = choice.trim();
            let active = provider.active_service_tier();
            if choice.is_empty() || choice == "status" {
                let mode = if active.as_deref() == Some("priority") {
                    "fast"
                } else {
                    "normal"
                };
                return Some(GatewaySlash::Direct(format!(
                    "priority processing: {mode}\nsupported: {}\nusage: /fast on|off [--global]",
                    if supported {
                        "yes"
                    } else {
                        "no (OpenAI gpt-/o-series on OpenAI-compatible endpoints only)"
                    }
                )));
            }
            if !supported {
                return Some(GatewaySlash::Direct(
                    "fast mode is not supported for this model/provider (OpenAI gpt-/o-series on OpenAI-compatible endpoints only)"
                        .to_string(),
                ));
            }
            let tier: Option<String> = match choice {
                "fast" | "on" => Some("priority".to_string()),
                "normal" | "off" => None,
                other => {
                    return Some(GatewaySlash::Direct(format!(
                        "unknown argument: {other} (expected on|off [--global])"
                    )))
                }
            };
            provider.set_service_tier(tier.clone());
            let label = if tier.is_some() {
                "fast (service_tier=priority)"
            } else {
                "normal"
            };
            if persist {
                match persist_service_tier(if tier.is_some() { "fast" } else { "normal" }) {
                    Ok(_) => Some(GatewaySlash::Direct(format!(
                        "priority processing: {label} \u{2014} saved to agent.service_tier"
                    ))),
                    Err(e) => Some(GatewaySlash::Direct(format!(
                        "priority processing: {label} (this process only; persist failed: {e})"
                    ))),
                }
            } else {
                Some(GatewaySlash::Direct(format!(
                    "priority processing: {label} for this gateway process; add --global to persist it"
                )))
            }
        }
        "/memory" => {
            let home = state.agent.context().home.clone();
            Some(GatewaySlash::Direct(crate::memory_cmd::memory_status(
                &home,
            )))
        }
        "/learn" => {
            // hermes /learn parity: rewrite the turn into the
            // standards-guided skill-authoring prompt; the agent does
            // the gathering + authoring with its normal tools.
            Some(GatewaySlash::AgentTurn(
                crate::learn_prompt::build_learn_prompt(rest),
            ))
        }
        "/platform" => {
            // hermes /platform parity: list connected + retry/pause
            // queue; pause/resume a failing platform's retries.
            Some(GatewaySlash::Direct(crate::messaging::run_platform_slash(
                rest,
            )))
        }
        "/handoff" => {
            // hermes /handoff parity (lean): bind this session to a
            // platform's home channel and ping it — the conversation
            // continues there (session remap + history eviction).
            let live = crate::messaging::platform_sender_names();
            let platform = if rest.is_empty() {
                if live.len() == 1 {
                    live[0].clone()
                } else if live.is_empty() {
                    return Some(GatewaySlash::Direct(
                        "no messaging platforms are connected — handoff needs a live platform."
                            .to_string(),
                    ));
                } else {
                    return Some(GatewaySlash::Direct(format!(
                        "usage: /handoff <platform> — connected: {}",
                        live.join(", ")
                    )));
                }
            } else {
                let wanted = rest.split_whitespace().next().unwrap_or("").to_lowercase();
                if live.iter().any(|p| p == &wanted) {
                    wanted
                } else {
                    return Some(GatewaySlash::Direct(format!(
                        "platform '{wanted}' is not connected — live platforms: {}.",
                        if live.is_empty() {
                            "none".to_string()
                        } else {
                            live.join(", ")
                        }
                    )));
                }
            };
            let chat_id = crate::config::get_env_value(
                &crate::send_message_tool::home_channel_env(&platform),
            )
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty());
            let Some(chat_id) = chat_id else {
                return Some(GatewaySlash::Direct(format!(
                    "no home channel configured for {platform} — send /sethome in the target chat first."
                )));
            };
            let session_key = format!("platform-{platform}-{chat_id}");
            crate::messaging::set_session_remap(&session_key, session_id);
            crate::messaging::drop_history_cache(&session_key).await;
            let title = state
                .store
                .get_session_row(session_id)
                .ok()
                .flatten()
                .and_then(|row| row.title)
                .filter(|t| !t.is_empty());
            if let Some(sender) = crate::messaging::platform_sender(&platform) {
                let notice = match &title {
                    Some(title) => format!(
                        "\u{21AA} Session **{title}** handed off here — send a message to continue."
                    ),
                    None => {
                        "\u{21AA} Session handed off here — send a message to continue.".to_string()
                    }
                };
                sender.send_text(&chat_id, &notice).await;
            }
            Some(GatewaySlash::Direct(match &title {
                Some(title) => format!(
                    "\u{2713} Handed session **{title}** off to {platform} ({chat_id}) — continue there."
                ),
                None => format!(
                    "\u{2713} Handed this session off to {platform} ({chat_id}) — continue there."
                ),
            }))
        }
        "/history" => {
            // hermes /history parity (lean): recent transcript of this
            // session; tool calls/results collapse into hidden counts.
            let limit = rest
                .split_whitespace()
                .next()
                .and_then(|token| token.parse::<usize>().ok())
                .unwrap_or(20)
                .clamp(1, 200);
            let messages = state.store.load_messages(session_id).unwrap_or_default();
            if messages.is_empty() {
                return Some(GatewaySlash::Direct(
                    "(._.) No conversation history yet.".to_string(),
                ));
            }
            let start = messages.len().saturating_sub(limit);
            let mut lines = vec![format!(
                "conversation history ({session_id}, last {} of {} messages):",
                messages.len() - start,
                messages.len()
            )];
            let mut hidden_tools = 0usize;
            for message in &messages[start..] {
                let is_user = message.role == Role::User;
                let is_assistant_text = message.role == Role::Assistant
                    && message
                        .content
                        .as_deref()
                        .map(|c| !c.trim().is_empty())
                        .unwrap_or(false);
                if is_user || is_assistant_text {
                    if hidden_tools > 0 {
                        lines.push(format!("  [tools] ({hidden_tools} tool messages hidden)"));
                        hidden_tools = 0;
                    }
                    let (glyph, label) = if is_user {
                        ("\u{1F464}", "user")
                    } else {
                        ("\u{1F916}", "assistant")
                    };
                    lines.push(format!(
                        "  {glyph} {label}: {}",
                        flatten_for_history(message.content.as_deref())
                    ));
                } else {
                    hidden_tools += 1;
                }
            }
            if hidden_tools > 0 {
                lines.push(format!("  [tools] ({hidden_tools} tool messages hidden)"));
            }
            Some(GatewaySlash::Direct(lines.join("\n")))
        }
        "/reload" => {
            // hermes /reload parity: re-read <home>/.env into the
            // process env so new keys are picked up without restart.
            let count = crate::config::reload_env();
            Some(GatewaySlash::Direct(format!(
                "\u{2713} Reloaded .env — {count} variable(s) updated. Provider/model                  config changes still need a gateway restart."
            )))
        }
        "/moa" => {
            // hermes /moa parity (REPL /moa twin): one prompt through
            // the default Mixture-of-Agents preset — parallel reference
            // models + aggregator synthesis. Bare /moa lists presets.
            if rest.is_empty() {
                return Some(GatewaySlash::Direct(moa_presets_digest(
                    &state.agent.context().config,
                )));
            }
            let config = state.agent.context().config.clone();
            let prompt = rest.to_string();
            let reply = match crate::moa::run_moa(&config, &prompt, None).await {
                Ok(outcome) => {
                    let mut lines: Vec<String> = outcome
                        .references
                        .iter()
                        .map(|reference| {
                            if reference.failed() {
                                format!("  \u{2717} {} failed", reference.label)
                            } else {
                                format!("  \u{2713} {}", reference.label)
                            }
                        })
                        .collect();
                    lines.push(String::new());
                    lines.push(outcome.synthesis.clone());
                    lines.join("\n")
                }
                Err(e) => format!("moa failed: {e}"),
            };
            Some(GatewaySlash::Direct(reply))
        }
        "/sessions" => {
            let limit = rest
                .split_whitespace()
                .next()
                .and_then(|token| token.parse::<usize>().ok())
                .unwrap_or(10)
                .clamp(1, 50);
            let rows = match state.store.list_session_rows(limit) {
                Ok(rows) => rows,
                Err(e) => return Some(GatewaySlash::Direct(format!("sessions failed: {e}"))),
            };
            if rows.is_empty() {
                return Some(GatewaySlash::Direct("no sessions yet.".to_string()));
            }
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs_f64())
                .unwrap_or(0.0);
            let mut lines = vec![format!("recent sessions ({limit} max):")];
            for row in rows {
                let age_secs = (now - row.last_activity_at).max(0.0) as i64;
                let age = if age_secs < 60 {
                    format!("{age_secs}s ago")
                } else if age_secs < 3600 {
                    format!("{}m ago", age_secs / 60)
                } else if age_secs < 86_400 {
                    format!("{}h ago", age_secs / 3600)
                } else {
                    format!("{}d ago", age_secs / 86_400)
                };
                let title = row
                    .title
                    .as_deref()
                    .filter(|t| !t.is_empty())
                    .unwrap_or("(untitled)");
                lines.push(format!(
                    "  {} \u{2014} {} ({} msgs, {age})",
                    row.id, title, row.message_count
                ));
            }
            Some(GatewaySlash::Direct(lines.join("\n")))
        }
        "/stop" => {
            // Best-effort twin of POST /v1/runs/:id/stop scoped to this
            // session: mark any running/queued run for interruption.
            let mut runs = state.runs.lock().await;
            let mut stopped = 0usize;
            for run in runs.values_mut() {
                if run.session_id.as_deref() == Some(session_id)
                    && (run.status == "running" || run.status == "queued")
                    && !run.stop_requested
                {
                    run.stop_requested = true;
                    stopped += 1;
                }
            }
            Some(GatewaySlash::Direct(if stopped > 0 {
                format!(
                    "stop requested for {stopped} run(s); the agent finishes its current iteration"
                )
            } else {
                "no running run found for this session.".to_string()
            }))
        }
        "/image" => {
            // P683 (hermes /image parity): stage a local image for the
            // session's next turn; it rides natively in the model call.
            if rest.is_empty() {
                let staged = state
                    .pending_images
                    .lock()
                    .unwrap()
                    .get(session_id)
                    .cloned()
                    .unwrap_or_default();
                return Some(GatewaySlash::Direct(if staged.is_empty() {
                    "usage: /image <path> — attach a local image to your next prompt".to_string()
                } else {
                    format!(
                        "{} image(s) staged for your next prompt: {}",
                        staged.len(),
                        staged.join(", ")
                    )
                }));
            }
            let path = std::path::Path::new(rest.trim());
            match std::fs::metadata(path) {
                Ok(meta) if meta.is_file() => {}
                Ok(_) => return Some(GatewaySlash::Direct(format!("{rest}: not a file"))),
                Err(e) => return Some(GatewaySlash::Direct(format!("{rest}: {e}"))),
            }
            let mime = crate::media_cache::mime_for_ext(path);
            if !mime.starts_with("image/") {
                return Some(GatewaySlash::Direct(format!(
                    "{rest}: unsupported type {mime} (images only)"
                )));
            }
            let count = {
                let mut pending = state.pending_images.lock().unwrap();
                let slot = pending.entry(session_id.to_string()).or_default();
                slot.push(rest.trim().to_string());
                slot.len()
            };
            Some(GatewaySlash::Direct(format!(
                "attached {rest} to your next prompt ({count} staged)"
            )))
        }
        "/approvals" => {
            // P681 (hermes /approvals parity): show or persist the
            // dangerous-command approval mode (manual|smart|off).
            let path = crate::config_cmd::config_path();
            let current_mode = crate::config::UlncLawConfig::load(Some(&path))
                .map(|c| c.approvals.mode)
                .unwrap_or_else(|_| "manual".to_string());
            let arg = rest.trim().to_ascii_lowercase();
            if arg.is_empty() {
                return Some(GatewaySlash::Direct(format!(
                    "approvals.mode: {current_mode} (manual prompts a human; smart asks the auxiliary guardian first; off auto-approves except approvals.deny rules)\nusage: /approvals manual|smart|off"
                )));
            }
            match persist_approvals_mode(&arg) {
                Ok(mode) => Some(GatewaySlash::Direct(format!(
                    "approvals.mode set to \"{mode}\" — applies to new runs"
                ))),
                Err(e) => Some(GatewaySlash::Direct(e)),
            }
        }
        "/debug" => {
            // P681 (hermes /debug local-mode parity): write a redacted
            // debug bundle (system info + logs) under
            // <home>/debug-bundles and report the paths.
            let arg = rest.trim().to_ascii_lowercase();
            let redact = match arg.as_str() {
                "" | "redact" | "--redact" => true,
                "no-redact" | "--no-redact" => false,
                _ => {
                    return Some(GatewaySlash::Direct(
                        "usage: /debug [no-redact]".to_string(),
                    ))
                }
            };
            let home = match crate::config::ensure_home() {
                Ok(home) => home,
                Err(e) => return Some(GatewaySlash::Direct(format!("debug bundle failed: {e}"))),
            };
            let output = home
                .join("debug-bundles")
                .join(format!("ulnclaw-debug-{}", now_secs()));
            let output_str = output.to_string_lossy().to_string();
            let config = crate::config::UlncLawConfig::load(None).unwrap_or_default();
            match crate::debug_cmd::handle_debug_command(
                &config,
                None,
                50,
                redact,
                Some(&output_str),
            ) {
                Ok(report) => Some(GatewaySlash::Direct(report.trim_end().to_string())),
                Err(e) => Some(GatewaySlash::Direct(format!("debug bundle failed: {e}"))),
            }
        }
        "/queue" => {
            // P680 (hermes /queue parity): FIFO prompts run as agent
            // turns after the current turn finishes.
            if rest == "clear" {
                let removed = state
                    .queued_prompts
                    .lock()
                    .unwrap()
                    .remove(session_id)
                    .map(|queue| queue.len())
                    .unwrap_or(0);
                return Some(GatewaySlash::Direct(format!(
                    "cleared {removed} queued prompt(s)."
                )));
            }
            if rest.is_empty() {
                let queued = state
                    .queued_prompts
                    .lock()
                    .unwrap()
                    .get(session_id)
                    .cloned()
                    .unwrap_or_default();
                return Some(GatewaySlash::Direct(if queued.is_empty() {
                    "nothing queued for this session. usage: /queue <prompt>".to_string()
                } else {
                    let mut text = format!("{} queued prompt(s):", queued.len());
                    for (index, prompt) in queued.iter().enumerate() {
                        text.push_str(&format!(
                            "\n  {}. {}",
                            index + 1,
                            crate::gateway::truncate_for_ui(prompt, 120)
                        ));
                    }
                    text
                }));
            }
            let depth = {
                let mut queues = state.queued_prompts.lock().unwrap();
                let queue = queues.entry(session_id.to_string()).or_default();
                queue.push_back(rest.to_string());
                queue.len()
            };
            Some(GatewaySlash::Direct(format!(
                "queued for the next turn (depth {depth}): {}",
                crate::gateway::truncate_for_ui(rest, 120)
            )))
        }
        "/steer" => {
            // P680 (hermes /steer parity): inject a message after the
            // next tool call of the session's active turn.
            if rest.is_empty() {
                return Some(GatewaySlash::Direct(
                    "usage: /steer <prompt> — injected after the next tool call without interrupting".to_string(),
                ));
            }
            let depth = state
                .agent
                .steer_message(session_id, rest.to_string())
                .await;
            Some(GatewaySlash::Direct(format!(
                "steered (depth {depth}) — the message is injected after the next tool call"
            )))
        }
        "/restart" => {
            // P679 (hermes /restart parity): drain active runs, then
            // exit with the service-restart code so the supervisor
            // revives the gateway.
            if state
                .restart
                .swap(true, std::sync::atomic::Ordering::SeqCst)
            {
                return Some(GatewaySlash::Direct(
                    "restart already in progress — draining active runs.".to_string(),
                ));
            }
            let active = active_run_count(state).await;
            let draining = state.clone();
            tokio::spawn(async move {
                // P726: out-of-loop shutdown watchdog (hermes
                // shutdown_watchdog.arm_shutdown_watchdog) — if the
                // drain path wedges past drain-timeout + grace, a
                // plain OS thread dumps diagnostics and forces the
                // exit so the supervisor can revive the gateway.
                let watchdog_done = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
                crate::shutdown_watchdog::arm_shutdown_watchdog(
                    watchdog_done.clone(),
                    crate::shutdown_watchdog::ShutdownWatchdogOptions {
                        delay: std::time::Duration::from_secs_f64(
                            crate::shutdown_watchdog::resolve_shutdown_watchdog_delay(
                                RESTART_DRAIN_TIMEOUT_SECS as f64,
                                crate::shutdown_watchdog::DEFAULT_SHUTDOWN_WATCHDOG_GRACE_S,
                            ),
                        ),
                        snapshot_fn: Some(std::sync::Arc::new(
                            || serde_json::json!({"trigger": "restart_drain"}),
                        )),
                        exit_code: GATEWAY_SERVICE_RESTART_EXIT_CODE,
                        dump_path: None,
                        home: None,
                        exit_fn: std::sync::Arc::new(|code| std::process::exit(code)),
                    },
                );
                let remaining = drain_active_runs(
                    &draining,
                    std::time::Duration::from_secs(RESTART_DRAIN_TIMEOUT_SECS),
                )
                .await;
                if remaining > 0 {
                    tracing::warn!(
                        "gateway restart drain timeout: {remaining} run(s) still active"
                    );
                }
                // P726: drain settled (or timed out in-band) — disarm
                // the hard-exit backstop; the normal exit path runs.
                watchdog_done.store(true, std::sync::atomic::Ordering::SeqCst);
                // Best-effort pidfile cleanup so the single-instance
                // guard never points at a dead process between exit
                // and the supervisor restart.
                if let Ok(home) = crate::config::ensure_home() {
                    let _ = std::fs::remove_file(crate::gateway_pidfile::pidfile_path(&home));
                    // P701: a restart drain is a clean exit — the next
                    // life must not read this as an unclean death.
                    crate::lifecycle_ledger::mark_exited(
                        &home,
                        Some(GATEWAY_SERVICE_RESTART_EXIT_CODE),
                        "restart_drain",
                    );
                }
                (draining.restart_exit)(GATEWAY_SERVICE_RESTART_EXIT_CODE);
            });
            let mut text = format!(
                "♻ restart scheduled — draining {active} active run(s) (max {RESTART_DRAIN_TIMEOUT_SECS}s), then the gateway exits with code {GATEWAY_SERVICE_RESTART_EXIT_CODE} for the supervisor to revive it."
            );
            if !gateway_supervised() {
                text.push_str(
                    " note: no supervisor detected (systemd/launchd or ULNCLAW_GATEWAY_SUPERVISOR=1) — the gateway will not come back on its own.",
                );
            }
            Some(GatewaySlash::Direct(text))
        }
        "/retry" => {
            // Hermes /retry parity: find the last real user turn, drop
            // everything from there on, and re-run it. Slash rows and
            // tool results are bookkeeping, not retryable user turns.
            let history = state.store.load_messages(session_id).unwrap_or_default();
            let last_user = history
                .iter()
                .enumerate()
                .rev()
                .find(|(_, m)| is_real_user_turn(m));
            let Some((index, message)) = last_user else {
                return Some(GatewaySlash::Direct(
                    "no previous message to retry.".to_string(),
                ));
            };
            let text = message.content.clone().unwrap_or_default();
            let truncated: Vec<Message> = history.into_iter().take(index).collect();
            if let Err(e) = state.store.replace_messages(session_id, &truncated) {
                return Some(GatewaySlash::Direct(format!(
                    "retry failed to truncate: {e}"
                )));
            }
            Some(GatewaySlash::AgentTurn(text))
        }
        "/undo" => {
            // Hermes /undo parity (hard-truncate adaptation): drop the
            // last N user turns plus everything after them, and echo
            // the removed user text so it can be copied and re-sent.
            let turns = match rest.split_whitespace().next() {
                None => 1,
                Some(raw) => match raw.parse::<usize>() {
                    Ok(parsed) => parsed.max(1),
                    Err(_) => {
                        return Some(GatewaySlash::Direct(format!("invalid turn count: {raw}")))
                    }
                },
            };
            let history = state.store.load_messages(session_id).unwrap_or_default();
            let user_cuts: Vec<usize> = history
                .iter()
                .enumerate()
                .filter(|(_, m)| is_real_user_turn(m))
                .map(|(index, _)| index)
                .collect();
            let Some(&cut) = user_cuts.iter().rev().nth(turns - 1).or(user_cuts.first()) else {
                return Some(GatewaySlash::Direct("nothing to undo.".to_string()));
            };
            let removed: Vec<Message> = history.iter().skip(cut).cloned().collect();
            let truncated: Vec<Message> = history.into_iter().take(cut).collect();
            if let Err(e) = state.store.replace_messages(session_id, &truncated) {
                return Some(GatewaySlash::Direct(format!("undo failed: {e}")));
            }
            let echoes: Vec<String> = removed
                .iter()
                .filter(|m| is_real_user_turn(m))
                .filter_map(|m| m.content.as_deref())
                .map(|text| {
                    let first_line = text.lines().next().unwrap_or(text);
                    let clipped: String = first_line.chars().take(120).collect();
                    format!("> {clipped}")
                })
                .collect();
            let undone = echoes.len().max(1);
            let mut reply = format!("undid {undone} user turn(s). removed:");
            for echo in echoes {
                reply.push('\n');
                reply.push_str(&echo);
            }
            Some(GatewaySlash::Direct(reply))
        }
        "/branch" => {
            // Hermes /branch parity: fork the current session into a
            // child branch (same mechanics as POST /api/sessions/:id/fork,
            // which the desktop /fork composer command already uses).
            let source = match state.store.get_session_row(session_id) {
                Ok(Some(row)) => row,
                Ok(None) => {
                    return Some(GatewaySlash::Direct(format!(
                        "session {session_id} not found"
                    )))
                }
                Err(e) => return Some(GatewaySlash::Direct(format!("branch failed: {e}"))),
            };
            let messages = state.store.load_messages(session_id).unwrap_or_default();
            if messages.is_empty() {
                return Some(GatewaySlash::Direct(
                    "no conversation to branch yet".to_string(),
                ));
            }
            let fork_id = format!(
                "api_{}_{}",
                now_secs() as u64,
                &uuid::Uuid::new_v4().simple().to_string()[..8]
            );
            if let Err(e) = state.store.end_session(session_id, "branched") {
                return Some(GatewaySlash::Direct(format!("branch failed: {e}")));
            }
            if let Err(e) = state.store.create_named_session(
                &fork_id,
                "gateway",
                source.model.as_deref(),
                Some(session_id),
            ) {
                return Some(GatewaySlash::Direct(format!("branch failed: {e}")));
            }
            for message in &messages {
                if let Err(e) = state.store.append_message(&fork_id, message) {
                    return Some(GatewaySlash::Direct(format!("branch copy failed: {e}")));
                }
            }
            let name = rest.trim();
            let title = if name.is_empty() {
                format!("{} branch", source.title.as_deref().unwrap_or("branch"))
            } else {
                name.to_string()
            };
            match crate::session::sqlite::sanitize_title(&title) {
                Ok(cleaned) => {
                    if let Some(cleaned) = cleaned {
                        if let Err(e) = state.store.set_session_title(&fork_id, &cleaned) {
                            return Some(GatewaySlash::Direct(format!(
                                "branch created but title rejected: {e}"
                            )));
                        }
                    }
                }
                Err(e) => {
                    return Some(GatewaySlash::Direct(format!(
                        "branch created but title rejected: {e}"
                    )))
                }
            }
            Some(GatewaySlash::Direct(format!(
                "branched session {fork_id} \u{2014} {title}; resume it with /open {}",
                &fork_id[..fork_id.len().min(12)]
            )))
        }
        "/diff" => {
            // Hermes /diff parity: git changes in the session's cwd —
            // working (default), staged, all, or the cumulative
            // checkpoint-baseline "session" diff; --stat limits to the
            // summary. Chat surfaces are not pagers, so the body is
            // capped.
            let cwd = session_cwd(&state, session_id);
            let mut stat_only = false;
            let mut mode_raw = "working";
            for token in rest.split_whitespace() {
                match token.to_ascii_lowercase().as_str() {
                    "--stat" | "stat" => stat_only = true,
                    "staged" | "--staged" | "cached" | "--cached" => mode_raw = "staged",
                    "all" | "--all" | "head" => mode_raw = "all",
                    "session" => mode_raw = "session",
                    "working" => {}
                    other => {
                        return Some(GatewaySlash::Direct(format!(
                            "unknown /diff argument: {other} (expected working|staged|all|session [--stat])"
                        )))
                    }
                }
            }
            let (stat, diff, untracked): (String, String, Vec<String>);
            if mode_raw == "session" {
                let config = state.agent.context().config.clone();
                let home = state.agent.context().home.clone();
                if !config.checkpoints.enabled {
                    return Some(GatewaySlash::Direct(
                        "checkpoints are not enabled ([checkpoints] enabled = true)".to_string(),
                    ));
                }
                let manager = crate::checkpoint::CheckpointManager::new(
                    home.join("checkpoints"),
                    &config.checkpoints,
                );
                let dir = cwd.to_string_lossy().to_string();
                let result = manager.session_diff(&dir).await;
                if result["success"] != json!(true) {
                    return Some(GatewaySlash::Direct(format!(
                        "session diff failed: {}",
                        result["error"].as_str().unwrap_or("unknown error")
                    )));
                }
                stat = result["stat"].as_str().unwrap_or_default().to_string();
                diff = result["diff"].as_str().unwrap_or_default().to_string();
                untracked = Vec::new();
            } else {
                let mode = match crate::git_diff::DiffMode::parse(mode_raw) {
                    Some(mode) => mode,
                    None => {
                        return Some(GatewaySlash::Direct(format!(
                            "unknown diff mode: {mode_raw}"
                        )))
                    }
                };
                let dir = cwd.clone();
                let outcome = tokio::task::spawn_blocking(move || {
                    crate::git_diff::collect_working_diff(&dir, mode, &[])
                })
                .await;
                match outcome {
                    Ok(Ok(result)) => {
                        stat = result.stat;
                        diff = result.diff;
                        untracked = result.untracked;
                        if result.empty {
                            return Some(GatewaySlash::Direct(
                                "no changes in the working tree".to_string(),
                            ));
                        }
                    }
                    Ok(Err(e)) => return Some(GatewaySlash::Direct(format!("diff failed: {e}"))),
                    Err(e) => return Some(GatewaySlash::Direct(format!("diff failed: {e}"))),
                }
            }
            if stat.trim().is_empty() && diff.trim().is_empty() {
                return Some(GatewaySlash::Direct("no changes".to_string()));
            }
            let mut out = Vec::new();
            if !stat.trim().is_empty() {
                out.push(stat.trim_end().to_string());
            }
            if !stat_only {
                if !untracked.is_empty() {
                    let shown: Vec<String> = untracked
                        .iter()
                        .take(15)
                        .map(|path| format!("+ {path}"))
                        .collect();
                    let mut block = format!("untracked:\n{}", shown.join("\n"));
                    if untracked.len() > 15 {
                        block.push_str(&format!("\n\u{2026} and {} more", untracked.len() - 15));
                    }
                    out.push(block);
                }
                if !diff.trim().is_empty() {
                    out.push(crate::title_generator::truncate_chars(
                        diff.trim_end(),
                        4000,
                    ));
                }
            }
            Some(GatewaySlash::Direct(out.join("\n\n")))
        }
        "/rollback" => {
            // Hermes /rollback parity: list or restore filesystem
            // checkpoints for the session's cwd (checkpoint store in
            // <home>/checkpoints; a pre-rollback snapshot is taken
            // automatically so the undo is itself undoable).
            let config = state.agent.context().config.clone();
            if !config.checkpoints.enabled {
                return Some(GatewaySlash::Direct(
                    "checkpoints are not enabled ([checkpoints] enabled = true)".to_string(),
                ));
            }
            let home = state.agent.context().home.clone();
            let manager = crate::checkpoint::CheckpointManager::new(
                home.join("checkpoints"),
                &config.checkpoints,
            );
            let cwd = session_cwd(&state, session_id);
            let dir = cwd.to_string_lossy().to_string();
            let arg = rest.trim();
            if arg.is_empty() {
                let checkpoints = manager.list_checkpoints(&dir).await;
                return Some(GatewaySlash::Direct(
                    crate::checkpoint::format_checkpoint_list(&checkpoints, &dir),
                ));
            }
            let checkpoints = manager.list_checkpoints(&dir).await;
            if checkpoints.is_empty() {
                return Some(GatewaySlash::Direct(format!(
                    "no checkpoints found for {dir}"
                )));
            }
            let target = match arg.parse::<usize>() {
                Ok(index) if index >= 1 && index <= checkpoints.len() => {
                    checkpoints[index - 1].hash.clone()
                }
                Ok(index) => {
                    return Some(GatewaySlash::Direct(format!(
                        "invalid checkpoint number: {index} (1-{})",
                        checkpoints.len()
                    )))
                }
                Err(_) => arg.to_string(),
            };
            match manager.restore(&dir, &target, None).await {
                Ok(result) => Some(GatewaySlash::Direct(format!(
                    "restored {} to checkpoint {} ({})",
                    dir,
                    result["restored_to"].as_str().unwrap_or("?"),
                    result["reason"].as_str().unwrap_or("unknown").trim()
                ))),
                Err(e) => Some(GatewaySlash::Direct(format!("rollback failed: {e}"))),
            }
        }
        "/blueprint" => {
            // Hermes /blueprint parity: browse the automation-blueprint
            // catalog, seed the agent to gather slot values
            // conversationally, or create the job directly with inline
            // slot=val arguments (deterministic power-user shortcut).
            let tokens = crate::cron::blueprints::tokenize_blueprint_args(rest);
            let Some(query) = tokens.first() else {
                return Some(GatewaySlash::Direct(
                    crate::cron::blueprints::format_catalog(),
                ));
            };
            let (blueprint, candidates) = crate::cron::blueprints::match_blueprint(query);
            let Some(blueprint) = blueprint else {
                return Some(GatewaySlash::Direct(if candidates.is_empty() {
                    crate::cron::blueprints::format_no_match(query)
                } else {
                    crate::cron::blueprints::format_candidates(query, &candidates)
                }));
            };
            let values: std::collections::HashMap<String, String> = tokens[1..]
                .iter()
                .filter_map(|tok| {
                    let tok = tok.as_str();
                    let eq = tok.find('=')?;
                    let key = tok[..eq].trim();
                    let value = tok[eq + 1..].trim();
                    if key.is_empty() {
                        return None;
                    }
                    Some((key.to_string(), value.to_string()))
                })
                .collect();
            if values.is_empty() {
                // Name only -> seed the agent to ask for each slot one
                // at a time (the messaging-assistant model).
                return Some(GatewaySlash::AgentTurn(
                    crate::cron::blueprints::build_blueprint_seed(&blueprint),
                ));
            }
            let store = match state.cron.get() {
                Some(store) => store,
                None => {
                    return Some(GatewaySlash::Direct(
                        "cron jobs are not enabled on this gateway".to_string(),
                    ))
                }
            };
            let filled = match crate::cron::blueprints::fill_blueprint(&blueprint, &values) {
                Ok(filled) => filled,
                Err(e) => {
                    return Some(GatewaySlash::Direct(format!(
                        "Can't set up '{}': {e}\nOr just run /blueprint {} and I'll ask you for the values.",
                        blueprint.title, blueprint.key
                    )))
                }
            };
            let deliver_value = Value::String(filled.deliver.clone());
            let deliver = crate::cron::delivery::normalize_deliver_value(Some(&deliver_value));
            let parsed = match crate::cron::parse_schedule(&filled.schedule) {
                Ok(parsed) => parsed,
                Err(e) => {
                    return Some(GatewaySlash::Direct(format!(
                        "failed to create the job: invalid schedule: {e}"
                    )))
                }
            };
            let job = CronJob {
                id: uuid::Uuid::new_v4().simple().to_string()[..12].to_string(),
                name: filled.name,
                schedule: filled.schedule.clone(),
                prompt: filled.prompt,
                skills: filled.skills,
                enabled: true,
                repeat: None,
                next_run: crate::cron::next_run(&parsed),
                created_at: now_secs(),
                last_run: None,
                last_status: None,
                deliver: Some(deliver),
                origin: None,
                last_delivery_error: None,
                attach_to_session: None,
            };
            match store.add(&job) {
                Ok(()) => Some(GatewaySlash::Direct(format!(
                    "Scheduled '{}' ({}), delivering to {}. Ask me to list, pause, or remove it any time.",
                    blueprint.title, filled.schedule, filled.deliver
                ))),
                Err(e) => Some(GatewaySlash::Direct(format!(
                    "failed to create the job: {e}"
                ))),
            }
        }
        "/toolsets" => {
            // Hermes /toolsets parity (P672): the toolset catalog with
            // the agent's registered toolsets marked.
            let enabled = state.agent.toolset_names();
            let digest = crate::toolsets::format_toolsets_digest(&enabled);
            Some(GatewaySlash::Direct(digest.trim_end().to_string()))
        }
        "/bundles" => {
            // Hermes /bundles parity (P671): list skill bundles (or
            // show one); invoking stays /<slug> [instruction].
            let reply = crate::bundles::run_slash(rest);
            Some(GatewaySlash::Direct(reply.trim_end().to_string()))
        }
        "/curator" => {
            // Hermes /curator parity (P670): background skill
            // maintenance controls (status/run/pause/resume/pin/
            // unpin/archive/restore/list-archived).
            let home = crate::config::ulnclaw_home();
            let reply = crate::curator::run_slash(&home, rest);
            Some(GatewaySlash::Direct(reply.trim_end().to_string()))
        }
        "/platforms" => {
            // Hermes /platforms parity (P669): messaging-platform
            // posture digest (same catalog as /api/messaging/platforms).
            let rows = crate::messaging::platform_state_rows();
            let digest = crate::messaging::format_platforms_digest(&rows);
            Some(GatewaySlash::Direct(digest.trim_end().to_string()))
        }
        "/snapshot" => {
            // Hermes /snapshot parity (P668): create/list/restore/prune
            // quick state snapshots (config, state.db, .env, cron…).
            let home = crate::config::ulnclaw_home();
            let reply = crate::backup::snapshot_slash(&home, rest);
            Some(GatewaySlash::Direct(reply.trim_end().to_string()))
        }
        "/journey" => {
            // Hermes /journey parity (P667): the learning timeline
            // (learned skills + approved memory cards) as a digest.
            let home = crate::config::ulnclaw_home();
            let digest = crate::learning_graph::journey_digest(&home, 15);
            Some(GatewaySlash::Direct(digest.trim_end().to_string()))
        }
        "/agents" => {
            // Hermes /agents parity (P666): active agents + recent
            // delegations digest (live registry; the Runs view shows
            // the durable history).
            let records = crate::async_delegation::list_delegations();
            Some(GatewaySlash::Direct(
                crate::async_delegation::format_agents_digest(&records)
                    .trim_end()
                    .to_string(),
            ))
        }
        "/background" => {
            // Hermes /background parity (P676): run the prompt in a
            // background tracked run with its own session; the chat is
            // immediately free for other work. Track it with /runs.
            let message = rest.trim().to_string();
            if message.is_empty() {
                return Some(GatewaySlash::Direct(
                    "usage: /background <prompt>".to_string(),
                ));
            }
            let run_id = uuid::Uuid::new_v4().to_string();
            let background_session = state
                .store
                .create_session("gateway-run", Some(&state.model_name), None)
                .unwrap_or_else(|_| uuid::Uuid::new_v4().to_string());
            crate::desktop_bridge::publish(
                "",
                "session.created",
                &json!({"session_id": background_session, "source": "gateway-run"}),
            );
            let run = RunState {
                run_id: run_id.clone(),
                status: "running".to_string(),
                session_id: Some(background_session.clone()),
                message: message.clone(),
                created_at: now_secs(),
                finished_at: None,
                result: None,
                error: None,
                iterations: None,
                stop_requested: false,
                approval: None,
                job_id: None,
            };
            state.runs.lock().await.insert(run_id.clone(), run);
            spawn_tracked_run(
                state.clone(),
                run_id.clone(),
                background_session.clone(),
                message,
                false,
            );
            Some(GatewaySlash::Direct(format!(
                "started background run {run_id} in session {background_session} — track it with /runs"
            )))
        }
        "/approve" => {
            // Hermes /approve parity (P675): resolve a pending
            // dangerous-command approval from chat. Optional decision
            // (once|session|always, default once) and run id (default:
            // the newest waiting run, this session first).
            let mut decision = "once";
            let mut run_id: Option<String> = None;
            for token in rest.split_whitespace() {
                match token {
                    "once" | "session" | "always" => decision = token,
                    "deny" => {
                        return Some(GatewaySlash::Direct(
                            "use /deny to reject a pending command".to_string(),
                        ))
                    }
                    other => run_id = Some(other.to_string()),
                }
            }
            let reply =
                resolve_pending_approval(&state, session_id, run_id.as_deref(), decision).await;
            Some(GatewaySlash::Direct(reply))
        }
        "/deny" => {
            // Hermes /deny parity (P675): reject a pending
            // dangerous-command approval from chat.
            let run_id = rest
                .split_whitespace()
                .next()
                .map(|token| token.to_string());
            let reply =
                resolve_pending_approval(&state, session_id, run_id.as_deref(), "deny").await;
            Some(GatewaySlash::Direct(reply))
        }
        "/init" => {
            // Hermes /init parity (P665): generate or update AGENTS.md
            // from a scan of the session cwd — prompt-injection turn.
            let cwd = session_cwd(&state, session_id);
            let extra = rest.trim().to_string();
            let prompt = crate::init_command::build_init_prompt_for_cwd(Some(&cwd), &extra);
            Some(GatewaySlash::AgentTurn(prompt))
        }
        "/suggestions" => {
            // Hermes /suggestions parity (P664): pending automation
            // suggestions with accept/dismiss; `accept` schedules the
            // job into the shared cron store.
            Some(GatewaySlash::Direct(
                crate::cron::suggestions::handle_suggestions_command(rest),
            ))
        }
        "/cron" => {
            // Hermes /cron parity (P663): manage scheduled jobs inline.
            // `run <id>` hands the job's prompt to this session as an
            // agent turn; the other arms are store-backed and reply
            // directly.
            let home = crate::config::ulnclaw_home();
            let result = crate::cron::run_slash(&home, rest);
            if let Some(prompt) = result.run_prompt {
                return Some(GatewaySlash::AgentTurn(prompt));
            }
            Some(GatewaySlash::Direct(result.text.trim_end().to_string()))
        }
        "/verbose" => {
            // Show or persist agent.verbose (takes effect for new runs).
            let path = crate::config_cmd::config_path();
            let current = crate::config::UlncLawConfig::load(Some(&path))
                .map(|c| c.agent.verbose)
                .unwrap_or(false);
            let arg = rest.trim().to_ascii_lowercase();
            if arg.is_empty() {
                return Some(GatewaySlash::Direct(format!(
                    "verbose logging: {}\nusage: /verbose on|off",
                    if current { "on" } else { "off" }
                )));
            }
            let value = match arg.as_str() {
                "on" | "true" | "1" => true,
                "off" | "false" | "0" => false,
                _ => return Some(GatewaySlash::Direct("usage: /verbose on|off".to_string())),
            };
            let mut doc = match crate::config_cmd::load_toml(&path) {
                Ok(v) => v,
                Err(e) => return Some(GatewaySlash::Direct(format!("config load failed: {e}"))),
            };
            let Some(root) = doc.as_table_mut() else {
                return Some(GatewaySlash::Direct(
                    "config root is not a table".to_string(),
                ));
            };
            let agent_entry = root
                .entry("agent".to_string())
                .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
            let Some(agent_table) = agent_entry.as_table_mut() else {
                return Some(GatewaySlash::Direct(
                    "config [agent] is not a table".to_string(),
                ));
            };
            agent_table.insert("verbose".to_string(), toml::Value::Boolean(value));
            if let Err(e) = crate::config_cmd::save_toml(&path, &doc) {
                return Some(GatewaySlash::Direct(format!("config save failed: {e}")));
            }
            Some(GatewaySlash::Direct(format!(
                "verbose logging set to {} \u{2014} applies to new runs; restart the gateway to change this process",
                if value { "on" } else { "off" }
            )))
        }
        "/yolo" => {
            // Show or persist approvals.mode=off (hermes /yolo parity,
            // config-persisted adaptation). Deny rules still bind.
            let path = crate::config_cmd::config_path();
            let current_mode = crate::config::UlncLawConfig::load(Some(&path))
                .map(|c| c.approvals.mode)
                .unwrap_or_else(|_| "manual".to_string());
            let arg = rest.trim().to_ascii_lowercase();
            if arg.is_empty() {
                let state = if current_mode == "off" { "on" } else { "off" };
                return Some(GatewaySlash::Direct(format!(
                    "yolo (approvals.mode=off): {state} (current mode: {current_mode})\nusage: /yolo on|off"
                )));
            }
            let mode = match arg.as_str() {
                "on" | "true" | "1" => "off",
                "off" | "false" | "0" => "manual",
                _ => return Some(GatewaySlash::Direct("usage: /yolo on|off".to_string())),
            };
            match persist_approvals_mode(mode) {
                Ok(_) => {}
                Err(e) => return Some(GatewaySlash::Direct(e)),
            }
            Some(GatewaySlash::Direct(if mode == "off" {
                "yolo ON \u{2014} approvals.mode=\"off\" persisted: dangerous commands auto-approve except approvals.deny rules; applies to new runs".to_string()
            } else {
                "yolo OFF \u{2014} approvals.mode=\"manual\" persisted; applies to new runs"
                    .to_string()
            }))
        }
        "/personality" => {
            // Hermes /personality parity: list the configured
            // personalities or activate one by resolving its prompt
            // into agent.system_prompt.
            let path = crate::config_cmd::config_path();
            let config = match crate::config::UlncLawConfig::load(Some(&path)) {
                Ok(c) => c,
                Err(e) => return Some(GatewaySlash::Direct(format!("config load failed: {e}"))),
            };
            if config.agent.personalities.is_empty() {
                return Some(GatewaySlash::Direct(
                    "no personalities configured ([agent.personalities] in config.toml)"
                        .to_string(),
                ));
            }
            let arg = rest.trim();
            if arg.is_empty() {
                let mut lines = vec![
                    "personalities:".to_string(),
                    "  none \u{2014} the default persona".to_string(),
                ];
                let mut names: Vec<&String> = config.agent.personalities.keys().collect();
                names.sort();
                for name in names {
                    let preview = config.agent.personalities[name].preview();
                    lines.push(format!("  {name} \u{2014} {preview}"));
                }
                lines.push("usage: /personality <name> | none".to_string());
                return Some(GatewaySlash::Direct(lines.join("\n")));
            }
            let lower = arg.to_ascii_lowercase();
            let name = if matches!(lower.as_str(), "none" | "default" | "neutral") {
                None
            } else {
                Some(lower.as_str())
            };
            match apply_personality(name) {
                Ok(Some(applied)) => Some(GatewaySlash::Direct(format!(
                    "personality set to {applied} \u{2014} applies to new runs; restart the gateway to change this process"
                ))),
                Ok(None) => Some(GatewaySlash::Direct(
                    "personality cleared \u{2014} the default persona applies to new runs"
                        .to_string(),
                )),
                Err(e) => Some(GatewaySlash::Direct(e)),
            }
        }
        "/runs" => {
            // The slash twin of GET /v1/runs: newest-first digest of
            // the tracked runs (status, session, error when present).
            let runs = state.runs.lock().await;
            let mut data: Vec<&RunState> = runs.values().collect();
            data.sort_by(|a, b| {
                b.created_at
                    .partial_cmp(&a.created_at)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
            if data.is_empty() {
                return Some(GatewaySlash::Direct("no runs tracked yet.".to_string()));
            }
            let mut lines = vec![format!("tracked runs ({}):", data.len())];
            for run in data.iter().take(10) {
                let session = run.session_id.as_deref().unwrap_or("-");
                let mut line = format!(
                    "  {} \u{2014} {} (session {session})",
                    run.run_id, run.status
                );
                if let Some(error) = run.error.as_deref().filter(|e| !e.is_empty()) {
                    let clipped: String = error.chars().take(80).collect();
                    line.push_str(&format!(": {clipped}"));
                }
                lines.push(line);
            }
            Some(GatewaySlash::Direct(lines.join("\n")))
        }
        "/goal" => {
            // Gateway twin of the CLI standing-goal control plane
            // (hermes /goal): manages the session's persisted Ralph-loop
            // state. Setting a goal kicks it off as this turn's work —
            // hermes queues the goal text as the next turn. The
            // judge-driven continuation loop itself runs on REPL/kanban
            // turns; gateway turns stay client-driven.
            let mut manager = crate::goals::GoalManager::new(
                session_id.to_string(),
                Some(state.store.clone()),
                crate::goals::DEFAULT_MAX_TURNS,
            );
            let lower = rest.to_ascii_lowercase();
            if rest.is_empty() || lower == "status" {
                return Some(GatewaySlash::Direct(manager.status_line()));
            }
            if lower == "show" {
                let mut text = manager.status_line();
                if manager.has_goal() {
                    text.push('\n');
                    text.push_str(&manager.render_contract());
                }
                return Some(GatewaySlash::Direct(text));
            }
            if lower == "pause" {
                return Some(GatewaySlash::Direct(match manager.pause("user-paused") {
                    Some(goal_state) => format!("\u{23F8} goal paused: {}", goal_state.goal),
                    None => "no goal set.".to_string(),
                }));
            }
            if lower == "resume" {
                return Some(GatewaySlash::Direct(match manager.resume(true) {
                    Some(goal_state) => format!("\u{25B6} goal resumed: {}", goal_state.goal),
                    None => "no goal set.".to_string(),
                }));
            }
            if lower == "clear" {
                let had_goal = manager.has_goal();
                manager.clear();
                return Some(GatewaySlash::Direct(if had_goal {
                    "goal cleared.".to_string()
                } else {
                    "no goal set.".to_string()
                }));
            }
            // Anything else is the new goal text; inline `field: value`
            // lines form the completion contract (hermes parse_contract).
            let (objective, contract) = crate::goals::parse_contract(rest);
            match manager.set(&objective, None, Some(contract)) {
                Ok(goal_state) => Some(GatewaySlash::AgentTurn(goal_state.goal)),
                Err(e) => Some(GatewaySlash::Direct(format!("invalid goal: {e}"))),
            }
        }
        "/subgoal" => {
            // Extra criteria on the active goal (hermes /subgoal).
            let mut manager = crate::goals::GoalManager::new(
                session_id.to_string(),
                Some(state.store.clone()),
                crate::goals::DEFAULT_MAX_TURNS,
            );
            if rest.is_empty() {
                return Some(GatewaySlash::Direct(manager.render_subgoals()));
            }
            let mut parts = rest.splitn(2, ' ');
            match parts.next().unwrap_or("") {
                "remove" => {
                    let index_raw = parts.next().unwrap_or("").trim();
                    if index_raw.is_empty() {
                        return Some(GatewaySlash::Direct(
                            "usage: /subgoal remove <n>".to_string(),
                        ));
                    }
                    match index_raw.parse::<usize>() {
                        Ok(n) => match manager.remove_subgoal(n) {
                            Ok(removed) => Some(GatewaySlash::Direct(format!(
                                "removed subgoal {n}: {removed}"
                            ))),
                            Err(e) => Some(GatewaySlash::Direct(format!("/subgoal remove: {e}"))),
                        },
                        Err(_) => Some(GatewaySlash::Direct(
                            "/subgoal remove: <n> must be a 1-based integer".to_string(),
                        )),
                    }
                }
                "clear" => match manager.clear_subgoals() {
                    Ok(count) => Some(GatewaySlash::Direct(format!("cleared {count} subgoal(s)"))),
                    Err(e) => Some(GatewaySlash::Direct(format!("/subgoal clear: {e}"))),
                },
                _ => match manager.add_subgoal(rest) {
                    Ok(text) => Some(GatewaySlash::Direct(format!("added subgoal: {text}"))),
                    Err(e) => Some(GatewaySlash::Direct(format!("/subgoal: {e}"))),
                },
            }
        }
        "/reload-mcp" => {
            // Gateway twin of the CLI /reload-mcp (hermes parity).
            // There is no interactive prompt over HTTP, so the
            // approvals.mcp_reload_confirm gate becomes a confirm
            // round-trip: warn first, reload on `/reload-mcp confirm`.
            let confirm_required = state.agent.context().config.approvals.mcp_reload_confirm;
            let confirmed = matches!(rest.trim().to_ascii_lowercase().as_str(), "confirm" | "yes");
            if confirm_required && !confirmed {
                return Some(GatewaySlash::Direct(
                    "\u{26A0}\u{FE0F} /reload-mcp rebuilds the MCP tool surface and invalidates                      the provider prompt cache (the next message re-sends full input tokens).                      Send `/reload-mcp confirm` to proceed."
                        .to_string(),
                ));
            }
            match crate::config::UlncLawConfig::load(None) {
                Ok(fresh_config) => {
                    let report = state.agent.reload_mcp(&fresh_config).await;
                    Some(GatewaySlash::Direct(crate::mcp::format_reload_report(
                        &report,
                    )))
                }
                Err(e) => Some(GatewaySlash::Direct(format!("config load failed: {e}"))),
            }
        }
        _ => {
            let cmd_name = cmd.trim_start_matches('/');
            // Bundles win over single skills (hermes bundle-over-skill
            // slash precedence).
            if let Some(key) = crate::bundles::resolve_bundle_command_key(cmd_name) {
                if let Some((message, _loaded, _missing)) =
                    crate::bundles::build_bundle_invocation_message(&key, rest, &skills_dir)
                {
                    return Some(GatewaySlash::AgentTurn(message));
                }
            }
            if let Some(message) =
                crate::skills::build_skill_invocation_message(&skills_dir, cmd_name, rest)
            {
                return Some(GatewaySlash::AgentTurn(message));
            }
            Some(GatewaySlash::Direct(format!(
                "unknown command: {cmd} — /help lists gateway slash commands"
            )))
        }
    }
}

/// Persist a direct slash exchange so the transcript stays whole, and
/// answer with a single-chunk SSE stream (chat-completions shape).
fn direct_sse_response(
    state: &Arc<GatewayState>,
    session_id: &str,
    request: &str,
    text: String,
) -> Response {
    let user_msg = Message {
        role: Role::User,
        content: Some(request.to_string()),
        tool_calls: None,
        tool_call_id: None,
        name: None,
    };
    let assistant_msg = Message {
        role: Role::Assistant,
        content: Some(text.clone()),
        tool_calls: None,
        tool_call_id: None,
        name: None,
    };
    let _ = state.store.append_message(session_id, &user_msg);
    let _ = state.store.append_message(session_id, &assistant_msg);
    use axum::response::sse::{Event, Sse};
    let completion_id = format!("chatcmpl-{}", uuid::Uuid::new_v4());
    let created = now_secs() as u64;
    let model = state.model_name.clone();
    let chunk = |delta: Value, finish: Value| -> Value {
        json!({
            "id": completion_id,
            "object": "chat.completion.chunk",
            "created": created,
            "model": model,
            "choices": [{"index": 0, "delta": delta, "finish_reason": finish}],
        })
    };
    let mut final_chunk = chunk(json!({}), json!("stop"));
    final_chunk["usage"] = json!({"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0});
    let events: Vec<Event> = vec![
        Event::default()
            .json_data(chunk(json!({"role": "assistant"}), Value::Null))
            .unwrap(),
        Event::default()
            .json_data(chunk(json!({"content": text}), Value::Null))
            .unwrap(),
        Event::default().json_data(final_chunk).unwrap(),
        Event::default().data("[DONE]"),
    ];
    let stream = futures::stream::iter(
        events
            .into_iter()
            .map(Ok::<Event, std::convert::Infallible>),
    );
    Sse::new(stream).into_response()
}

/// Drain finished background delegations into a session before its turn —
/// hermes' async-delegation wake delivery (positive-ownership by the
/// process session key; ulnclaw runs one profile per gateway process).
fn drain_delegations_into_session(state: &GatewayState, session_id: &str) {
    let key = state.agent.context().session_id.clone();
    for completion in crate::async_delegation::drain_completions(Some(&state.store), &key) {
        let message = crate::provider::Message {
            role: crate::provider::Role::User,
            content: Some(completion.message),
            tool_calls: None,
            tool_call_id: None,
            name: None,
        };
        let _ = state.store.append_message(session_id, &message);
    }
}

async fn session_chat(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Json(request): Json<SessionChatRequest>,
) -> Response {
    if request.message.trim().is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": {"message": "message is required", "type": "invalid_request_error"}})),
        )
            .into_response();
    }
    drain_delegations_into_session(&state, &id);
    let mut message = request.message.clone();
    if let Some(slash) = resolve_gateway_slash(&state, &id, &message).await {
        match slash {
            GatewaySlash::Direct(text) => {
                let user_msg = Message {
                    role: Role::User,
                    content: Some(message.clone()),
                    tool_calls: None,
                    tool_call_id: None,
                    name: None,
                };
                let assistant_msg = Message {
                    role: Role::Assistant,
                    content: Some(text.clone()),
                    tool_calls: None,
                    tool_call_id: None,
                    name: None,
                };
                let _ = state.store.append_message(&id, &user_msg);
                let _ = state.store.append_message(&id, &assistant_msg);
                return Json(json!({
                    "session_id": id,
                    "response": text,
                    "iterations": 0,
                }))
                .into_response();
            }
            GatewaySlash::AgentTurn(expanded) => message = expanded,
        }
    }
    let history = state
        .store
        .load_messages(&id)
        .unwrap_or_default()
        .into_iter()
        .filter(|m| m.role != Role::System)
        .collect::<Vec<_>>();
    let history_arg = if history.is_empty() {
        None
    } else {
        Some(history)
    };
    // P683: request-attached images plus anything `/image` staged for
    // this session ride natively in the model call.
    let mut image_paths = request.images.clone().unwrap_or_default();
    image_paths.extend(
        state
            .pending_images
            .lock()
            .unwrap()
            .remove(&id)
            .unwrap_or_default(),
    );
    let images = match load_chat_images(&image_paths) {
        Ok(images) => images,
        Err(e) => return bad_request(&e, None),
    };
    let override_model = session_model_override(&state, &id);
    state
        .metrics
        .session_chats
        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let outcome = await_with_model_override(
        override_model,
        state
            .agent
            .run_with_session_images(&message, images, history_arg, Some(&id)),
    )
    .await;
    match outcome {
        Ok(result) => {
            state
                .metrics
                .record_run(&result.usage, result.tool_calls.len());
            // P680: flush queued prompts as follow-up turns.
            spawn_queue_drain(&state, &id);
            Json(json!({
                "session_id": id,
                "response": result.content,
                "iterations": result.iterations,
            }))
            .into_response()
        }
        Err(e) => server_error(&e.to_string()),
    }
}

/// `POST /api/sessions/:id/chat/stream` — SSE wrapper over session chat
/// (hermes `_handle_session_chat_stream`).
async fn session_chat_stream(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Json(request): Json<SessionChatRequest>,
) -> Response {
    if request.message.trim().is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": {"message": "message is required", "type": "invalid_request_error"}})),
        )
            .into_response();
    }
    drain_delegations_into_session(&state, &id);
    let mut message = request.message.clone();
    if let Some(slash) = resolve_gateway_slash(&state, &id, &message).await {
        match slash {
            GatewaySlash::Direct(text) => {
                return direct_sse_response(&state, &id, &message, text);
            }
            GatewaySlash::AgentTurn(expanded) => message = expanded,
        }
    }
    let history = state
        .store
        .load_messages(&id)
        .unwrap_or_default()
        .into_iter()
        .filter(|m| m.role != Role::System)
        .collect::<Vec<_>>();
    let history_arg = if history.is_empty() {
        None
    } else {
        Some(history)
    };
    // P683: request-attached images plus `/image` staged paths.
    let mut image_paths = request.images.clone().unwrap_or_default();
    image_paths.extend(
        state
            .pending_images
            .lock()
            .unwrap()
            .remove(&id)
            .unwrap_or_default(),
    );
    let images = match load_chat_images(&image_paths) {
        Ok(images) => images,
        Err(e) => return bad_request(&e, None),
    };
    stream_agent_response(state, message, history_arg, Some(id), images)
}

/// `PATCH /api/sessions/:id` — update client-safe session metadata
/// (hermes `_handle_patch_session`). Only `title` and `end_reason` are
/// accepted; unknown fields are rejected.
/// `end_reason: null` clears a recorded end (unarchive; P414).
async fn patch_session(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Json(body): Json<Value>,
) -> Response {
    match state.store.get_session_row(&id) {
        Ok(None) => return not_found(&format!("session {} not found", id)),
        Err(e) => return server_error(&e.to_string()),
        Ok(Some(_)) => {}
    }
    let Some(obj) = body.as_object() else {
        return bad_request("body must be a JSON object", None);
    };
    let unknown: Vec<&String> = obj
        .keys()
        .filter(|k| k.as_str() != "title" && k.as_str() != "end_reason" && k.as_str() != "archived")
        .collect();
    if !unknown.is_empty() {
        let names = unknown
            .iter()
            .map(|k| k.as_str())
            .collect::<Vec<_>>()
            .join(", ");
        return bad_request(
            &format!("Unsupported session fields: {}", names),
            Some("unsupported_session_field"),
        );
    }
    if let Some(title) = obj.get("title") {
        let title = match title {
            Value::Null => String::new(),
            Value::String(s) => s.clone(),
            other => other.to_string(),
        };
        if let Err(e) = state.store.set_session_title(&id, &title) {
            return bad_request(&e.to_string(), Some("invalid_title"));
        }
    }
    match obj.get("archived") {
        Some(Value::Bool(flag)) => {
            if let Err(e) = state.store.set_session_archived(&id, *flag) {
                return server_error(&e.to_string());
            }
        }
        Some(Value::Null) => {
            if let Err(e) = state.store.set_session_archived(&id, false) {
                return server_error(&e.to_string());
            }
        }
        _ => {}
    }
    match obj.get("end_reason") {
        // `end_reason: null` clears the recorded end (unarchive; P414).
        Some(Value::Null) => {
            if let Err(e) = state.store.clear_session_end(&id) {
                return server_error(&e.to_string());
            }
        }
        Some(Value::String(reason)) if !reason.is_empty() => {
            if let Err(e) = state.store.end_session(&id, reason) {
                return server_error(&e.to_string());
            }
        }
        _ => {}
    }
    match state.store.get_session_row(&id) {
        Ok(Some(row)) => {
            // P445: tell the desktop shell the session changed.
            crate::desktop_bridge::publish(&id, "session.updated", &json!({"session_id": id}));
            Json(json!({"object": "ulnclaw.session", "session": row})).into_response()
        }
        Ok(None) => not_found(&format!("session {} not found", id)),
        Err(e) => server_error(&e.to_string()),
    }
}

/// `POST /api/sessions/:id/fork` — branch a session (hermes
/// `_handle_fork_session`). Marks the source as `branched` and creates a
/// child session carrying the transcript forward.
async fn fork_session(
    State(state): State<Arc<GatewayState>>,
    Path(source_id): Path<String>,
    Json(body): Json<Value>,
) -> Response {
    let source = match state.store.get_session_row(&source_id) {
        Ok(Some(row)) => row,
        Ok(None) => return not_found(&format!("session {} not found", source_id)),
        Err(e) => return server_error(&e.to_string()),
    };
    let fork_id = body
        .get("id")
        .or_else(|| body.get("session_id"))
        .and_then(|v| v.as_str())
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
        .unwrap_or_else(|| {
            format!(
                "api_{}_{}",
                now_secs() as u64,
                &uuid::Uuid::new_v4().simple().to_string()[..8]
            )
        });
    if fork_id.contains(['\r', '\n', '\0']) {
        return bad_request("Invalid session ID", Some("invalid_session_id"));
    }
    match state.store.get_session_row(&fork_id) {
        Ok(Some(_)) => {
            return (
                StatusCode::CONFLICT,
                Json(json!({"error": {"message": format!("Session already exists: {}", fork_id), "type": "invalid_request_error", "code": "session_exists"}})),
            )
                .into_response()
        }
        Err(e) => return server_error(&e.to_string()),
        Ok(None) => {}
    }
    if let Err(e) = state.store.end_session(&source_id, "branched") {
        return server_error(&e.to_string());
    }
    if let Err(e) = state.store.create_named_session(
        &fork_id,
        "gateway",
        source.model.as_deref(),
        Some(&source_id),
    ) {
        return server_error(&e.to_string());
    }
    match state.store.load_messages(&source_id) {
        Ok(messages) => {
            for message in &messages {
                if let Err(e) = state.store.append_message(&fork_id, message) {
                    return server_error(&e.to_string());
                }
            }
        }
        Err(e) => return server_error(&e.to_string()),
    }
    let title = body
        .get("title")
        .and_then(|v| v.as_str())
        .map(|v| v.to_string())
        .unwrap_or_else(|| format!("{} fork", source.title.as_deref().unwrap_or("fork")));
    if let Err(e) = state.store.set_session_title(&fork_id, &title) {
        return bad_request(&e.to_string(), Some("invalid_title"));
    }
    match state.store.get_session_row(&fork_id) {
        Ok(Some(row)) => (
            StatusCode::CREATED,
            Json(json!({"object": "ulnclaw.session", "session": row})),
        )
            .into_response(),
        Ok(None) => server_error("fork created but not found"),
        Err(e) => server_error(&e.to_string()),
    }
}

// ---------------------------------------------------------------------------
// Cron jobs API (/api/jobs — hermes `_handle_*_job` parity)
// ---------------------------------------------------------------------------

const MAX_JOB_NAME_LENGTH: usize = 200;
const MAX_JOB_PROMPT_LENGTH: usize = 5000;

fn jobs_error(status: StatusCode, message: &str) -> Response {
    (status, Json(json!({"error": message}))).into_response()
}

fn cron_store(state: &GatewayState) -> std::result::Result<Arc<CronStore>, Response> {
    state.cron.get().cloned().ok_or_else(|| {
        jobs_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "cron jobs are not enabled on this gateway",
        )
    })
}

fn job_value(job: &CronJob) -> Value {
    serde_json::to_value(job).unwrap_or(Value::Null)
}

#[derive(Deserialize)]
struct JobsQuery {
    #[serde(default)]
    include_disabled: Option<String>,
}

async fn list_jobs(
    State(state): State<Arc<GatewayState>>,
    Query(query): Query<JobsQuery>,
) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let include_disabled = query
        .include_disabled
        .map(|v| matches!(v.to_lowercase().as_str(), "true" | "1"))
        .unwrap_or(false);
    match store.list() {
        Ok(jobs) => {
            let jobs: Vec<Value> = jobs
                .into_iter()
                .filter(|job| include_disabled || job.enabled)
                .map(|job| job_value(&job))
                .collect();
            Json(json!({"jobs": jobs})).into_response()
        }
        Err(e) => server_error(&e.to_string()),
    }
}

#[derive(Deserialize, Default)]
struct CreateJobRequest {
    #[serde(default)]
    name: Option<String>,
    #[serde(default)]
    schedule: Option<String>,
    #[serde(default)]
    prompt: Option<String>,
    /// `Value` (not `String`): hermes accepts lists here too and
    /// `_normalize_deliver_value` flattens them to a comma list.
    #[serde(default)]
    deliver: Option<Value>,
    #[serde(default)]
    skills: Option<Vec<String>>,
    #[serde(default)]
    repeat: Option<i64>,
    /// P708: per-job delivery-mirror override (hermes
    /// `attach_to_session`).
    #[serde(default)]
    attach_to_session: Option<bool>,
}

fn validate_job_fields(name: &str, prompt: &str) -> std::result::Result<(), Response> {
    if name.is_empty() {
        return Err(jobs_error(StatusCode::BAD_REQUEST, "Name is required"));
    }
    if name.chars().count() > MAX_JOB_NAME_LENGTH {
        return Err(jobs_error(
            StatusCode::BAD_REQUEST,
            &format!("Name must be ≤ {} characters", MAX_JOB_NAME_LENGTH),
        ));
    }
    if prompt.chars().count() > MAX_JOB_PROMPT_LENGTH {
        return Err(jobs_error(
            StatusCode::BAD_REQUEST,
            &format!("Prompt must be ≤ {} characters", MAX_JOB_PROMPT_LENGTH),
        ));
    }
    Ok(())
}

async fn create_job(
    State(state): State<Arc<GatewayState>>,
    Json(request): Json<CreateJobRequest>,
) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let name = request.name.unwrap_or_default().trim().to_string();
    let schedule = request.schedule.unwrap_or_default().trim().to_string();
    let prompt = request.prompt.unwrap_or_default();
    if schedule.is_empty() {
        return jobs_error(StatusCode::BAD_REQUEST, "Schedule is required");
    }
    if let Err(response) = validate_job_fields(&name, &prompt) {
        return response;
    }
    if let Some(repeat) = request.repeat {
        if repeat < 1 {
            return jobs_error(StatusCode::BAD_REQUEST, "Repeat must be a positive integer");
        }
    }
    // `deliver` is stored verbatim (normalized) and resolved at fire
    // time — hermes `create_job` accepts any target string and lets
    // resolution fail soft at run time.
    let deliver = crate::cron::delivery::normalize_deliver_value(request.deliver.as_ref());
    let parsed = match crate::cron::parse_schedule(&schedule) {
        Ok(parsed) => parsed,
        Err(e) => return jobs_error(StatusCode::BAD_REQUEST, &format!("Invalid schedule: {}", e)),
    };
    let job = CronJob {
        id: uuid::Uuid::new_v4().simple().to_string()[..12].to_string(),
        name,
        schedule,
        prompt,
        skills: request.skills.unwrap_or_default(),
        enabled: true,
        repeat: request.repeat,
        next_run: crate::cron::next_run(&parsed),
        created_at: now_secs(),
        last_run: None,
        last_status: None,
        deliver: Some(deliver),
        origin: None,
        last_delivery_error: None,
        attach_to_session: request.attach_to_session,
    };
    match store.add(&job) {
        Ok(()) => Json(json!({"job": job_value(&job)})).into_response(),
        Err(e) => server_error(&e.to_string()),
    }
}

#[derive(Deserialize)]
struct InstantiateBlueprintRequest {
    blueprint: String,
    #[serde(default)]
    values: std::collections::HashMap<String, String>,
}

/// `GET /api/jobs/blueprints` — automation blueprint catalog (hermes
/// `/api/cron/blueprints` parity): form schemas + ready-to-paste
/// command + human-readable schedule for every curated blueprint.
async fn list_job_blueprints() -> Response {
    let entries: Vec<Value> = crate::cron::blueprints::catalog()
        .iter()
        .map(crate::cron::blueprints::blueprint_catalog_entry)
        .collect();
    Json(json!({ "blueprints": entries })).into_response()
}

/// `POST /api/jobs/blueprints/instantiate` — fill a blueprint's slots
/// and create the cron job (hermes `/api/cron/blueprints/instantiate`
/// parity). Slot-validation errors return 422 with the field message.
async fn instantiate_job_blueprint(
    State(state): State<Arc<GatewayState>>,
    Json(request): Json<InstantiateBlueprintRequest>,
) -> Response {
    let blueprint = match crate::cron::blueprints::get_blueprint(&request.blueprint) {
        Some(bp) => bp,
        None => {
            return jobs_error(
                StatusCode::NOT_FOUND,
                &format!("Unknown blueprint: {}", request.blueprint),
            )
        }
    };
    let filled = match crate::cron::blueprints::fill_blueprint(&blueprint, &request.values) {
        Ok(filled) => filled,
        Err(e) => return jobs_error(StatusCode::UNPROCESSABLE_ENTITY, &e),
    };
    if let Err(response) = validate_job_fields(&filled.name, &filled.prompt) {
        return response;
    }
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let deliver_value = Value::String(filled.deliver.clone());
    let deliver = crate::cron::delivery::normalize_deliver_value(Some(&deliver_value));
    let parsed = match crate::cron::parse_schedule(&filled.schedule) {
        Ok(parsed) => parsed,
        Err(e) => return jobs_error(StatusCode::BAD_REQUEST, &format!("Invalid schedule: {}", e)),
    };
    let job = CronJob {
        id: uuid::Uuid::new_v4().simple().to_string()[..12].to_string(),
        name: filled.name,
        schedule: filled.schedule,
        prompt: filled.prompt,
        skills: filled.skills,
        enabled: true,
        repeat: None,
        next_run: crate::cron::next_run(&parsed),
        created_at: now_secs(),
        last_run: None,
        last_status: None,
        deliver: Some(deliver),
        origin: None,
        last_delivery_error: None,
        attach_to_session: None,
    };
    match store.add(&job) {
        Ok(()) => Json(json!({ "job": job_value(&job) })).into_response(),
        Err(e) => server_error(&e.to_string()),
    }
}

async fn get_job(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    match store.get(&id) {
        Ok(Some(job)) => Json(json!({"job": job_value(&job)})).into_response(),
        Ok(None) => jobs_error(StatusCode::NOT_FOUND, "Job not found"),
        Err(e) => server_error(&e.to_string()),
    }
}

async fn update_job(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Json(body): Json<Value>,
) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let mut job = match store.get(&id) {
        Ok(Some(job)) => job,
        Ok(None) => return jobs_error(StatusCode::NOT_FOUND, "Job not found"),
        Err(e) => return server_error(&e.to_string()),
    };
    let Some(obj) = body.as_object() else {
        return jobs_error(StatusCode::BAD_REQUEST, "body must be a JSON object");
    };
    // Whitelist of mutable fields (hermes blocks only the immutable
    // fields; this port whitelists the mutable ones, incl. `deliver`
    // since P219 persists it).
    let allowed = [
        "name",
        "schedule",
        "prompt",
        "skills",
        "repeat",
        "enabled",
        "deliver",
        "attach_to_session",
    ];
    let updates: Vec<(&String, &Value)> = obj
        .iter()
        .filter(|(key, _)| allowed.contains(&key.as_str()))
        .collect();
    if updates.is_empty() {
        return jobs_error(StatusCode::BAD_REQUEST, "No valid fields to update");
    }
    for (key, value) in updates {
        match key.as_str() {
            "name" => {
                let name = value.as_str().unwrap_or("").trim().to_string();
                if let Err(response) = validate_job_fields(&name, &job.prompt) {
                    return response;
                }
                job.name = name;
            }
            "prompt" => {
                let prompt = value.as_str().unwrap_or("").to_string();
                if let Err(response) = validate_job_fields(&job.name, &prompt) {
                    return response;
                }
                job.prompt = prompt;
            }
            "schedule" => {
                let schedule = value.as_str().unwrap_or("").trim().to_string();
                if schedule.is_empty() {
                    return jobs_error(StatusCode::BAD_REQUEST, "Schedule is required");
                }
                match crate::cron::parse_schedule(&schedule) {
                    Ok(parsed) => {
                        job.next_run = crate::cron::next_run(&parsed);
                        job.schedule = schedule;
                    }
                    Err(e) => {
                        return jobs_error(
                            StatusCode::BAD_REQUEST,
                            &format!("Invalid schedule: {}", e),
                        )
                    }
                }
            }
            "skills" => {
                if let Some(list) = value.as_array() {
                    job.skills = list
                        .iter()
                        .filter_map(|v| v.as_str().map(String::from))
                        .collect();
                }
            }
            "repeat" => match value {
                Value::Null => job.repeat = None,
                Value::Number(n) if n.as_i64().map(|v| v >= 1).unwrap_or(false) => {
                    job.repeat = n.as_i64();
                }
                _ => {
                    return jobs_error(StatusCode::BAD_REQUEST, "Repeat must be a positive integer")
                }
            },
            "enabled" => {
                if let Some(flag) = value.as_bool() {
                    job.enabled = flag;
                    if flag {
                        if let Ok(parsed) = crate::cron::parse_schedule(&job.schedule) {
                            job.next_run = crate::cron::next_run(&parsed);
                        }
                    } else {
                        job.next_run = None;
                    }
                }
            }
            "deliver" => {
                let deliver = crate::cron::delivery::normalize_deliver_value(Some(value));
                job.deliver = Some(deliver);
            }
            "attach_to_session" => match value {
                Value::Null => job.attach_to_session = None,
                Value::Bool(flag) => job.attach_to_session = Some(*flag),
                _ => {
                    return jobs_error(
                        StatusCode::BAD_REQUEST,
                        "attach_to_session must be a boolean",
                    )
                }
            },
            _ => {}
        }
    }
    match store.update(&job) {
        Ok(()) => Json(json!({"job": job_value(&job)})).into_response(),
        Err(e) => server_error(&e.to_string()),
    }
}

async fn delete_job(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    match store.remove(&id) {
        Ok(true) => Json(json!({"ok": true})).into_response(),
        Ok(false) => jobs_error(StatusCode::NOT_FOUND, "Job not found"),
        Err(e) => server_error(&e.to_string()),
    }
}

async fn set_job_enabled(state: &GatewayState, id: &str, enabled: bool) -> Response {
    let store = match cron_store(state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let mut job = match store.get(id) {
        Ok(Some(job)) => job,
        Ok(None) => return jobs_error(StatusCode::NOT_FOUND, "Job not found"),
        Err(e) => return server_error(&e.to_string()),
    };
    job.enabled = enabled;
    job.next_run = if enabled {
        crate::cron::parse_schedule(&job.schedule)
            .ok()
            .and_then(|parsed| crate::cron::next_run(&parsed))
    } else {
        None
    };
    match store.update(&job) {
        Ok(()) => Json(json!({"job": job_value(&job)})).into_response(),
        Err(e) => server_error(&e.to_string()),
    }
}

async fn pause_job(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    set_job_enabled(&state, &id, false).await
}

async fn resume_job(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    set_job_enabled(&state, &id, true).await
}

/// `GET /api/jobs/:id/runs` — tracked-run history of one cron job
/// (P674 — hermes `GET /api/cron/jobs/:id/runs` parity over the live
/// run registry). Newest first, `?limit=N` (default 20, max 200).
async fn job_runs(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Query(params): Query<std::collections::HashMap<String, String>>,
) -> Response {
    let limit = params
        .get("limit")
        .and_then(|raw| raw.parse::<usize>().ok())
        .unwrap_or(20)
        .clamp(1, 200);
    let runs = state.runs.lock().await;
    let mut matches: Vec<&RunState> = runs
        .values()
        .filter(|run| run.job_id.as_deref() == Some(id.as_str()))
        .collect();
    matches.sort_by(|a, b| {
        b.created_at
            .partial_cmp(&a.created_at)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    matches.truncate(limit);
    Json(json!({ "runs": matches })).into_response()
}

/// One suggestion the desktop accepted/dismissed (P673).
#[derive(Deserialize)]
struct SuggestionReferenceRequest {
    reference: String,
}

/// `GET /api/jobs/suggestions` — pending automation suggestions
/// (hermes suggestions surface parity; P673).
async fn list_job_suggestions() -> Response {
    let store = crate::cron::suggestions::SuggestionStore::open_default();
    let pending = store.list_pending();
    Json(json!({ "suggestions": pending })).into_response()
}

/// `POST /api/jobs/suggestions/accept` — schedule a pending suggestion
/// into the shared cron store (P673). 404 when nothing matches.
async fn accept_job_suggestion(Json(request): Json<SuggestionReferenceRequest>) -> Response {
    let store = crate::cron::suggestions::SuggestionStore::open_default();
    match store.accept(&request.reference) {
        Ok(Some(job)) => Json(json!({
            "scheduled": true,
            "job_id": job.id,
            "name": job.name,
            "schedule": job.schedule,
        }))
        .into_response(),
        Ok(None) => jobs_error(
            StatusCode::NOT_FOUND,
            &format!("No pending suggestion matches '{}'", request.reference),
        ),
        Err(e) => jobs_error(StatusCode::UNPROCESSABLE_ENTITY, &e),
    }
}

/// `POST /api/jobs/suggestions/dismiss` — dismiss a pending suggestion
/// so it is never re-offered (P673). 404 when nothing matches.
async fn dismiss_job_suggestion(Json(request): Json<SuggestionReferenceRequest>) -> Response {
    let store = crate::cron::suggestions::SuggestionStore::open_default();
    if store.dismiss(&request.reference) {
        Json(json!({ "dismissed": true })).into_response()
    } else {
        jobs_error(
            StatusCode::NOT_FOUND,
            &format!("No pending suggestion matches '{}'", request.reference),
        )
    }
}

/// `POST /api/jobs/suggestions/catalog` — seed the curated starter
/// catalog (P673); returns the newly added titles.
async fn seed_job_suggestion_catalog() -> Response {
    let store = crate::cron::suggestions::SuggestionStore::open_default();
    let created = crate::cron::suggestions::seed_catalog_suggestions(&store);
    let titles: Vec<String> = created
        .iter()
        .map(|suggestion| suggestion.title.clone())
        .collect();
    Json(json!({ "created": titles })).into_response()
}

/// `POST /api/jobs/suggestions/clear` — drop resolved (accepted)
/// records; dismissed ones stay for their dedup keys (P673).
async fn clear_job_suggestions() -> Response {
    let store = crate::cron::suggestions::SuggestionStore::open_default();
    let removed = store.clear_resolved();
    Json(json!({ "removed": removed })).into_response()
}

/// `GET /api/jobs/delivery-targets` — delivery targets the dropdown
/// should offer (hermes `GET /api/cron/delivery-targets`): always the
/// implicit `local` option plus every connected gateway platform, with
/// `home_target_set` so the UI can prompt for a home channel.
async fn job_delivery_targets() -> Response {
    let mut targets = vec![json!({
        "id": "local",
        "name": "Local (save only)",
        "home_target_set": true,
        "home_env_var": Value::Null,
    })];
    let config = crate::config::UlncLawConfig::load(None).unwrap_or_default();
    let connected = crate::cron::delivery::connected_messaging_platforms(&config.messaging);
    targets.extend(crate::cron::delivery::cron_delivery_targets(&connected));
    Json(json!({ "targets": targets })).into_response()
}

/// `POST /api/jobs/fire` — Chronos managed-cron fire webhook (NAS →
/// agent), hermes `POST /api/cron/fire` parity. Authenticated by a
/// short-lived NAS-minted JWT (the route is public — the JWT is the
/// gate, not the gateway bearer key). Verifies, claims the job, returns
/// 202 immediately and runs the job in the background so a long agent
/// turn never trips NAS's HTTP timeout.
async fn fire_job(
    State(state): State<Arc<GatewayState>>,
    headers: HeaderMap,
    body: axum::body::Bytes,
) -> Response {
    let token = headers
        .get("authorization")
        .and_then(|value| value.to_str().ok())
        .map(|value| {
            value
                .trim()
                .strip_prefix("Bearer ")
                .unwrap_or(value.trim())
                .to_string()
        })
        .unwrap_or_default();
    let config = crate::config::UlncLawConfig::load(None).unwrap_or_default();
    let chronos = &config.cron.chronos;
    let claims = crate::cron::chronos::verify_fire_token(
        &token,
        chronos.expected_audience.as_deref().unwrap_or(""),
        chronos.nas_jwks_url.as_deref(),
        chronos.portal_url.as_deref(),
        30,
    )
    .await;
    if claims.is_none() {
        return jobs_error(StatusCode::UNAUTHORIZED, "invalid fire token");
    }
    let payload: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
    let job_id = payload
        .get("job_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty());
    let Some(job_id) = job_id else {
        return jobs_error(StatusCode::BAD_REQUEST, "missing job_id");
    };
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let mut job = match store.get(job_id) {
        Ok(Some(job)) => job,
        // Job is gone (cancelled / completed) — nothing to fire. 200 so
        // NAS does not retry a fire that is intentionally absent.
        Ok(None) => return Json(json!({ "status": "gone", "job_id": job_id })).into_response(),
        Err(e) => return server_error(&e.to_string()),
    };
    // CAS claim: a NAS retry that lands while the previous fire is still
    // running is accepted but not double-dispatched.
    if !take_fire_claim(job_id) {
        return Json(json!({ "status": "accepted", "job_id": job_id })).into_response();
    }
    if job.prompt.trim().is_empty() {
        release_fire_claim(job_id);
        return jobs_error(StatusCode::BAD_REQUEST, "Job has no prompt to run");
    }
    match spawn_job_run(state.clone(), &mut job, store).await {
        Some(_) => (
            StatusCode::ACCEPTED,
            Json(json!({ "status": "accepted", "job_id": job_id })),
        )
            .into_response(),
        None => {
            release_fire_claim(job_id);
            server_error("failed to start job run")
        }
    }
}

/// `POST /api/jobs/:id/run` — trigger one immediate execution as a tracked
/// run (hermes `_handle_run_job`).
async fn run_job_now(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let store = match cron_store(&state) {
        Ok(store) => store,
        Err(response) => return response,
    };
    let mut job = match store.get(&id) {
        Ok(Some(job)) => job,
        Ok(None) => return jobs_error(StatusCode::NOT_FOUND, "Job not found"),
        Err(e) => return server_error(&e.to_string()),
    };
    if job.prompt.trim().is_empty() {
        return jobs_error(StatusCode::BAD_REQUEST, "Job has no prompt to run");
    }
    let Some(run_id) = spawn_job_run(state.clone(), &mut job, store).await else {
        return server_error("failed to start job run");
    };
    Json(json!({"job": job_value(&job), "run_id": run_id})).into_response()
}

/// In-flight Chronos fire claims (hermes store CAS claim): dedupes a
/// NAS retry that arrives while a previous fire of the same job is
/// still running.
fn fire_claims() -> &'static std::sync::Mutex<std::collections::HashSet<String>> {
    static CLAIMS: std::sync::OnceLock<std::sync::Mutex<std::collections::HashSet<String>>> =
        std::sync::OnceLock::new();
    CLAIMS.get_or_init(|| std::sync::Mutex::new(std::collections::HashSet::new()))
}

/// Take the fire claim for a job. Returns false when a fire is already
/// in flight for it.
fn take_fire_claim(job_id: &str) -> bool {
    fire_claims()
        .lock()
        .map(|mut claims| claims.insert(job_id.to_string()))
        .unwrap_or(true)
}

fn release_fire_claim(job_id: &str) {
    if let Ok(mut claims) = fire_claims().lock() {
        claims.remove(job_id);
    }
}

/// Deliver one cron job's final response to its resolved targets (hermes
/// `_deliver_result`, live-adapter lane): wraps the content when
/// configured, strips `MEDIA:` tags (senders are text-only), and sends
/// via each platform's registered sender. Returns None on success /
/// nothing-to-deliver, or an error string.
async fn deliver_job_result(
    store: &crate::session::SqliteSessionStore,
    job: &CronJob,
    content: &str,
    wrap_response: bool,
) -> Option<String> {
    let targets = crate::cron::delivery::resolve_delivery_targets(job);
    if targets.is_empty() {
        let deliver = crate::cron::delivery::normalize_deliver_value(
            job.deliver
                .as_ref()
                .map(|deliver| Value::String(deliver.clone()))
                .as_ref(),
        );
        if deliver == "local" {
            return None; // local-only jobs don't deliver — not a failure
        }
        // deliver=origin with no resolvable origin and no configured
        // home channels: treat as local rather than reporting an error
        // (hermes #43014) — output stays in the run/session.
        if deliver == "origin" {
            return None;
        }
        return Some(format!(
            "no delivery target resolved for deliver={}",
            deliver
        ));
    }
    let body = if wrap_response {
        crate::cron::delivery::wrap_delivery_content(job, content)
    } else {
        content.to_string()
    };
    let (cleaned, _media) = crate::messaging::extract_media_tags(&body);
    // P708: delivery-mirror gate (hermes `_cron_mirror_delivery_enabled`,
    // default off). When on, each successful delivery to the job's OWN
    // origin conversation is also appended to that chat's session
    // transcript so the next reply there sees the cron output in
    // context — fan-out targets are never mirrored (hermes
    // `_target_matches_origin` scoping). Mirror the CLEAN, unwrapped
    // output.
    let mirror_enabled = crate::cron::delivery::mirror_delivery_enabled(
        job,
        &crate::config::UlncLawConfig::load(None)
            .map(|config| config.cron)
            .unwrap_or_default(),
    );
    let mut errors: Vec<String> = Vec::new();
    let session_key = format!("cron-job:{}", job.id);
    for target in targets {
        let key = crate::cron::delivery::sender_key_for(&target.platform);
        // P707: skip targets already proven permanently unreachable
        // (hermes dead-target registry) — re-sending wastes a send
        // against flood control. Reported as a delivery error so the
        // job's last_delivery_error stays observable; a successful
        // send to the target later clears the flag (self-healing).
        if !target.chat_id.trim().is_empty() && crate::dead_targets::is_dead(&key, &target.chat_id)
        {
            tracing::info!(
                "[cron] skipping delivery to known-dead target {}:{} (send to it again to clear)",
                key,
                target.chat_id
            );
            errors.push(format!(
                "target {}:{} previously confirmed unreachable (dead target)",
                key, target.chat_id
            ));
            continue;
        }
        match crate::messaging::platform_sender(&key) {
            Some(sender) => {
                // P700: durable delivery obligation around the send
                // (hermes delivery_ledger) — cron output is exactly the
                // kind of final response a restart must not lose.
                let obligation = crate::delivery_ledger::record_obligation(
                    store,
                    &session_key,
                    &key,
                    &target.chat_id,
                    target.thread_id.as_deref(),
                    &cleaned,
                );
                if let Some(id) = &obligation {
                    crate::delivery_ledger::mark_attempting(store, id);
                }
                sender.send_text(&target.chat_id, &cleaned).await;
                if let Some(id) = &obligation {
                    crate::delivery_ledger::mark_delivered(store, id);
                }
                // P707: successful delivery clears any stale dead flag.
                crate::dead_targets::revive(&key, &target.chat_id);
                // P708: mirror the delivery into the origin chat's
                // session transcript (best-effort, user-role + labelled
                // prefix — hermes `_maybe_mirror_cron_delivery`).
                if mirror_enabled
                    && crate::cron::delivery::target_matches_origin(
                        job.origin.as_ref(),
                        &key,
                        &target.chat_id,
                        target.thread_id.as_deref(),
                    )
                {
                    let job_label = if job.name.trim().is_empty() {
                        job.id.clone()
                    } else {
                        job.name.clone()
                    };
                    let mirrored = crate::mirror::mirror_to_session(
                        store,
                        &key,
                        &target.chat_id,
                        &format!("[Cron delivery: {job_label}]\n{cleaned}"),
                        "cron",
                        crate::provider::Role::User,
                    );
                    if mirrored {
                        tracing::info!(
                            "[cron] mirrored delivery into {}:{} session transcript",
                            key,
                            target.chat_id
                        );
                    }
                }
            }
            None => errors.push(format!(
                "platform '{}' has no registered sender",
                target.platform
            )),
        }
    }
    if errors.is_empty() {
        None
    } else {
        Some(errors.join("; "))
    }
}

/// Dispatch one cron job as a tracked run (shared by `POST /api/jobs/:id/run`,
/// the scheduler, and the Chronos fire webhook): creates the cron-run
/// session + run row, records the outcome back onto the job when the run
/// finishes (incl. external delivery + `last_delivery_error`), and
/// executes the turn inside the cron approval scope. Returns the run id.
async fn spawn_job_run(
    state: Arc<GatewayState>,
    job: &mut CronJob,
    store: Arc<CronStore>,
) -> Option<String> {
    let run_id = uuid::Uuid::new_v4().to_string();
    let session_id = state
        .store
        .create_session("cron-run", Some(&state.model_name), None)
        .unwrap_or_else(|_| uuid::Uuid::new_v4().to_string());
    // P444: tell the desktop shell a cron-run session appeared.
    crate::desktop_bridge::publish(
        "",
        "session.created",
        &json!({"session_id": session_id, "source": "cron-run"}),
    );
    let run = RunState {
        run_id: run_id.clone(),
        status: "running".to_string(),
        session_id: Some(session_id.clone()),
        message: job.prompt.clone(),
        created_at: now_secs(),
        finished_at: None,
        result: None,
        error: None,
        iterations: None,
        stop_requested: false,
        approval: None,
        job_id: Some(job.id.clone()),
    };
    state.runs.lock().await.insert(run_id.clone(), run);
    job.last_run = Some(now_secs());
    job.last_status = Some("running".to_string());
    store.update(job).ok();

    // Record the outcome on the job row once the run finishes, then
    // deliver the final response to the configured target(s) (hermes
    // `run_one_job` delivery block).
    let job_store = Arc::clone(&store);
    let job_snapshot = job.clone();
    let job_id = job.id.clone();
    let runs = state.runs.clone();
    let outcome_run_id = run_id.clone();
    let session_store = state.store.clone();
    tokio::spawn(async move {
        let outcome = loop {
            tokio::time::sleep(std::time::Duration::from_millis(500)).await;
            let snapshot = runs
                .lock()
                .await
                .get(&outcome_run_id)
                .map(|run| (run.status.clone(), run.error.clone(), run.result.clone()));
            match snapshot {
                None => break ("failed".to_string(), Some("run lost".to_string()), None),
                Some((status, error, result))
                    if matches!(status.as_str(), "completed" | "failed") =>
                {
                    break (status, error, result)
                }
                Some(_) => continue,
            }
        };
        let (status, mut run_error, result) = outcome;
        let mut success = status == "completed";
        // Empty final responses are a soft failure (hermes #8585): the
        // agent ran but produced nothing useful.
        let result_text = result.unwrap_or_default();
        if success && result_text.trim().is_empty() {
            success = false;
            run_error = Some(
                "Agent completed but produced empty response (model error, timeout, or misconfiguration)"
                    .to_string(),
            );
        }
        // Failed jobs deliver a compact failure summary; successful jobs
        // deliver the response unless it is a silence marker (hermes
        // `_is_cron_silence_response`).
        let wrap_response = crate::config::UlncLawConfig::load(None)
            .map(|config| config.cron.wrap_response)
            .unwrap_or(true);
        let mut delivery_error: Option<String> = None;
        if success {
            if !crate::cron::delivery::is_cron_silence_response(&result_text) {
                delivery_error =
                    deliver_job_result(&session_store, &job_snapshot, &result_text, wrap_response)
                        .await;
            }
        } else {
            let summary = crate::cron::delivery::summarize_cron_failure_for_delivery(
                &job_snapshot,
                run_error.as_deref(),
            );
            if !summary.trim().is_empty() {
                delivery_error =
                    deliver_job_result(&session_store, &job_snapshot, &summary, wrap_response)
                        .await;
            }
        }
        let delivery_failed = delivery_error.is_some();
        if let Ok(Some(mut job)) = job_store.get(&job_id) {
            job.last_status = Some(match (success, &run_error) {
                (true, _) => "ok".to_string(),
                (false, Some(error)) => format!("error: {}", error),
                (false, None) => format!("error: {}", status),
            });
            job.last_delivery_error = delivery_error;
            job_store.update(&job).ok();
        }
        release_fire_claim(&job_id);

        // Content-free cron execution lifecycle projection (hermes
        // CronExecutionEvent) — monitoring egress only.
        crate::monitoring::emit(
            crate::monitoring::CronExecutionEvent {
                status: if success {
                    "ok".to_string()
                } else {
                    "error".to_string()
                },
                job_key: job_id.clone(),
                source: job_snapshot
                    .origin
                    .as_ref()
                    .map(|o| format!("platform:{}", o.platform))
                    .unwrap_or_else(|| "cron".to_string()),
                duration_ms: None,
                delivery_outcome: Some(if delivery_failed {
                    "failed".to_string()
                } else {
                    "ok".to_string()
                }),
                error_class: run_error.as_ref().map(|_| "agent_error".to_string()),
                ts_ns: crate::monitoring::now_ns(),
            }
            .to_value(),
        );
    });

    spawn_tracked_run(state, run_id.clone(), session_id, job.prompt.clone(), true);
    Some(run_id)
}

/// Provider factory used by the dispatcher's auto-decompose tick (the
/// binary builds it from live config so `main.rs`' provider wiring is
/// reused without a library dependency on the CLI).
pub type DispatcherProviderFactory = std::sync::Arc<
    dyn Fn() -> std::result::Result<std::sync::Arc<dyn crate::provider::Provider>, String>
        + Send
        + Sync,
>;

/// Try to take the exclusive, non-blocking dispatcher lock at `path`
/// (hermes `_acquire_singleton_lock`). The returned handle must stay
/// open for as long as this process dispatches; dropping it releases
/// the lock.
fn try_acquire_dispatcher_lock_at(path: &std::path::Path) -> Option<std::fs::File> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).ok()?;
    }
    let file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .ok()?;
    // Non-blocking exclusive lock (flock / LockFileEx); dropping
    // the file releases it.
    crate::process_ctl::try_lock_exclusive(&file).ok()?;
    Some(file)
}

/// Start the embedded kanban dispatcher loop (hermes hosts the dispatcher
/// in the gateway, ticking every 60 s by default): auto-decompose fresh
/// triage tasks, reclaim stale claims, promote parent-done todos, spawn
/// detached workers for ready tasks.
///
/// Only one gateway process machine-wide runs the dispatcher: an
/// exclusive advisory lock next to `kanban.db` is the backstop that
/// survives config drift and restart races (hermes singleton lock —
/// concurrent dispatchers double reclaim frequency and claim events).
///
/// The `[kanban] auto_decompose` toggle is re-read from config EVERY
/// tick (hermes #49638): it is a safety switch — flipping it off must
/// stop a runaway fan-out on the next tick, not on gateway restart. A
/// config read failure fails safe (no auto-decompose that tick).
pub fn spawn_kanban_dispatcher(
    interval_secs: u64,
    max_spawn: usize,
    use_worktrees: bool,
    provider_factory: Option<DispatcherProviderFactory>,
) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let lock_path = crate::config::ulnclaw_home()
            .join("kanban")
            .join("dispatcher.lock");
        // Held for the loop's lifetime; dropping releases the lock.
        let _lock_guard = match try_acquire_dispatcher_lock_at(&lock_path) {
            Some(handle) => handle,
            None => {
                tracing::warn!(
                    "kanban dispatcher: another gateway holds {lock_path:?};                      this process will not dispatch (dispatch_in_gateway backstop)"
                );
                return;
            }
        };
        let mut interval =
            tokio::time::interval(std::time::Duration::from_secs(interval_secs.max(5)));
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        // Health telemetry (hermes HEALTH_WINDOW): warn when spawnable
        // ready work keeps waiting but nothing spawns, throttled to
        // 300 s. Claim-pulled lanes don't count (has_spawnable_ready).
        const HEALTH_WINDOW: u32 = 6;
        let mut bad_ticks: u32 = 0;
        let mut last_warn_at: i64 = 0;
        loop {
            interval.tick().await;
            auto_decompose_tick(provider_factory.as_ref()).await;
            let tick_outcome = tokio::task::spawn_blocking(move || -> Option<(usize, bool)> {
                let Ok(store) = crate::kanban::KanbanStore::open_default() else {
                    return None;
                };
                let home = crate::config::ulnclaw_home();
                // Live re-read so [kanban] stale_timeout_seconds edits
                // take effect without a gateway restart.
                let config = crate::config::UlncLawConfig::load(None).unwrap_or_default();
                let stale_timeout = config.kanban.stale_timeout_seconds;
                let known_profiles: std::collections::HashSet<String> =
                    config.profiles.keys().cloned().collect();
                match store.dispatch_once(
                    &home,
                    use_worktrees,
                    |task, workspace| crate::kanban::dispatch_spawn(&home, task, workspace),
                    Some(max_spawn.max(1)),
                    false,
                    2,
                    stale_timeout,
                    Some(&known_profiles),
                    config.kanban.max_in_progress_per_profile,
                    config.kanban.max_in_progress,
                ) {
                    Ok(result) => {
                        if !result.spawned.is_empty() || !result.reclaimed.is_empty() {
                            tracing::info!(
                                "kanban dispatch: {} reclaimed, {} promoted, {} spawned",
                                result.reclaimed.len(),
                                result.promoted.len(),
                                result.spawned.len()
                            );
                        }
                        // Hermes health probe: only count work the
                        // dispatcher would actually spawn (unknown
                        // assignees are claim-pulled lanes, correctly
                        // idle — not stuck).
                        let ready_pending = store
                            .has_spawnable_ready(Some(&known_profiles))
                            .unwrap_or(false)
                            || store
                                .has_spawnable_review(Some(&known_profiles))
                                .unwrap_or(false);
                        Some((result.spawned.len(), ready_pending))
                    }
                    Err(e) => {
                        tracing::warn!("kanban dispatch tick failed: {e}");
                        None
                    }
                }
            })
            .await;
            if let Ok(Some((spawned, ready_pending))) = tick_outcome {
                if ready_pending && spawned == 0 {
                    bad_ticks += 1;
                } else {
                    bad_ticks = 0;
                }
                if bad_ticks >= HEALTH_WINDOW {
                    let now = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_secs() as i64)
                        .unwrap_or(0);
                    if now - last_warn_at >= 300 {
                        tracing::warn!(
                            "kanban dispatcher stuck: spawnable ready tasks waiting for                              {bad_ticks} consecutive ticks but 0 workers spawned.                              Check profile health (binary, PATH, credentials) and                              `ulnclaw kanban list --status ready`."
                        );
                        last_warn_at = now;
                    }
                }
            }
        }
    })
}

/// One auto-decompose pass (hermes `_auto_decompose_tick`): turn fresh
/// triage tasks into ready workgraphs before the dispatcher fans out
/// workers. Capped by `auto_decompose_per_tick` so a bulk load of triage
/// tasks does not burst-spend the auxiliary LLM in one tick; the
/// remainder defers to subsequent ticks.
async fn auto_decompose_tick(provider_factory: Option<&DispatcherProviderFactory>) {
    // Fail safe: a config read error disables auto-decompose for this
    // tick rather than falling back to burst-prone defaults (hermes
    // _resolve_auto_decompose_settings).
    let Ok(config) = crate::config::UlncLawConfig::load(None) else {
        return;
    };
    if !config.kanban.auto_decompose {
        return;
    }
    let Some(factory) = provider_factory else {
        return;
    };
    let provider = match factory() {
        Ok(provider) => provider,
        Err(e) => {
            tracing::debug!("kanban auto-decompose: provider unavailable ({e})");
            return;
        }
    };
    let Ok(store) = crate::kanban::KanbanStore::open_default() else {
        return;
    };
    let triage_ids = match crate::kanban_triage::list_triage_ids(&store) {
        Ok(ids) => ids,
        Err(e) => {
            tracing::debug!("kanban auto-decompose: list_triage_ids failed ({e})");
            return;
        }
    };
    let per_tick = config.kanban.auto_decompose_per_tick.max(1);
    for task_id in triage_ids.into_iter().take(per_tick) {
        let outcome = crate::kanban_triage::decompose_task(
            &store,
            &config,
            provider.clone(),
            &task_id,
            Some("auto-decomposer"),
        )
        .await;
        if outcome.ok {
            match &outcome.child_ids {
                Some(children) if outcome.fanout => {
                    tracing::info!(
                        "kanban auto-decompose: {task_id} → {} children",
                        children.len()
                    );
                }
                _ => {
                    tracing::info!("kanban auto-decompose: {task_id} → single task (no fanout)");
                }
            }
        } else {
            // Common no-op reasons (no aux client configured) must not
            // spam logs every tick (hermes logs them at debug).
            tracing::debug!(
                "kanban auto-decompose: {task_id} skipped: {}",
                outcome.reason
            );
        }
    }
}

/// Terminal event kinds delivered to notify subscribers (hermes
/// `TERMINAL_KINDS`). `archived` / `unblocked` are claimed (cursor
/// advances past them so they can't wedge a later completed/blocked
/// event behind an unclaimed row) but intentionally silent.
const NOTIFY_TERMINAL_KINDS: &[&str] = &[
    "completed",
    "blocked",
    "gave_up",
    "crashed",
    "timed_out",
    "status",
    "archived",
    "unblocked",
];

/// Start the kanban notification delivery loop (hermes kanban notifier):
/// every 5 s, poll `kanban_notify_subs`, deliver unseen terminal events
/// to each subscribed chat via the registered platform sender, advance
/// the subscription cursor after delivery, and drop the subscription
/// once the task reaches a truly final status (done / archived).
/// Gateway chat entry point targeted by the kanban wake self-post
/// (hermes wake routing needs the in-process API server's bind + key).
#[derive(Debug, Clone)]
pub struct WakeEndpoint {
    pub host: String,
    pub port: u16,
    pub key: Option<String>,
}

/// A wake self-post runs an entire agent turn synchronously
/// (stream=false); generous ceiling so long tool-using turns are not
/// killed mid-flight (hermes `WAKE_TURN_TIMEOUT_SECONDS`).
const WAKE_TURN_TIMEOUT_SECONDS: u64 = 600;

/// Backoff between retries on transient failures (429 concurrency cap,
/// connection errors) — hermes `_RETRY_DELAYS_SECONDS`.
const WAKE_RETRY_DELAYS_SECONDS: [u64; 3] = [2, 5, 10];

/// Wake the creator session by self-POSTing the wake text to the
/// gateway's own `/v1/chat/completions` with the raw session id in
/// `X-Ulnclaw-Session-Id` — the exact entry point real turns use, so
/// the wake resumes the REAL session with full history (hermes
/// `_self_post_chat_completion`). Errors are returned so the caller
/// logs instead of silently losing the event.
pub async fn deliver_session_wake(
    endpoint: &WakeEndpoint,
    session_id: &str,
    text: &str,
) -> std::result::Result<(), String> {
    let mut host = endpoint.host.clone();
    if host == "0.0.0.0" || host == "::" || host == "*" {
        // Wildcard bind — connect over loopback.
        host = "127.0.0.1".to_string();
    }
    if host.contains(':') && !host.starts_with('[') {
        host = format!("[{host}]"); // bare IPv6 literal
    }
    let url = format!("http://{host}:{}/v1/chat/completions", endpoint.port);
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(WAKE_TURN_TIMEOUT_SECONDS))
        .build()
        .map_err(|e| format!("wake http client: {e}"))?;
    let mut last_err = String::new();
    let attempts = 1 + WAKE_RETRY_DELAYS_SECONDS.len();
    for attempt in 0..attempts {
        if attempt > 0 {
            tokio::time::sleep(std::time::Duration::from_secs(
                WAKE_RETRY_DELAYS_SECONDS[attempt - 1],
            ))
            .await;
        }
        let mut request = client
            .post(&url)
            .header("X-Ulnclaw-Session-Id", session_id)
            .json(&serde_json::json!({
                "model": "ulnclaw",
                "messages": [{ "role": "user", "content": text }],
                "stream": false
            }));
        if let Some(key) = endpoint.key.as_deref().filter(|k| !k.is_empty()) {
            request = request.bearer_auth(key);
        }
        match request.send().await {
            Ok(response) => {
                let status = response.status();
                if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
                    last_err = format!(
                        "wake self-post got HTTP 429 (concurrency cap) \
                         for session {session_id}"
                    );
                    tracing::warn!("{last_err}; attempt {}/{}", attempt + 1, attempts);
                    continue;
                }
                if status.is_client_error() || status.is_server_error() {
                    let body = response.text().await.unwrap_or_default();
                    let body: String = body.chars().take(300).collect();
                    return Err(format!(
                        "wake self-post failed for session {session_id}: \
                         HTTP {status}: {body}"
                    ));
                }
                tracing::info!(
                    "kanban notifier: wake delivered for session {session_id} \
                     (attempt {})",
                    attempt + 1
                );
                return Ok(());
            }
            Err(e) => {
                last_err =
                    format!("wake self-post transient failure for session {session_id}: {e}");
                tracing::warn!("{last_err} (attempt {}/{})", attempt + 1, attempts);
            }
        }
    }
    Err(format!(
        "wake self-post gave up for session {session_id} after \
         {attempts} attempts: {last_err}"
    ))
}

pub fn spawn_kanban_notifier(wake: Option<WakeEndpoint>) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        // Initial delay so the gateway can finish wiring platform
        // adapters (hermes does the same 5 s wait).
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
        let mut interval = tokio::time::interval(std::time::Duration::from_secs(5));
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            interval.tick().await;
            notifier_tick(wake.as_ref()).await;
        }
    })
}

/// One notifier pass over every subscription.
async fn notifier_tick(wake: Option<&WakeEndpoint>) {
    let Ok(store) = crate::kanban::KanbanStore::open_default() else {
        return;
    };
    let subs = match store.list_notify_subs(None) {
        Ok(subs) => subs,
        Err(e) => {
            tracing::debug!("kanban notifier: list_notify_subs failed ({e})");
            return;
        }
    };
    for sub in subs {
        // No connected adapter for this platform: skip WITHOUT advancing
        // the cursor so events are still delivered once the adapter
        // comes up (hermes rewind semantics).
        let Some(sender) = crate::messaging::platform_sender(&sub.platform) else {
            continue;
        };
        let thread = if sub.thread_id.is_empty() {
            None
        } else {
            Some(sub.thread_id.as_str())
        };
        let (cursor, events) = match store.unseen_events_for_sub(
            &sub.task_id,
            &sub.platform,
            &sub.chat_id,
            thread,
            Some(NOTIFY_TERMINAL_KINDS),
        ) {
            Ok(page) => page,
            Err(e) => {
                tracing::debug!(
                    "kanban notifier: unseen events for {} failed ({e})",
                    sub.task_id
                );
                continue;
            }
        };
        if events.is_empty() {
            continue;
        }
        let task = store.get_task(&sub.task_id).ok().flatten();
        for event in &events {
            let Some(message) = format_notify_message(task.as_ref(), event) else {
                continue; // silent kinds (archived / unblocked)
            };
            // Scoped delivery: PlatformSender has no thread routing or
            // failure channel, so thread_id rides in the subscription
            // row only and sends are assumed delivered.
            sender.send_text(&sub.chat_id, &message).await;
            tracing::debug!(
                "kanban notifier: delivered {} event for {} to {}/{}",
                event.kind,
                sub.task_id,
                sub.platform,
                sub.chat_id
            );
        }
        if let Err(e) =
            store.advance_notify_cursor(&sub.task_id, &sub.platform, &sub.chat_id, thread, cursor)
        {
            tracing::debug!("kanban notifier: cursor advance failed ({e})");
        }
        // Wake routing (hermes): terminal events ALSO resume the
        // creator session recorded on the task. The text ping above was
        // the delivery, so the wake is best-effort and runs detached —
        // a slow agent turn must not stall other subscriptions.
        if let Some(endpoint) = wake {
            if let Some(task) = task.as_ref() {
                if let Some(session_id) = task
                    .session_id
                    .as_deref()
                    .map(str::trim)
                    .filter(|id| !id.is_empty())
                {
                    let present: std::collections::HashSet<&str> = events
                        .iter()
                        .map(|e| e.kind.as_str())
                        .filter(|kind| crate::kanban::WAKE_KINDS.contains(kind))
                        .collect();
                    // Fixed hermes order: completed, gave_up, crashed,
                    // timed_out, blocked.
                    let wake_kinds: Vec<String> = crate::kanban::WAKE_KINDS
                        .iter()
                        .filter(|kind| present.contains(*kind))
                        .map(|kind| kind.to_string())
                        .collect();
                    if !wake_kinds.is_empty() {
                        let text = crate::kanban::wake_message(task, &wake_kinds, &task.board);
                        let session_id = session_id.to_string();
                        let endpoint = endpoint.clone();
                        tokio::spawn(async move {
                            if let Err(e) =
                                deliver_session_wake(&endpoint, &session_id, &text).await
                            {
                                tracing::warn!(
                                    "kanban notifier: wakeup failed for \
                                     {session_id}: {e}"
                                );
                            }
                        });
                    }
                }
            }
        }
        // Subscriptions are removed only when the task reaches a truly
        // final status (done / archived) — crash/retry cycles must keep
        // notifying (hermes policy; the cursor handles dedup).
        if let Some(task) = task.as_ref() {
            if task.status == "done" || task.status == "archived" {
                store
                    .remove_notify_sub(&sub.task_id, &sub.platform, &sub.chat_id, thread)
                    .ok();
            }
        }
    }
}

/// Render one terminal event as a chat message (hermes notifier message
/// formats). Returns `None` for intentionally silent kinds.
fn format_notify_message(
    task: Option<&crate::kanban::Task>,
    event: &crate::kanban::TaskEvent,
) -> Option<String> {
    let board_tag = task.map(|t| format!("[{}] ", t.board)).unwrap_or_default();
    let who_tag = task
        .and_then(|t| t.assignee.as_deref())
        .filter(|a| !a.is_empty())
        .map(|a| format!("@{a} "))
        .unwrap_or_default();
    let task_id = task.map(|t| t.id.as_str()).unwrap_or("?");
    let title: String = task
        .map(|t| t.title.chars().take(120).collect())
        .unwrap_or_default();
    let payload_str = |key: &str, limit: usize| -> Option<String> {
        let s = event.payload.get(key)?.as_str()?;
        let first = s.trim().lines().next().unwrap_or("");
        Some(first.chars().take(limit).collect())
    };
    let message = match event.kind.as_str() {
        "completed" => {
            let handoff = payload_str("summary", 200)
                .or_else(|| payload_str("result", 200))
                .or_else(|| {
                    task.and_then(|t| t.result.as_deref())
                        .map(|r| r.trim().lines().next().unwrap_or("").chars().take(160).collect())
                })
                .map(|h| format!("\n{h}"))
                .unwrap_or_default();
            format!("✔ {board_tag}{who_tag}Kanban {task_id} done — {title}{handoff}")
        }
        "blocked" => {
            let reason = payload_str("reason", 160)
                .map(|r| format!(": {r}"))
                .unwrap_or_default();
            format!("⏸ {board_tag}{who_tag}Kanban {task_id} blocked{reason}")
        }
        "gave_up" => {
            let err = payload_str("error", 200)
                .map(|e| format!("\n{e}"))
                .unwrap_or_default();
            format!("✖ {board_tag}{who_tag}Kanban {task_id} gave up after repeated spawn failures{err}")
        }
        "crashed" => format!(
            "✖ {board_tag}{who_tag}Kanban {task_id} worker crashed (pid gone); dispatcher will retry"
        ),
        "timed_out" => {
            let limit = event
                .payload
                .get("limit_seconds")
                .and_then(|v| v.as_i64())
                .unwrap_or(0);
            format!(
                "⏱ {board_tag}{who_tag}Kanban {task_id} timed out (max_runtime={limit}s); will retry"
            )
        }
        "status" => {
            let new_status = payload_str("status", 40).unwrap_or_default();
            format!("🔄 {board_tag}{who_tag}Kanban {task_id} → {new_status}")
        }
        // archived / unblocked advance the cursor silently.
        _ => return None,
    };
    Some(message)
}

/// Start the cron scheduler loop (hermes scheduler): every `poll_secs`
/// dispatch each due job as a tracked cron run. Called from the gateway
/// command once the cron store is wired; does nothing when absent.
/// Start the monitoring plane (hermes `agent/monitoring` gateway wiring):
/// the OTLP streamer consuming the emitter queue, plus a periodic
/// content-free health sampler. No-op unless
/// `[monitoring] gateway_health_export.enabled` AND `export.otlp.enabled`
/// with an endpoint. Never affects gateway operation (fail-isolated).
pub fn spawn_monitoring(
    state: Arc<GatewayState>,
    config: &crate::config::UlncLawConfig,
    platform_count: u64,
) -> Vec<tokio::task::JoinHandle<()>> {
    let monitoring = &config.monitoring;
    if !monitoring.enabled() || !monitoring.otlp_enabled() {
        return Vec::new();
    }
    let Some(endpoint) = monitoring
        .export
        .otlp
        .endpoint
        .clone()
        .map(|e| e.trim().to_string())
        .filter(|e| !e.is_empty())
    else {
        tracing::warn!("monitoring.gateway_health_export enabled but monitoring.export.otlp.endpoint is not set");
        return Vec::new();
    };

    let install_id = crate::monitoring::ensure_install_id(monitoring.install_id.as_deref());
    let version = env!("CARGO_PKG_VERSION");
    let resource = crate::monitoring::resource_attributes(&install_id, version, None);

    let mut handles = Vec::new();

    // Lifecycle event (hermes gateway_started).
    crate::monitoring::emit(
        crate::monitoring::GatewayHealthEvent {
            name: "gateway_started".to_string(),
            gateway_state: Some("running".to_string()),
            old_state: None,
            new_state: Some("running".to_string()),
            exit_reason: None,
            active_agents: 0,
            gateway_busy: false,
            platform_count,
            profile: None,
            install_id: Some(install_id.clone()),
            version: Some(version.to_string()),
            pid: Some(std::process::id()),
            ts_ns: crate::monitoring::now_ns(),
        }
        .to_value(),
    );

    // Continuous streamer (hermes OTLPStreamer).
    if monitoring.diagnostic_events_enabled() || monitoring.metrics_enabled() {
        let streamer_endpoint = endpoint.clone();
        let headers_env = monitoring.export.otlp.headers_env.clone();
        let streamer_resource = resource.clone();
        let flush = std::time::Duration::from_secs(monitoring.logs_export_interval_seconds());
        handles.push(tokio::spawn(async move {
            crate::monitoring::run_streamer(
                streamer_endpoint,
                headers_env,
                streamer_resource,
                flush,
            )
            .await;
        }));
    }

    // Periodic health snapshot (hermes gateway_health_export metrics loop).
    if monitoring.metrics_enabled() {
        let interval = std::time::Duration::from_secs(monitoring.export_interval_seconds());
        let sampler_install_id = install_id.clone();
        let sampler_version = version.to_string();
        handles.push(tokio::spawn(async move {
            loop {
                tokio::time::sleep(interval).await;
                let active = state.runs.lock().await.len() as u64;
                crate::monitoring::emit(
                    crate::monitoring::GatewayHealthEvent {
                        name: "heartbeat".to_string(),
                        gateway_state: Some("running".to_string()),
                        old_state: None,
                        new_state: None,
                        exit_reason: None,
                        active_agents: active,
                        gateway_busy: active > 0,
                        platform_count,
                        profile: None,
                        install_id: Some(sampler_install_id.clone()),
                        version: Some(sampler_version.clone()),
                        pid: Some(std::process::id()),
                        ts_ns: crate::monitoring::now_ns(),
                    }
                    .to_value(),
                );
            }
        }));
    }

    tracing::info!(
        "monitoring enabled: OTLP export to {} (install_id {})",
        crate::monitoring::traces_url(&endpoint),
        install_id
    );
    handles
}

pub fn spawn_cron_scheduler(
    state: Arc<GatewayState>,
    poll_secs: u64,
) -> Option<tokio::task::JoinHandle<()>> {
    let store = state.cron.get().cloned()?;
    Some(tokio::spawn(crate::cron::run_scheduler(
        store,
        poll_secs,
        move |job| {
            let state = state.clone();
            let run = async move {
                if job.prompt.trim().is_empty() {
                    return Err(crate::error::AgentError::config("job has no prompt to run"));
                }
                let store = match state.cron.get().cloned() {
                    Some(store) => store,
                    None => return Err(crate::error::AgentError::config("cron store unavailable")),
                };
                let mut job = job;
                match spawn_job_run(state, &mut job, store).await {
                    Some(run_id) => Ok(format!("running (run {})", run_id)),
                    None => Err(crate::error::AgentError::config("failed to start job run")),
                }
            };
            // Hermes parity: the scheduler installs a profile secret scope
            // around every job run, so scoped credential reads inside the
            // job resolve against the gateway home's `.env` overlay.
            let home = crate::config::ulnclaw_home();
            crate::secret_scope::scope_secrets(
                std::sync::Arc::new(crate::secret_scope::build_profile_secret_scope(&home)),
                run,
            )
        },
    )))
}

// ---------------------------------------------------------------------------
// Discovery: skills + toolsets
// ---------------------------------------------------------------------------

/// `GET /v1/skills` — list installed skills (hermes `_handle_skills`).
async fn skills_list(State(state): State<Arc<GatewayState>>) -> Json<Value> {
    let dir = state.skills_dir.get().cloned().or_else(|| {
        crate::config::ensure_home()
            .ok()
            .map(|home| home.join("skills"))
    });
    let skills = dir
        .map(|dir| crate::skills::list_skills(&dir))
        .unwrap_or_default();
    Json(json!({"object": "list", "data": skills}))
}

/// `GET /v1/toolsets` — list toolsets and their resolved tools
/// (hermes `_handle_toolsets`). A toolset counts as enabled when the agent
/// actually exposes at least one of its tools.
async fn toolsets_list(State(state): State<Arc<GatewayState>>) -> Json<Value> {
    let registered: std::collections::HashSet<String> =
        state.agent.tool_names().into_iter().collect();
    let definitions = crate::toolsets::toolsets();
    let mut names: Vec<&str> = definitions.keys().copied().collect();
    names.sort_unstable();
    let data: Vec<Value> = names
        .into_iter()
        .map(|name| {
            let definition = &definitions[name];
            let mut tools = crate::toolsets::resolve_toolset(name);
            tools.sort();
            tools.dedup();
            let enabled = tools.iter().any(|tool| registered.contains(tool));
            json!({
                "name": name,
                "description": definition.description,
                "enabled": enabled,
                "tools": tools,
            })
        })
        .collect();
    Json(json!({"object": "list", "data": data}))
}

// ---------------------------------------------------------------------------
// Async runs API
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct StartRunRequest {
    message: String,
    #[serde(default)]
    session_id: Option<String>,
}

async fn start_run(
    State(state): State<Arc<GatewayState>>,
    Json(request): Json<StartRunRequest>,
) -> Response {
    if request.message.trim().is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": {"message": "message is required", "type": "invalid_request_error"}})),
        )
            .into_response();
    }
    // P679: a draining gateway (after /restart) refuses new runs.
    if state.restart.load(std::sync::atomic::Ordering::SeqCst) {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({"error": {"message": "gateway is draining for a restart — no new runs", "type": "invalid_request_error"}})),
        )
            .into_response();
    }
    let run_id = uuid::Uuid::new_v4().to_string();
    // Runs always own a session so approvals can be session-scoped and the
    // conversation stays continuable.
    let session_id = match request.session_id.clone() {
        Some(sid) if !sid.trim().is_empty() => sid,
        _ => {
            let created = state
                .store
                .create_session("gateway-run", Some(&state.model_name), None)
                .unwrap_or_else(|_| uuid::Uuid::new_v4().to_string());
            // P444: tell the desktop shell a gateway-run session appeared.
            crate::desktop_bridge::publish(
                "",
                "session.created",
                &json!({"session_id": created, "source": "gateway-run"}),
            );
            created
        }
    };
    let run = RunState {
        run_id: run_id.clone(),
        status: "running".to_string(),
        session_id: Some(session_id.clone()),
        message: request.message.clone(),
        created_at: now_secs(),
        finished_at: None,
        result: None,
        error: None,
        iterations: None,
        stop_requested: false,
        approval: None,
        job_id: None,
    };
    state.runs.lock().await.insert(run_id.clone(), run.clone());

    spawn_tracked_run(
        state,
        run_id.clone(),
        session_id.clone(),
        request.message.clone(),
        false,
    );

    (
        StatusCode::ACCEPTED,
        Json(json!({"run_id": run_id, "status": "running", "session_id": session_id})),
    )
        .into_response()
}

/// Approval pump (extracted in P437): wire a run's approval channel into
/// the router, pump pending approvals into the run state + the
/// pending-approvals map, and notify the desktop shell so a human can be
/// pulled in. Lives until the run task unregisters on settle.
fn spawn_approval_pump(state: Arc<GatewayState>, run_id: String, session_id: String) {
    let (approval_tx, mut approval_rx) = tokio::sync::mpsc::unbounded_channel::<PendingApproval>();
    state.router.register(&run_id, &session_id, approval_tx);
    tokio::spawn(async move {
        while let Some(pending) = approval_rx.recv().await {
            {
                let mut runs = state.runs.lock().await;
                if let Some(run) = runs.get_mut(&run_id) {
                    run.status = "waiting_for_approval".to_string();
                    run.approval = Some(json!({
                        "command": pending.command,
                        "reason": pending.reason,
                        "choices": ["once", "session", "always", "deny"],
                    }));
                }
            }
            // P437: pull a human in — surface the pending approval on the
            // desktop bridge (inert without a subscribed shell).
            crate::desktop_bridge::publish(
                &session_id,
                "run.approval",
                &json!({
                    "run_id": run_id,
                    "command": pending.command,
                    "reason": pending.reason,
                }),
            );
            state
                .pending_approvals
                .lock()
                .await
                .insert(run_id.clone(), pending.respond);
        }
    });
}

/// Execute one agent turn as a tracked background run: registers approval
/// routing, pumps pending approvals into run state, and updates the run row
/// when the turn finishes. Shared by `/v1/runs` (`cron = false`) and
/// `/api/jobs/:id/run` (`cron = true` — approval gates apply
/// `approvals.cron_mode` because no human is attached).
fn spawn_tracked_run(
    state: Arc<GatewayState>,
    run_id: String,
    session_id: String,
    message: String,
    cron: bool,
) {
    spawn_approval_pump(state.clone(), run_id.clone(), session_id.clone());

    state
        .metrics
        .runs_started
        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let runner = state.clone();
    let spawn_run_id = run_id.clone();
    let run_future = RUN_ID.scope(
        run_id.clone(),
        crate::agent::cron_scope(cron, async move {
            let history = runner
                .store
                .load_messages(&session_id)
                .unwrap_or_default()
                .into_iter()
                .filter(|m| m.role != Role::System)
                .collect::<Vec<_>>();
            let history = if history.is_empty() {
                None
            } else {
                Some(history)
            };
            let override_model = session_model_override(&runner, &session_id);
            let outcome = await_with_model_override(
                override_model,
                runner
                    .agent
                    .run_with_session(&message, history, Some(session_id.as_str())),
            )
            .await;
            let mut runs = runner.runs.lock().await;
            let mut settle: Option<(bool, String)> = None;
            if let Some(run) = runs.get_mut(&spawn_run_id) {
                match outcome {
                    Ok(result) => {
                        run.status = "completed".to_string();
                        runner
                            .metrics
                            .record_run(&result.usage, result.tool_calls.len());
                        runner
                            .metrics
                            .runs_completed
                            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        let snippet = result.content.chars().take(140).collect::<String>();
                        run.result = Some(result.content);
                        run.session_id = result.session_id.or(run.session_id.take());
                        run.iterations = Some(result.iterations);
                        settle = Some((true, snippet));
                    }
                    Err(e) => {
                        run.status = "failed".to_string();
                        runner
                            .metrics
                            .runs_failed
                            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        let message = e.to_string();
                        run.error = Some(message.clone());
                        settle = Some((false, message.chars().take(140).collect()));
                    }
                }
                run.finished_at = Some(now_secs());
            }
            drop(runs);
            runner.router.unregister(&spawn_run_id);
            // Desktop shell notification (P433): surface the settled run on the
            // UI bridge so the desktop webview can toast it. Inert unless a
            // desktop consumer is subscribed to /api/desktop/events.
            if let Some((succeeded, snippet)) = settle {
                crate::desktop_bridge::publish(
                    &session_id,
                    if succeeded {
                        "run.completed"
                    } else {
                        "run.failed"
                    },
                    &json!({
                        "run_id": spawn_run_id,
                        "status": if succeeded { "completed" } else { "failed" },
                        "snippet": snippet,
                    }),
                );
            }
        }),
    );
    // Profile secret scope inheritance (hermes copy_context parity): a
    // mirrored `/p/<profile>/...` request dispatches with that profile's
    // scope installed; the run task must keep resolving credentials
    // against it, so re-install the captured scope inside the spawn.
    crate::secret_scope::spawn_scoped(run_future);
}

async fn list_runs(State(state): State<Arc<GatewayState>>) -> Json<Value> {
    let runs = state.runs.lock().await;
    let mut data: Vec<&RunState> = runs.values().collect();
    data.sort_by(|a, b| {
        b.created_at
            .partial_cmp(&a.created_at)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    Json(json!({"object": "list", "data": data}))
}

async fn get_run(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let runs = state.runs.lock().await;
    match runs.get(&id) {
        Some(run) => Json(json!(run)).into_response(),
        None => not_found(&format!("run {} not found", id)),
    }
}

/// SSE stream of run lifecycle events (`run.progress` / `run.completed` /
/// `run.failed`), closing once the run reaches a terminal state.
async fn run_events(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let exists = state.runs.lock().await.contains_key(&id);
    if !exists {
        return not_found(&format!("run {} not found", id));
    }
    let stream = futures::stream::unfold(
        (state, id, String::new(), false),
        |(state, id, last_status, done)| async move {
            if done {
                return None;
            }
            loop {
                let run = state.runs.lock().await.get(&id).cloned();
                match run {
                    None => return None,
                    Some(run) if run.status != last_status => {
                        let event_name = match run.status.as_str() {
                            "completed" => "run.completed",
                            "failed" => "run.failed",
                            "waiting_for_approval" => "approval.request",
                            _ => "run.progress",
                        };
                        let data = serde_json::to_string(&run).unwrap_or_default();
                        let event = axum::response::sse::Event::default()
                            .event(event_name)
                            .data(data);
                        let terminal = matches!(run.status.as_str(), "completed" | "failed");
                        return Some((
                            Ok::<_, std::convert::Infallible>(event),
                            (state, id, run.status.clone(), terminal),
                        ));
                    }
                    Some(_) => {
                        drop(run);
                        tokio::time::sleep(std::time::Duration::from_millis(250)).await;
                    }
                }
            }
        },
    );
    axum::response::sse::Sse::new(stream)
        .keep_alive(
            axum::response::sse::KeepAlive::new()
                .interval(std::time::Duration::from_secs(15))
                .text("keep-alive"),
        )
        .into_response()
}

#[derive(Deserialize)]
struct ApprovalDecision {
    decision: String,
}

/// Resolve a run's pending approval: once | session | always | deny.
async fn resolve_approval(
    State(state): State<Arc<GatewayState>>,
    Path(id): Path<String>,
    Json(request): Json<ApprovalDecision>,
) -> Response {
    let decision = request.decision.trim().to_string();
    if !matches!(decision.as_str(), "once" | "session" | "always" | "deny") {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({"error": {"message": "decision must be one of: once, session, always, deny", "type": "invalid_request_error"}})),
        )
            .into_response();
    }
    let responder = state.pending_approvals.lock().await.remove(&id);
    let Some(responder) = responder else {
        return (
            StatusCode::CONFLICT,
            Json(json!({"error": {"message": format!("run {} has no pending approval", id), "type": "invalid_request_error"}})),
        )
            .into_response();
    };
    responder.send(decision.clone()).ok();
    let mut runs = state.runs.lock().await;
    if let Some(run) = runs.get_mut(&id) {
        if run.status == "waiting_for_approval" {
            run.status = "running".to_string();
        }
        if let Some(approval) = run.approval.as_mut() {
            approval["resolved"] = json!(decision);
        }
    }
    Json(json!({"run_id": id, "decision": decision})).into_response()
}

async fn stop_run(State(state): State<Arc<GatewayState>>, Path(id): Path<String>) -> Response {
    let mut runs = state.runs.lock().await;
    match runs.get_mut(&id) {
        Some(run) if run.status == "running" || run.status == "queued" => {
            run.stop_requested = true;
            Json(json!({
                "run_id": id,
                "stop_requested": true,
                "note": "interruption is best-effort in this build; the agent finishes its current iteration",
            }))
            .into_response()
        }
        Some(run) => Json(json!({
            "run_id": id,
            "stop_requested": false,
            "note": format!("run already {}", run.status),
        }))
        .into_response(),
        None => not_found(&format!("run {} not found", id)),
    }
}

