    #[tokio::test]
    async fn test_capabilities_and_sessions_crud() {
        let state = test_state();
        let token = "sekret";
        let app = router(state.clone());

        let (status, body) = get_json(app.clone(), "/v1/capabilities", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["endpoints"]["chat_completions"], true);

        // Create → list → get → messages → delete.
        let request = axum::http::Request::builder()
            .uri("/api/sessions")
            .method("POST")
            .header("authorization", format!("Bearer {}", token))
            .header("content-type", "application/json")
            .body(axum::body::Body::empty())
            .unwrap();
        let response = app.clone().oneshot(request).await.unwrap();
        assert_eq!(response.status(), StatusCode::CREATED);
        let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let created: Value = serde_json::from_slice(&body_bytes).unwrap();
        let session_id = created["id"].as_str().unwrap().to_string();

        let (status, body) = get_json(app.clone(), "/api/sessions?limit=10", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["data"]
            .as_array()
            .unwrap()
            .iter()
            .any(|s| s["id"] == session_id));

        let (status, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}", session_id),
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["source"], "gateway");

        let (status, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages", session_id),
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["data"].as_array().unwrap().len(), 0);

        let request = axum::http::Request::builder()
            .uri(&format!("/api/sessions/{}", session_id))
            .method("DELETE")
            .header("authorization", format!("Bearer {}", token))
            .body(axum::body::Body::empty())
            .unwrap();
        let response = app.clone().oneshot(request).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let (status, _) =
            get_json(app, &format!("/api/sessions/{}", session_id), Some(token)).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn test_sessions_list_last_message_preview() {
        let state = test_state();
        let token = "sekret";
        let app = router(state.clone());

        // Two sessions: one with messages, one empty.
        let with_messages = state
            .store
            .create_session("gateway", Some("test-model"), None)
            .unwrap();
        let empty = state
            .store
            .create_session("gateway", Some("test-model"), None)
            .unwrap();
        let user_msg = Message {
            role: Role::User,
            content: Some("first question".to_string()),
            tool_calls: None,
            tool_call_id: None,
            name: None,
        };
        let assistant_msg = Message {
            role: Role::Assistant,
            content: Some("  final  answer\nover   two lines ".to_string()),
            tool_calls: None,
            tool_call_id: None,
            name: None,
        };
        state
            .store
            .append_message(&with_messages, &user_msg)
            .unwrap();
        state
            .store
            .append_message(&with_messages, &assistant_msg)
            .unwrap();

        // Default listing carries no preview field.
        let (status, body) = get_json(app.clone(), "/api/sessions?limit=10", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let rows = body["data"].as_array().unwrap();
        let plain = rows.iter().find(|row| row["id"] == with_messages).unwrap();
        assert!(plain.get("last_message").is_none());

        // preview=true attaches a whitespace-collapsed snippet of the
        // last message; empty sessions get null.
        let (status, body) = get_json(
            app.clone(),
            "/api/sessions?limit=10&preview=true",
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let rows = body["data"].as_array().unwrap();
        let with_row = rows.iter().find(|row| row["id"] == with_messages).unwrap();
        assert_eq!(with_row["last_message"], "final answer over two lines");
        let empty_row = rows.iter().find(|row| row["id"] == empty).unwrap();
        assert_eq!(empty_row["last_message"], Value::Null);

        // Long last messages are capped at 80 chars plus an ellipsis.
        let long_id = state
            .store
            .create_session("gateway", Some("test-model"), None)
            .unwrap();
        let long_msg = Message {
            role: Role::Assistant,
            content: Some("x".repeat(200)),
            tool_calls: None,
            tool_call_id: None,
            name: None,
        };
        state.store.append_message(&long_id, &long_msg).unwrap();
        let (status, body) =
            get_json(app, "/api/sessions?limit=10&preview=true", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let rows = body["data"].as_array().unwrap();
        let long_row = rows.iter().find(|row| row["id"] == long_id).unwrap();
        let preview = long_row["last_message"].as_str().unwrap();
        assert_eq!(preview.chars().count(), 81);
        assert!(preview.ends_with('…'));
    }

    #[tokio::test]
    async fn test_sessions_list_exposes_archived_flag() {
        let state = test_state();
        let token = "sekret";
        let app = router(state.clone());
        let id = state
            .store
            .create_session("gateway", Some("test-model"), None)
            .unwrap();

        // Fresh rows report archived=false.
        let (status, body) = get_json(app.clone(), "/api/sessions?limit=10", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let row = body["data"]
            .as_array()
            .unwrap()
            .iter()
            .find(|r| r["id"] == id)
            .unwrap()
            .clone();
        assert_eq!(row["archived"], false);

        // The TUI F8 archive flow flips the flag visible on the API.
        state.store.set_session_archived(&id, true).unwrap();
        let (status, body) = get_json(app.clone(), "/api/sessions?limit=10", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let row = body["data"]
            .as_array()
            .unwrap()
            .iter()
            .find(|r| r["id"] == id)
            .unwrap()
            .clone();
        assert_eq!(row["archived"], true);

        // The single-session GET carries the flag too.
        let (status, body) = get_json(app, &format!("/api/sessions/{}", id), Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["archived"], true);
    }

    #[tokio::test]
    async fn test_sessions_list_source_and_end_reason_filters() {
        let state = test_state();
        let token = "sekret";
        let app = router(state.clone());
        let cli = state
            .store
            .create_session("cli", Some("test-model"), None)
            .unwrap();
        let cron = state
            .store
            .create_session("cron", Some("test-model"), None)
            .unwrap();
        state.store.end_session(&cron, "complete").unwrap();

        let ids = |body: &Value| -> Vec<String> {
            body["data"]
                .as_array()
                .unwrap()
                .iter()
                .map(|row| row["id"].as_str().unwrap().to_string())
                .collect()
        };

        // ?source= narrows to one source.
        let (status, body) = get_json(
            app.clone(),
            "/api/sessions?limit=10&source=cli",
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let listed = ids(&body);
        assert!(listed.contains(&cli));
        assert!(!listed.contains(&cron));

        // ?end_reason= matches ended sessions; `none` selects open ones.
        let (status, body) = get_json(
            app.clone(),
            "/api/sessions?limit=10&end_reason=complete",
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let listed = ids(&body);
        assert_eq!(listed, vec![cron.clone()]);

        let (status, body) = get_json(
            app.clone(),
            "/api/sessions?limit=10&end_reason=none",
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let listed = ids(&body);
        assert!(listed.contains(&cli));
        assert!(!listed.contains(&cron));

        // Filters compose.
        let (status, body) = get_json(
            app,
            "/api/sessions?limit=10&source=cron&end_reason=none",
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(ids(&body).is_empty());
    }

