    #[tokio::test]
    async fn test_session_chat_slash_direct_commands() {
        let state = streaming_state();
        let sid = state
            .store
            .create_session("slash-test", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        let reply = post_chat(app.clone(), &sid, "/help").await;
        assert!(
            reply["response"]
                .as_str()
                .unwrap()
                .starts_with("Gateway slash commands:"),
            "help: {}",
            reply
        );
        assert_eq!(reply["iterations"], 0);

        let reply = post_chat(app.clone(), &sid, "/title Slash Session").await;
        assert_eq!(reply["response"], "title set: Slash Session");
        let reply = post_chat(app.clone(), &sid, "/title").await;
        assert_eq!(reply["response"], "title: Slash Session");

        // P570: /retitle regenerates the title from the first exchange
        // (the fake provider's answer is always "Hello"), then no-ops.
        let reply = post_chat(app.clone(), &sid, "/retitle").await;
        assert_eq!(
            reply["response"],
            "title: \"Slash Session\" \u{2192} \"Hello\""
        );
        let reply = post_chat(app.clone(), &sid, "/retitle").await;
        assert_eq!(reply["response"], "title already up to date: \"Hello\"");

        let reply = post_chat(app.clone(), &sid, "/no-such-command").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .starts_with("unknown command: /no-such-command"));

        // Direct exchanges are persisted to the transcript.
        let messages = state.store.load_messages(&sid).expect("messages load");
        assert!(messages
            .iter()
            .any(|m| m.content.as_deref() == Some("/help")));
        assert!(messages
            .iter()
            .any(|m| m.content.as_deref() == Some("title set: Slash Session")));
    }

    #[tokio::test]
    async fn test_session_chat_slash_status_wave() {
        // P612 read-only slash wave: /status, /context, /whoami,
        // /version, /commands, /profile, /model + /reasoning display.
        let state = streaming_state();
        let sid = state
            .store
            .create_session("slash-wave", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        let reply = post_chat(app.clone(), &sid, "/status").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains(&format!("session: {sid}")), "{text}");
        assert!(text.contains("run status: "), "{text}");
        assert!(text.contains("model: fake-stream (fake)"), "{text}");
        assert!(text.contains("gateway uptime:"), "{text}");

        // P624: /context renders the hermes-style breakdown view.
        let reply = post_chat(app.clone(), &sid, "/context").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("Estimated usage by category"), "{text}");
        assert!(text.contains("Conversation"), "{text}");
        assert!(text.contains("/context all"), "{text}");

        let reply = post_chat(app.clone(), &sid, "/whoami").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("claimer: "), "{text}");
        assert!(text.contains("provider: fake"), "{text}");

        let reply = post_chat(app.clone(), &sid, "/version").await;
        assert!(reply["response"].as_str().unwrap().starts_with("ulnclaw "));

        let reply = post_chat(app.clone(), &sid, "/commands").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .starts_with("Gateway slash commands:"));

        let reply = post_chat(app.clone(), &sid, "/model").await;
        assert_eq!(reply["response"], "model: fake-stream (fake)");

        let reply = post_chat(app.clone(), &sid, "/profile").await;
        let text = reply["response"].as_str().unwrap();
        assert!(
            text.contains("profiles:") || text.contains("no profiles configured"),
            "{text}"
        );

        let reply = post_chat(app.clone(), &sid, "/reasoning").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.starts_with("reasoning effort: "), "{text}");

        // Bad /model usage explains itself.
        let reply = post_chat(app.clone(), &sid, "/model onlyone").await;
        assert_eq!(reply["response"], "usage: /model <provider> <model>");
    }

    #[tokio::test]
    async fn test_session_context_breakdown_endpoint() {
        let state = streaming_state();
        let sid = state
            .store
            .create_session("ctx-breakdown", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        // Seed one exchange so the conversation category is nonzero.
        let reply = post_chat(app.clone(), &sid, "hello there").await;
        assert_eq!(reply["response"], "Hello");

        let (status, body) =
            get_json(app.clone(), &format!("/api/sessions/{sid}/context"), None).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["context_max"].as_u64().unwrap() > 0, "{body}");
        assert!(body["estimated_total"].as_u64().unwrap() > 0, "{body}");
        assert_eq!(
            body["context_used"].as_u64().unwrap(),
            body["estimated_total"].as_u64().unwrap()
        );
        let percent = body["context_percent"].as_u64().unwrap();
        assert!(percent <= 100, "{body}");
        let categories = body["categories"].as_array().expect("categories");
        let ids: Vec<&str> = categories
            .iter()
            .map(|c| c["id"].as_str().unwrap())
            .collect();
        assert!(ids.contains(&"system_prompt"), "{ids:?}");
        assert!(ids.contains(&"tool_definitions"), "{ids:?}");
        assert!(ids.contains(&"conversation"), "{ids:?}");
        // Declaration order mirrors hermes (system before tools, tools
        // before conversation).
        assert!(
            ids.iter().position(|i| *i == "system_prompt")
                < ids.iter().position(|i| *i == "conversation")
        );

        // Unknown session → 404.
        let (status, _) = get_json(app, "/api/sessions/nope/context", None).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

