    #[tokio::test]
    async fn test_session_chat_slash_blueprint() {
        // P656: /blueprint — catalog listing, forgiving name match,
        // agent seeding, and inline slot=val direct creation.
        let state = streaming_state();
        let cron_temp = tempfile::tempdir().expect("tempdir");
        let cron = crate::cron::CronStore::open(&cron_temp.path().join("cron.db"))
            .expect("cron store opens");
        state.cron.set(Arc::new(cron)).ok();
        let sid = state
            .store
            .create_session("blueprint-slash", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        // Bare -> catalog.
        let reply = post_chat(app.clone(), &sid, "/blueprint").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("Automation Blueprints"), "{text}");
        assert!(text.contains("morning-brief"), "{text}");

        // Ambiguous prefix -> candidate list.
        let reply = post_chat(app.clone(), &sid, "/blueprint week").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("matches several blueprints"), "{text}");

        // No match -> suggestion.
        let reply = post_chat(app.clone(), &sid, "/blueprint zzzzz").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("No automation blueprint matches"), "{text}");

        // Direct create with inline values.
        let reply = post_chat(
            app.clone(),
            &sid,
            "/blueprint morning-brief time=07:45 deliver=local",
        )
        .await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("Scheduled 'Morning briefing'"), "{text}");
        assert!(text.contains("45 7 * * *"), "{text}");
        let jobs = state.cron.get().unwrap().list().expect("jobs list");
        assert_eq!(jobs.len(), 1);
        assert_eq!(jobs[0].schedule, "45 7 * * *");
        assert_eq!(jobs[0].deliver.as_deref(), Some("local"));

        // Inline validation error stays a direct reply.
        let reply = post_chat(app.clone(), &sid, "/blueprint morning-brief time=25:99").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("Can't set up"), "{text}");
        assert!(text.contains("invalid time"), "{text}");
    }

    /// P625: gateway state wired to a real OpenAI provider (no network
    /// calls — only the service-tier plumbing is exercised).
    fn fast_state() -> Arc<GatewayState> {
        let temp = tempfile::tempdir().expect("tempdir");
        let store =
            Arc::new(SqliteSessionStore::open(temp.path().join("state.db")).expect("store opens"));
        std::mem::forget(temp);
        let provider = crate::provider::openai::OpenAiProvider::builder()
            .endpoint("http://127.0.0.1:9")
            .model("gpt-5")
            .name("openai")
            .build()
            .expect("provider builds");
        let agent = Agent::new(Arc::new(provider), ToolRegistry::new()).with_store(store);
        GatewayState::new(
            Arc::new(agent),
            "gpt-5".into(),
            "openai".into(),
            None,
            ApprovalRouter::new(),
        )
        .expect("state builds")
    }

    #[tokio::test]
    async fn test_session_chat_slash_branch_diff_rollback() {
        let state = streaming_state();
        let app = router(state.clone());

        // /branch guards an empty transcript.
        let empty_sid = state
            .store
            .create_session("branch-empty", Some("fake-stream"), None)
            .expect("session created");
        let reply = post_chat(app.clone(), &empty_sid, "/branch").await;
        assert!(
            reply["response"]
                .as_str()
                .unwrap()
                .contains("no conversation"),
            "{reply}"
        );

        // Seed an exchange, then branch with an explicit name.
        let sid = state
            .store
            .create_session("branch-src", Some("fake-stream"), None)
            .expect("session created");
        let reply = post_chat(app.clone(), &sid, "hello").await;
        assert_eq!(reply["response"], "Hello");
        let reply = post_chat(app.clone(), &sid, "/branch experiment").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("branched session"), "{text}");
        assert!(text.contains("experiment"), "{text}");

        // Parent ends as branched; the child carries the copied history.
        let parent = state.store.get_session_row(&sid).unwrap().unwrap();
        assert_eq!(parent.end_reason.as_deref(), Some("branched"));
        let child = state
            .store
            .list_session_rows(20)
            .unwrap()
            .into_iter()
            .find(|row| row.title.as_deref() == Some("experiment"))
            .expect("child session exists");
        assert_eq!(child.parent_session_id.as_deref(), Some(sid.as_str()));
        assert_eq!(state.store.load_messages(&child.id).unwrap().len(), 2);

        // /diff on a session whose cwd is not a git repo reports the
        // failure; unknown arguments are rejected up front.
        let temp = tempfile::tempdir().unwrap();
        let did = state
            .store
            .create_session(
                "diff-src",
                Some("fake-stream"),
                Some(temp.path().to_str().unwrap()),
            )
            .expect("session created");
        let reply = post_chat(app.clone(), &did, "/diff").await;
        assert!(
            reply["response"].as_str().unwrap().contains("diff failed"),
            "{reply}"
        );
        let reply = post_chat(app.clone(), &did, "/diff bogus").await;
        assert!(
            reply["response"]
                .as_str()
                .unwrap()
                .contains("unknown /diff argument"),
            "{reply}"
        );

        // /rollback while checkpoints stay disabled (the default).
        let reply = post_chat(app.clone(), &did, "/rollback").await;
        assert!(
            reply["response"].as_str().unwrap().contains("not enabled"),
            "{reply}"
        );
    }

    #[tokio::test]
    async fn test_sessions_list_context_enrichment() {
        let state = streaming_state();
        let sid = state
            .store
            .create_session("ctx-list", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        // Seed an exchange so the conversation estimate is nonzero.
        let reply = post_chat(app.clone(), &sid, "hello there").await;
        assert_eq!(reply["response"], "Hello");

        // Without context=true the fields stay absent.
        let (status, body) = get_json(app.clone(), "/api/sessions", None).await;
        assert_eq!(status, StatusCode::OK);
        let row = body["data"]
            .as_array()
            .unwrap()
            .iter()
            .find(|r| r["id"] == json!(sid))
            .expect("row present")
            .clone();
        assert!(row.get("context_percent").is_none(), "{row}");

        // With context=true every row carries usage vs the budget.
        let (status, body) = get_json(app.clone(), "/api/sessions?context=true", None).await;
        assert_eq!(status, StatusCode::OK);
        let row = body["data"]
            .as_array()
            .unwrap()
            .iter()
            .find(|r| r["id"] == json!(sid))
            .expect("row present")
            .clone();
        assert!(row["context_used"].as_u64().unwrap() > 0, "{row}");
        // Percent can legitimately round to 0 for tiny histories vs a
        // 128k budget; the contract is a bounded integer.
        let percent = row["context_percent"].as_u64().unwrap();
        assert!(percent <= 100, "{row}");
    }

    #[tokio::test]
    async fn test_fast_endpoint_and_slash_supported_model() {
        let state = fast_state();
        let sid = state
            .store
            .create_session("fast-test", Some("gpt-5"), None)
            .expect("session created");
        let app = router(state.clone());

        // Status before any toggle.
        let (status, body) = get_json(app.clone(), "/api/fast", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["supported"], true, "{body}");
        assert_eq!(body["mode"], "normal", "{body}");

        // HTTP twin: switch on, then off.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/fast",
            None,
            json!({"mode": "fast"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["mode"], "fast", "{body}");
        let (_, body) = get_json(app.clone(), "/api/fast", None).await;
        assert_eq!(body["mode"], "fast", "{body}");

        // Slash status reflects the process-wide override.
        let reply = post_chat(app.clone(), &sid, "/fast").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("priority processing: fast"));

        let reply = post_chat(app.clone(), &sid, "/fast off").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("priority processing: normal"));
        let (_, body) = get_json(app.clone(), "/api/fast", None).await;
        assert_eq!(body["mode"], "normal", "{body}");

        // Invalid mode → 400 with the error envelope.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/fast",
            None,
            json!({"mode": "warp"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(body["error"]["message"]
            .as_str()
            .unwrap()
            .contains("fast or normal"));
    }

