    #[tokio::test]
    async fn test_approvals_endpoint_round_trip() {
        // P635 write path: PUT /api/approvals persists approvals.mode
        // (isolated ULNCLAW_HOME under the env lock).
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("config.toml"), "").unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let state = streaming_state();
        let app = router(state.clone());

        // Default mode surfaces with the allowed values.
        let (status, body) = get_json(app.clone(), "/api/approvals", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["mode"], "manual", "{body}");
        assert_eq!(body["modes"], json!(["manual", "smart", "off"]), "{body}");

        // Switch to smart, verify on disk.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals",
            None,
            json!({"mode": "smart"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["mode"], "smart", "{body}");
        let config_text = std::fs::read_to_string(dir.path().join("config.toml")).unwrap();
        assert!(config_text.contains("mode = \"smart\""), "{config_text}");
        let (_, body) = get_json(app.clone(), "/api/approvals", None).await;
        assert_eq!(body["mode"], "smart", "{body}");

        // Invalid mode → 400 with the allowed-list message.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals",
            None,
            json!({"mode": "yolo"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(body["error"]["message"]
            .as_str()
            .unwrap()
            .contains("manual|smart|off"));

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_approvals_settings_editor() {
        // P744: PUT /api/approvals/settings persists the knobs the mode
        // switch does not cover; GET /api/approvals surfaces them.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("config.toml"), "").unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let app = router(test_state());

        // Defaults surface in the extended GET.
        let (status, body) = get_json(app.clone(), "/api/approvals", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["timeout"], 300, "{body}");
        assert_eq!(body["cron_mode"], "deny", "{body}");
        assert_eq!(body["denial_breaker_threshold"], 3, "{body}");
        assert_eq!(body["mcp_reload_confirm"], true, "{body}");
        assert_eq!(body["deny"], json!([]), "{body}");

        // Persist each knob.
        for (key, value) in [
            ("timeout", json!(600)),
            ("cron_mode", json!("approve")),
            ("smart_policy", json!("be strict")),
            ("denial_breaker_threshold", json!(5)),
            ("mcp_reload_confirm", json!(false)),
            ("deny", json!(["sudo *", "rm -rf /"])),
        ] {
            let (status, body) = send_json(
                app.clone(),
                "PUT",
                "/api/approvals/settings",
                Some("sekret"),
                json!({ "key": key, "value": value }),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "{key}: {body}");
        }
        let (_, body) = get_json(app.clone(), "/api/approvals", Some("sekret")).await;
        assert_eq!(body["timeout"], 600, "{body}");
        assert_eq!(body["cron_mode"], "approve", "{body}");
        assert_eq!(body["smart_policy"], "be strict", "{body}");
        assert_eq!(body["denial_breaker_threshold"], 5, "{body}");
        assert_eq!(body["mcp_reload_confirm"], false, "{body}");
        assert_eq!(body["deny"], json!(["sudo *", "rm -rf /"]), "{body}");

        // Validation: unknown key, bad enum, wrong types.
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals/settings",
            Some("sekret"),
            json!({ "key": "yolo", "value": 1 }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals/settings",
            Some("sekret"),
            json!({ "key": "cron_mode", "value": "maybe" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals/settings",
            Some("sekret"),
            json!({ "key": "timeout", "value": "soon" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals/settings",
            Some("sekret"),
            json!({ "key": "deny", "value": "sudo *" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Null removes the override and restores the default.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/approvals/settings",
            Some("sekret"),
            json!({ "key": "timeout", "value": null }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["removed"], true, "{body}");
        let (_, body) = get_json(app.clone(), "/api/approvals", Some("sekret")).await;
        assert_eq!(body["timeout"], 300, "{body}");

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_gateway_settings_editor() {
        // P745: GET /api/gateway-settings surfaces the resolved gateway
        // settings; PUT persists behavior knobs with validation.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("config.toml"),
            "[gateway]\nkey = \"hunter2\"\n",
        )
        .unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let app = router(test_state());

        // Defaults: local listener on 8642, configured key surfaces as
        // a flag (never the value), watchdog on, stall 300s.
        let (status, body) = get_json(app.clone(), "/api/gateway-settings", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["host"], "127.0.0.1", "{body}");
        assert_eq!(body["port"], 8642, "{body}");
        assert_eq!(body["key_configured"], true, "{body}");
        assert_eq!(body["key_env_override"], false, "{body}");
        assert!(body.to_string().contains("hunter2") == false, "{body}");
        assert_eq!(body["loop_watchdog"], true, "{body}");
        assert_eq!(body["message_timestamps"], false, "{body}");
        assert_eq!(body["multiplex_profiles"], false, "{body}");
        assert_eq!(body["session_stall_timeout_secs"], 300.0, "{body}");

        // Persist each knob.
        for (key, value) in [
            ("message_timestamps", json!(true)),
            ("loop_watchdog", json!(false)),
            ("multiplex_profiles", json!(true)),
            ("systemd_watchdog_seconds", json!(30)),
            ("max_concurrent_sessions", json!(8)),
            ("session_stall_timeout_secs", json!(120.5)),
        ] {
            let (status, body) = send_json(
                app.clone(),
                "PUT",
                "/api/gateway-settings",
                Some("sekret"),
                json!({ "key": key, "value": value }),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "{key}: {body}");
        }
        let (_, body) = get_json(app.clone(), "/api/gateway-settings", Some("sekret")).await;
        assert_eq!(body["message_timestamps"], true, "{body}");
        assert_eq!(body["loop_watchdog"], false, "{body}");
        assert_eq!(body["multiplex_profiles"], true, "{body}");
        assert_eq!(body["systemd_watchdog_seconds"], 30, "{body}");
        assert_eq!(body["max_concurrent_sessions"], 8, "{body}");
        assert_eq!(body["session_stall_timeout_secs"], 120.5, "{body}");

        // Listener identity is not editable through this surface.
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/gateway-settings",
            Some("sekret"),
            json!({ "key": "port", "value": 1234 }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/gateway-settings",
            Some("sekret"),
            json!({ "key": "loop_watchdog", "value": "yes" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/gateway-settings",
            Some("sekret"),
            json!({ "key": "session_stall_timeout_secs", "value": -5 }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Null removes the override and restores the default.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/gateway-settings",
            Some("sekret"),
            json!({ "key": "message_timestamps", "value": null }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["removed"], true, "{body}");
        let (_, body) = get_json(app.clone(), "/api/gateway-settings", Some("sekret")).await;
        assert_eq!(body["message_timestamps"], false, "{body}");

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

