    #[tokio::test]
    async fn test_discord_settings_editor() {
        // P761: GET /api/discord-settings surfaces the server_actions
        // allowlist + known actions; PUT persists with validation.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("config.toml"),
            "[discord]\nserver_actions = \"fetch_messages, list_pins\"\n",
        )
        .unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let app = router(test_state());

        // Comma-string config normalises to a list; known actions
        // surface for the editor.
        let (status, body) = get_json(app.clone(), "/api/discord-settings", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            body["server_actions"],
            json!(["fetch_messages", "list_pins"]),
            "{body}"
        );
        assert!(
            body["known_actions"].as_array().unwrap().len() > 10,
            "{body}"
        );

        // Persist an array of valid actions.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/discord-settings",
            Some("sekret"),
            json!({ "key": "server_actions", "value": ["list_guilds", "server_info"] }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (_, body) = get_json(app.clone(), "/api/discord-settings", Some("sekret")).await;
        assert_eq!(
            body["server_actions"],
            json!(["list_guilds", "server_info"]),
            "{body}"
        );

        // Comma-separated strings are accepted too.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/discord-settings",
            Some("sekret"),
            json!({ "key": "server_actions", "value": "fetch_messages" }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (_, body) = get_json(app.clone(), "/api/discord-settings", Some("sekret")).await;
        assert_eq!(body["server_actions"], json!(["fetch_messages"]), "{body}");

        // Unknown actions are rejected with the known list.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/discord-settings",
            Some("sekret"),
            json!({ "key": "server_actions", "value": ["nuke_guild"] }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
        assert!(body["known_actions"].as_array().is_some(), "{body}");

        // null removes the allowlist (every action exposed again).
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/discord-settings",
            Some("sekret"),
            json!({ "key": "server_actions", "value": Value::Null }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["removed"], true, "{body}");
        let (_, body) = get_json(app.clone(), "/api/discord-settings", Some("sekret")).await;
        assert_eq!(body["server_actions"], Value::Null, "{body}");

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_pets_settings_editor() {
        // P762: GET /api/pets-settings surfaces the image pipeline
        // knobs with a configured-flag (never the key value); PUT
        // persists base URL/model but refuses the key.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("config.toml"),
            "[pets]\nimage_api_key = \"sk-secret\"\nimage_model = \"gpt-image-2\"\n",
        )
        .unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let app = router(test_state());

        // Key surfaces only as a configured flag; the value never
        // leaks through the endpoint.
        let (status, body) = get_json(app.clone(), "/api/pets-settings", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["image_api_key_configured"], true, "{body}");
        assert_eq!(body["image_model"], "gpt-image-2", "{body}");
        assert_eq!(body["image_base_url"], Value::Null, "{body}");
        assert!(!body.to_string().contains("sk-secret"), "{body}");

        // Persist base URL + model.
        for (key, value) in [
            ("image_base_url", json!("http://localhost:11434/v1")),
            ("image_model", json!("custom-image-1")),
        ] {
            let (status, body) = send_json(
                app.clone(),
                "PUT",
                "/api/pets-settings",
                Some("sekret"),
                json!({ "key": key, "value": value }),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "{key}: {body}");
        }
        let (_, body) = get_json(app.clone(), "/api/pets-settings", Some("sekret")).await;
        assert_eq!(
            body["image_base_url"], "http://localhost:11434/v1",
            "{body}"
        );
        assert_eq!(body["image_model"], "custom-image-1", "{body}");

        // The API key is not editable through the shell.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/pets-settings",
            Some("sekret"),
            json!({ "key": "image_api_key", "value": "sk-other" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");

        // Empty string clears a knob back to the default.
        let (status, body) = send_json(
            app.clone(),
            "PUT",
            "/api/pets-settings",
            Some("sekret"),
            json!({ "key": "image_base_url", "value": "" }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["removed"], true, "{body}");
        let (_, body) = get_json(app.clone(), "/api/pets-settings", Some("sekret")).await;
        assert_eq!(body["image_base_url"], Value::Null, "{body}");
        // The untouched key stays configured.
        assert_eq!(body["image_api_key_configured"], true, "{body}");

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

