        let (status, _) = send_json(
            app.clone(),
            "PUT",
            "/api/auxiliary-settings",
            Some("sekret"),
            json!({ "task": "title_generation", "key": "enabled", "value": "off" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Empty string clears an override back to inherit.
