    #[tokio::test]
    async fn test_kanban_board_rename_remove_endpoints() {
        // P653: POST .../rename + DELETE /api/kanban/boards/:slug
        // (hermes boards rename / rm with safety guards).
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let state = streaming_state();
        let app = router(state.clone());

        // Create a scratch board and rename it.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/boards",
            None,
            json!({"slug": "temp-board", "name": "Temp"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/boards/temp-board/rename",
            None,
            json!({"name": "Renamed"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["name"], "Renamed", "{body}");

        // Blank name -> 400; unknown slug -> 404.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/boards/temp-board/rename",
            None,
            json!({"name": "   "}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/boards/nope/rename",
            None,
            json!({"name": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        // Default board is protected.
        let (status, body) = send_json(
            app.clone(),
            "DELETE",
            "/api/kanban/boards/default",
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
        assert!(
            body["error"]["message"]
                .as_str()
                .unwrap()
                .contains("default board"),
            "{body}"
        );

        // A board with an active task refuses removal until archived.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/boards/temp-board/switch",
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/kanban/tasks",
            None,
            json!({"title": "blocker"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let task_id = body["task"]["id"].as_str().unwrap().to_string();
        let (status, body) = send_json(
            app.clone(),
            "DELETE",
            "/api/kanban/boards/temp-board",
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
        assert!(
            body["error"]["message"]
                .as_str()
                .unwrap()
                .contains("active task"),
            "{body}"
        );
        let (status, _) = send_json(
            app.clone(),
            "POST",
            &format!("/api/kanban/tasks/{task_id}/archive"),
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let (status, body) = send_json(
            app.clone(),
            "DELETE",
            "/api/kanban/boards/temp-board",
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["ok"], true, "{body}");

        // Removing it again 404s.
        let (status, _) = send_json(
            app.clone(),
            "DELETE",
            "/api/kanban/boards/temp-board",
            None,
            json!(null),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

