    #[tokio::test]
    async fn test_session_chat_slash_personality_lifecycle() {
        // P619: /personality lists, activates, and clears personas by
        // writing agent.system_prompt.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("config.toml"),
            "[agent.personalities]\npirate = \"Talk like a grizzled pirate.\"\n\n[agent.personalities.poet]\nsystem_prompt = \"Answer in verse.\"\ntone = \"lyrical\"\n",
        ).unwrap();
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let state = streaming_state();
        let sid = state
            .store
            .create_session("slash-personality", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        // Listing shows both names + the none option.
        let reply = post_chat(app.clone(), &sid, "/personality").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("pirate"), "{text}");
        assert!(text.contains("poet"), "{text}");
        assert!(text.contains("none"), "{text}");

        // Activate the table personality: prompt is resolved + persisted.
        let reply = post_chat(app.clone(), &sid, "/personality poet").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("personality set to poet"));
        let text = std::fs::read_to_string(dir.path().join("config.toml")).unwrap();
        let doc: toml::Value = toml::from_str(&text).expect("config parses");
        let pinned = doc
            .get("agent")
            .and_then(|agent| agent.get("system_prompt"))
            .and_then(|v| v.as_str());
        assert_eq!(pinned, Some("Answer in verse.\nTone: lyrical"), "{text}");

        // Unknown names list the available set.
        let reply = post_chat(app.clone(), &sid, "/personality wizard").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("unknown personality: wizard"), "{text}");
        assert!(text.contains("pirate"), "{text}");

        // Clearing removes the system_prompt pin.
        let reply = post_chat(app.clone(), &sid, "/personality none").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("personality cleared"));
        // The personalities table still defines a system_prompt key;
        // only the agent-level pin must be gone.
        let text = std::fs::read_to_string(dir.path().join("config.toml")).unwrap();
        let doc: toml::Value = toml::from_str(&text).expect("config parses");
        assert!(
            doc.get("agent")
                .and_then(|agent| agent.get("system_prompt"))
                .is_none(),
            "{text}"
        );

        match saved_home {
            Some(v) => std::env::set_var("ULNCLAW_HOME", v),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_session_chat_slash_runs_digest() {
        // P621: /runs renders the tracked-run digest (newest first).
        let state = streaming_state();
        let sid = state
            .store
            .create_session("slash-runs", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        let reply = post_chat(app.clone(), &sid, "/runs").await;
        assert_eq!(reply["response"], "no runs tracked yet.");

        state.runs.lock().await.insert(
            "run_old".to_string(),
            RunState {
                run_id: "run_old".to_string(),
                status: "completed".to_string(),
                session_id: Some(sid.clone()),
                message: "older run".to_string(),
                created_at: 100.0,
                finished_at: Some(105.0),
                result: Some("done".to_string()),
                error: None,
                iterations: Some(3),
                stop_requested: false,
                approval: None,
                job_id: None,
            },
        );
        state.runs.lock().await.insert(
            "run_new".to_string(),
            RunState {
                run_id: "run_new".to_string(),
                status: "failed".to_string(),
                session_id: Some(sid.clone()),
                message: "newer run".to_string(),
                created_at: 200.0,
                finished_at: Some(201.0),
                result: None,
                error: Some("provider exploded".to_string()),
                iterations: None,
                stop_requested: false,
                approval: None,
                job_id: None,
            },
        );

        let reply = post_chat(app.clone(), &sid, "/runs").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("tracked runs (2):"), "{text}");
        // Newest first.
        let new_pos = text.find("run_new").unwrap();
        let old_pos = text.find("run_old").unwrap();
        assert!(new_pos < old_pos, "{text}");
        assert!(text.contains("provider exploded"), "{text}");
        assert!(text.contains(&sid), "{text}");
    }

    #[tokio::test]
    async fn test_session_chat_slash_goal_lifecycle() {
        // P622: /goal + /subgoal manage the persisted standing-goal
        // state; setting a goal kicks it as this turn's work.
        let state = streaming_state();
        let sid = state
            .store
            .create_session("slash-goal", Some("fake-stream"), None)
            .expect("session created");
        let app = router(state.clone());

        let reply = post_chat(app.clone(), &sid, "/goal").await;
        assert_eq!(
            reply["response"],
            "No active goal. Set one with /goal <text>."
        );

        // Setting kicks the goal text as the turn (fake provider answers
        // "Hello"), and the goal persists.
        let reply = post_chat(app.clone(), &sid, "/goal ship the widget").await;
        assert_eq!(reply["response"], "Hello");
        let messages = state.store.load_messages(&sid).expect("messages load");
        assert!(messages
            .iter()
            .any(|m| m.content.as_deref() == Some("ship the widget")));

        let reply = post_chat(app.clone(), &sid, "/goal").await;
        let text = reply["response"].as_str().unwrap();
        assert!(text.contains("ship the widget"), "{text}");

        // Subgoals add/list/remove.
        let reply = post_chat(app.clone(), &sid, "/subgoal add tests").await;
        assert_eq!(reply["response"], "added subgoal: add tests");
        let reply = post_chat(app.clone(), &sid, "/subgoal").await;
        assert!(reply["response"].as_str().unwrap().contains("add tests"));
        let reply = post_chat(app.clone(), &sid, "/subgoal remove 1").await;
        assert_eq!(reply["response"], "removed subgoal 1: add tests");

        // Pause / resume / clear.
        let reply = post_chat(app.clone(), &sid, "/goal pause").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("goal paused: ship the widget"));
        let reply = post_chat(app.clone(), &sid, "/goal resume").await;
        assert!(reply["response"]
            .as_str()
            .unwrap()
            .contains("goal resumed: ship the widget"));
        let reply = post_chat(app.clone(), &sid, "/goal clear").await;
        assert_eq!(reply["response"], "goal cleared.");
        let reply = post_chat(app.clone(), &sid, "/goal").await;
        assert_eq!(
            reply["response"],
            "No active goal. Set one with /goal <text>."
        );
    }

