    #[tokio::test]
    async fn test_jobs_crud_lifecycle() {
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        // Validation errors.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs",
            Some(token),
            json!({"schedule": "30m", "prompt": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "Name is required");

        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs",
            Some(token),
            json!({"name": "j", "schedule": "not-a-schedule", "prompt": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs",
            Some(token),
            json!({"name": "j", "schedule": "30m", "prompt": "x", "repeat": 0}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Create.
        let (status, body) = send_json(
            app.clone(), "POST", "/api/jobs", Some(token),
            json!({"name": "daily digest", "schedule": "30m", "prompt": "summarize news", "repeat": 3}),
        ).await;
        assert_eq!(status, StatusCode::OK);
        let job = body["job"].clone();
        let job_id = job["id"].as_str().unwrap().to_string();
        assert_eq!(job["name"], "daily digest");
        assert_eq!(job["enabled"], true);
        assert_eq!(job["repeat"], 3);
        assert!(job["next_run"].as_f64().unwrap() > 0.0);

        // List hides disabled jobs unless asked.
        let (status, body) = get_json(app.clone(), "/api/jobs", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["jobs"].as_array().unwrap().len(), 1);

        // Get + 404.
        let (status, body) =
            get_json(app.clone(), &format!("/api/jobs/{}", job_id), Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["job"]["id"], job_id);
        let (status, _) = get_json(app.clone(), "/api/jobs/nope", Some(token)).await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        // Patch name + schedule; unknown fields are dropped.
        let (status, body) = send_json(
            app.clone(),
            "PATCH",
            &format!("/api/jobs/{}", job_id),
            Some(token),
            json!({"name": "renamed", "schedule": "0 9 * * *", "bogus": 1}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["job"]["name"], "renamed");
        assert_eq!(body["job"]["schedule"], "0 9 * * *");

        // Patch with only unknown fields → 400.
        let (status, body) = send_json(
            app.clone(),
            "PATCH",
            &format!("/api/jobs/{}", job_id),
            Some(token),
            json!({"bogus": 1}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "No valid fields to update");

        // Pause → hidden from list, visible with include_disabled.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            &format!("/api/jobs/{}/pause", job_id),
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["job"]["enabled"], false);
        let (_, body) = get_json(app.clone(), "/api/jobs", Some(token)).await;
        assert_eq!(body["jobs"].as_array().unwrap().len(), 0);
        let (_, body) = get_json(app.clone(), "/api/jobs?include_disabled=true", Some(token)).await;
        assert_eq!(body["jobs"].as_array().unwrap().len(), 1);

        // Resume recomputes next_run.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            &format!("/api/jobs/{}/resume", job_id),
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["job"]["enabled"], true);
        assert!(body["job"]["next_run"].as_f64().unwrap() > 0.0);

        // Delete.
        let (status, body) = send_json(
            app.clone(),
            "DELETE",
            &format!("/api/jobs/{}", job_id),
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["ok"], true);
        let (status, _) =
            get_json(app.clone(), &format!("/api/jobs/{}", job_id), Some(token)).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn test_jobs_blueprints_list_and_instantiate() {
        // P655: GET /api/jobs/blueprints serves the curated catalog and
        // POST /api/jobs/blueprints/instantiate fills slots into a real
        // cron job (hermes blueprint parity).
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        let (status, body) = get_json(app.clone(), "/api/jobs/blueprints", Some(token)).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let blueprints = body["blueprints"].as_array().unwrap();
        assert_eq!(blueprints.len(), 14, "{body}");
        let first = &blueprints[0];
        assert_eq!(first["key"], "morning-brief", "{body}");
        assert!(first["fields"].is_array(), "{body}");
        assert!(first["scheduleHuman"].as_str().unwrap().len() > 0, "{body}");
        assert!(
            first["command"]
                .as_str()
                .unwrap()
                .starts_with("/blueprint morning-brief"),
            "{body}"
        );

        // Instantiate with slot overrides creates a job.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/blueprints/instantiate",
            Some(token),
            json!({"blueprint": "morning-brief", "values": {"time": "07:15", "deliver": "local"}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["job"]["name"], "Morning briefing", "{body}");
        assert_eq!(body["job"]["schedule"], "15 7 * * *", "{body}");
        assert_eq!(body["job"]["deliver"], "local", "{body}");
        assert!(
            body["job"]["prompt"]
                .as_str()
                .unwrap()
                .contains("morning briefing"),
            "{body}"
        );

        // Slot validation error -> 422 with the field message.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/blueprints/instantiate",
            Some(token),
            json!({"blueprint": "morning-brief", "values": {"time": "25:99"}}),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{body}");
        assert!(
            body["error"].as_str().unwrap().contains("invalid time"),
            "{body}"
        );

        // Unknown slot names are rejected.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/blueprints/instantiate",
            Some(token),
            json!({"blueprint": "morning-brief", "values": {"tiem": "07:15"}}),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);

        // Unknown blueprint -> 404.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/blueprints/instantiate",
            Some(token),
            json!({"blueprint": "nope", "values": {}}),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn test_jobs_suggestions_endpoints() {
        // P673: suggestions HTTP surface — seed catalog, list pending,
        // accept (schedules into the default cron store), dismiss,
        // clear.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        // Empty at first.
        let (status, body) = get_json(app.clone(), "/api/jobs/suggestions", Some(token)).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["suggestions"].as_array().unwrap().len(), 0, "{body}");

        // Seed the curated catalog.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/suggestions/catalog",
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert!(!body["created"].as_array().unwrap().is_empty(), "{body}");

        // Pending list is populated.
        let (_, body) = get_json(app.clone(), "/api/jobs/suggestions", Some(token)).await;
        let suggestions = body["suggestions"].as_array().unwrap().clone();
        assert!(!suggestions.is_empty(), "{body}");
        let reference = suggestions[0]["id"].as_str().unwrap().to_string();

        // Accept schedules a real cron job into the default store.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/suggestions/accept",
            Some(token),
            json!({"reference": reference}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["scheduled"], true, "{body}");
        let cron = crate::cron::CronStore::open_default().expect("cron store");
        assert_eq!(cron.list().unwrap().len(), 1);

        // Dismiss the next pending suggestion.
        let (_, body) = get_json(app.clone(), "/api/jobs/suggestions", Some(token)).await;
        let remaining = body["suggestions"].as_array().unwrap().clone();
        let second = remaining[0]["id"].as_str().unwrap().to_string();
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/suggestions/dismiss",
            Some(token),
            json!({"reference": second}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["dismissed"], true, "{body}");

        // Unknown reference -> 404.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/suggestions/accept",
            Some(token),
            json!({"reference": "nope"}),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        // Clear drops accepted records.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/suggestions/clear",
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert!(body["removed"].as_u64().unwrap() >= 1, "{body}");

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_job_runs_history_endpoint() {
        // P674: GET /api/jobs/:id/runs lists the tracked runs spawned
        // for one cron job, newest first.
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        // Create a job.
        let (_, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs",
            Some(token),
            json!({"name": "histogram", "schedule": "1h", "prompt": "say hi"}),
        )
        .await;
        let job_id = body["job"]["id"].as_str().unwrap().to_string();

        // Empty history at first.
        let (status, body) = get_json(
            app.clone(),
            &format!("/api/jobs/{job_id}/runs"),
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["runs"].as_array().unwrap().len(), 0, "{body}");

        // Seed the run registry with two runs for this job + one for
        // another job.
        {
            let mut runs = state.runs.lock().await;
            runs.insert(
                "run-old".into(),
                RunState {
                    run_id: "run-old".into(),
                    status: "completed".into(),
                    session_id: None,
                    message: "first".into(),
                    created_at: 1000.0,
                    finished_at: Some(1010.0),
                    result: Some("ok".into()),
                    error: None,
                    iterations: None,
                    stop_requested: false,
                    approval: None,
                    job_id: Some(job_id.clone()),
                },
            );
            runs.insert(
                "run-new".into(),
                RunState {
                    run_id: "run-new".into(),
                    status: "failed".into(),
                    session_id: None,
                    message: "second".into(),
                    created_at: 2000.0,
                    finished_at: Some(2005.0),
                    result: None,
                    error: Some("boom".into()),
                    iterations: None,
                    stop_requested: false,
                    approval: None,
                    job_id: Some(job_id.clone()),
                },
            );
            runs.insert(
                "run-other".into(),
                RunState {
                    run_id: "run-other".into(),
                    status: "completed".into(),
                    session_id: None,
                    message: "other".into(),
                    created_at: 3000.0,
                    finished_at: None,
                    result: None,
                    error: None,
                    iterations: None,
                    stop_requested: false,
                    approval: None,
                    job_id: Some("another-job".into()),
                },
            );
        }

        let (status, body) = get_json(
            app.clone(),
            &format!("/api/jobs/{job_id}/runs"),
            Some(token),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let rows = body["runs"].as_array().unwrap();
        assert_eq!(rows.len(), 2, "{body}");
        assert_eq!(rows[0]["run_id"], "run-new", "{body}");
        assert_eq!(rows[0]["status"], "failed", "{body}");
        assert_eq!(rows[0]["error"], "boom", "{body}");
        assert_eq!(rows[1]["run_id"], "run-old", "{body}");

        // limit=1 keeps only the newest.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/jobs/{job_id}/runs?limit=1"),
            Some(token),
        )
        .await;
        assert_eq!(body["runs"].as_array().unwrap().len(), 1, "{body}");
    }

    #[tokio::test]
    async fn test_job_run_creates_tracked_run() {
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        let (_, body) = send_json(
            app.clone(),
            "POST",
            "/api/jobs",
            Some(token),
            json!({"name": "runnable", "schedule": "1h", "prompt": "say hi"}),
        )
        .await;
        let job_id = body["job"]["id"].as_str().unwrap().to_string();

        let (status, body) = send_json(
            app.clone(),
            "POST",
            &format!("/api/jobs/{}/run", job_id),
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let run_id = body["run_id"]
            .as_str()
            .expect("run id returned")
            .to_string();

        // The run is tracked; the provider is unreachable so it settles to
        // failed quickly.
        let mut settled = String::new();
        for _ in 0..40 {
            let (_, run) =
                get_json(app.clone(), &format!("/v1/runs/{}", run_id), Some(token)).await;
            settled = run["status"].as_str().unwrap_or("").to_string();
            if settled == "completed" || settled == "failed" {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
        assert!(matches!(settled.as_str(), "completed" | "failed"));

        // The job row recorded the trigger.
        let (_, body) = get_json(app.clone(), &format!("/api/jobs/{}", job_id), Some(token)).await;
        assert!(body["job"]["last_run"].as_f64().is_some());

        // Unknown job → 404.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/jobs/nope/run",
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

