    #[tokio::test]
    async fn test_logs_endpoints_inventory_and_tail() {
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());
        let logs_dir = dir.path().join("logs");
        std::fs::create_dir_all(&logs_dir).unwrap();
        std::fs::write(
            logs_dir.join("agent.log"),
            "2026-08-08 INFO hello world\n2026-08-08 ERROR bad thing\n",
        )
        .unwrap();

        let app = router(test_state());

        // Auth gate.
        let (status, _) = get_json(app.clone(), "/api/logs", None).await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        // Inventory lists the three known files with existence posture.
        let (status, body) = get_json(app.clone(), "/api/logs", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        let files = body["files"].as_array().unwrap();
        assert_eq!(files.len(), 3);
        let agent = files.iter().find(|f| f["name"] == "agent").unwrap();
        assert_eq!(agent["exists"], true);
        let errors = files.iter().find(|f| f["name"] == "errors").unwrap();
        assert_eq!(errors["exists"], false);

        // Tail returns both lines.
        let (status, body) = get_json(app.clone(), "/api/logs?file=agent", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["lines"].as_array().unwrap().len(), 2);

        // Level filter keeps only ERROR+.
        let (status, body) = get_json(
            app.clone(),
            "/api/logs?file=agent&level=ERROR",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let lines = body["lines"].as_array().unwrap();
        assert_eq!(lines.len(), 1);
        assert!(lines[0].as_str().unwrap().contains("bad thing"));

        // Search filter matches case-insensitively.
        let (status, body) = get_json(
            app.clone(),
            "/api/logs?file=agent&search=HELLO",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["lines"].as_array().unwrap().len(), 1);

        // Unknown file and unknown component are rejected.
        let (status, _) = get_json(app.clone(), "/api/logs?file=nope", Some("sekret")).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = get_json(
            app.clone(),
            "/api/logs?file=agent&component=nope",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_ops_hooks_endpoints_list_accept_revoke() {
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());
        std::fs::write(
            dir.path().join("shell-hooks-allowlist.json"),
            "{\"accepted\": [\"on_session_start\\techo hi\"]}",
        )
        .unwrap();

        let app = router(test_state());

        // Auth gate.
        let (status, _) = get_json(app.clone(), "/api/ops/hooks", None).await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        // List reports valid events + the allowlist census.
        let (status, body) = get_json(app.clone(), "/api/ops/hooks", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["valid_events"].as_array().unwrap().len() > 5);
        assert_eq!(body["allowlist"]["entries"], 1);
        assert!(body["hooks"].as_array().is_some());

        // Accept-all with no configured hooks accepts nothing.
        let (status, body) =
            post_json(app.clone(), "/api/ops/hooks/accept-all", "{}", "sekret").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["accepted"], 0);

        // Revoke requires a command.
        let (status, _) = request_json(
            app.clone(),
            "POST",
            "/api/ops/hooks/revoke",
            Some(r#"{"command": "  "}"#),
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Revoke removes the seeded entry.
        let (status, body) = request_json(
            app.clone(),
            "POST",
            "/api/ops/hooks/revoke",
            Some(r#"{"command": "echo hi"}"#),
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["removed"], 1);
        let (_, body) = get_json(app, "/api/ops/hooks", Some("sekret")).await;
        assert_eq!(body["allowlist"]["entries"], 0);

        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_audio_transcribe_endpoint_validation() {
        let app = router(test_state());

        // Auth gate.
        let (status, _) = post_json(app.clone(), "/api/audio/transcribe", "{}", "").await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        // Non-data-URL payload is rejected.
        let (status, _) = post_json(
            app.clone(),
            "/api/audio/transcribe",
            r#"{"data_url": "not-a-data-url"}"#,
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Non-base64 data URL is rejected.
        let (status, _) = post_json(
            app.clone(),
            "/api/audio/transcribe",
            r#"{"data_url": "data:audio/webm,plain"}"#,
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Non-audio mime is rejected.
        let (status, _) = post_json(
            app.clone(),
            "/api/audio/transcribe",
            r#"{"data_url": "data:text/plain;base64,aGVsbG8="}"#,
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Valid base64 audio but empty decoding is rejected.
        let (status, _) = post_json(
            app.clone(),
            "/api/audio/transcribe",
            r#"{"data_url": "data:audio/webm;base64,"}"#,
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Well-formed audio reaches provider readiness; the test state has
        // no STT provider configured, so the endpoint reports 503.
        let (status, _) = post_json(
            app,
            "/api/audio/transcribe",
            r#"{"data_url": "data:audio/webm;base64,aGVsbG8="}"#,
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE);
    }

