    #[tokio::test]
    async fn test_desktop_parity_endpoints_and_archived_filter() {
        let state = test_state();
        let app = router(state.clone());

        // Status / updater / profile-active shapes the renderer boots on.
        let (status, body) = get_json(app.clone(), "/api/status", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["gateway_running"], true);
        assert!(body["version"].as_str().is_some());

        let (status, body) = get_json(app.clone(), "/api/profiles/active", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["current"], "default");

        let (status, body) =
            get_json(app.clone(), "/api/ulnclaw/update/check", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["update_available"], false);

        // View surfaces return arrays / expected keys.
        let (status, body) = get_json(app.clone(), "/api/skills", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body.as_array().is_some());

        let (status, body) = get_json(app.clone(), "/api/tools/toolsets", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body.as_array().map(|a| !a.is_empty()).unwrap_or(false));

        let (status, body) =
            get_json(app.clone(), "/api/tools/terminal/backends", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["backends"].as_array().is_some());

        let (status, body) = get_json(
            app.clone(),
            "/api/tools/computer-use/status",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["platform"].as_str().is_some());

        let (status, body) = get_json(app.clone(), "/api/cron/blueprints", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["blueprints"].as_array().is_some());

        let (status, body) =
            get_json(app.clone(), "/api/cron/delivery-targets", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["targets"].as_array().is_some());

        // Batched sidebar payload carries the three windows.
        let (status, body) = get_json(
            app.clone(),
            "/api/profiles/sessions/sidebar?recents_profile=default",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["recents"]["sessions"].as_array().is_some());
        assert!(body["cron"]["sessions"].as_array().is_some());
        assert!(body["messaging"]["sessions"].as_array().is_some());

        // Archived filter uses the sessions archived column (not end_reason):
        // a completed session stays in `exclude` until explicitly archived.
        let id = state
            .store
            .create_session("desktop", Some("test-model"), None)
            .unwrap();
        state.store.end_session(&id, "complete").unwrap();
        let (status, body) = get_json(
            app.clone(),
            "/api/sessions?archived=exclude",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["data"]
            .as_array()
            .unwrap()
            .iter()
            .any(|row| row["id"] == id));

        state.store.set_session_archived(&id, true).unwrap();
        let (_, body) = get_json(
            app.clone(),
            "/api/sessions?archived=exclude",
            Some("sekret"),
        )
        .await;
        assert!(!body["data"]
            .as_array()
            .unwrap()
            .iter()
            .any(|row| row["id"] == id));
        let (_, body) = get_json(app, "/api/sessions?archived=only", Some("sekret")).await;
        assert!(body["data"]
            .as_array()
            .unwrap()
            .iter()
            .any(|row| row["id"] == id));
    }

    #[tokio::test]
    async fn test_fs_endpoints_list_read_write() {
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        // Home lives in a SEPARATE tempdir: dozens of unlocked tests read
        // ULNCLAW_HOME concurrently and would drop state files into `dir`
        // (corrupting fs-listing/git-status assertions) if it doubled as
        // the home.
        let home_dir = tempfile::tempdir().expect("tempdir");
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", home_dir.path());
        let saved_cwd = std::env::current_dir().unwrap();
        std::env::set_current_dir(dir.path()).unwrap();

        // Seed a small tree.
        std::fs::create_dir_all(dir.path().join("sub")).unwrap();
        std::fs::create_dir_all(dir.path().join("node_modules")).unwrap();
        std::fs::write(dir.path().join("hello.txt"), "hello fs\n").unwrap();

        let app = router(test_state());

        // Auth gate.
        let (status, _) = get_json(app.clone(), "/api/fs/list?path=.", None).await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        // Listing: dirs first, hidden set filtered.
        let (status, body) = get_json(app.clone(), "/api/fs/list?path=.", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        let entries = body["entries"].as_array().unwrap().clone();
        let names: Vec<String> = entries
            .iter()
            .filter_map(|entry| entry["name"].as_str().map(String::from))
            .collect();
        assert!(names.contains(&"sub".to_string()));
        assert!(names.contains(&"hello.txt".to_string()));
        assert!(!names.contains(&"node_modules".to_string()));
        assert_eq!(entries[0]["isDirectory"], true);

        // Read-text returns the content with metadata.
        let (status, body) = get_json(
            app.clone(),
            "/api/fs/read-text?path=hello.txt",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["text"], "hello fs\n");
        assert_eq!(body["byteSize"], 9);
        assert_eq!(body["binary"], false);

        // Write-text creates a new file atomically.
        let (status, body) = request_json(
            app.clone(),
            "POST",
            "/api/fs/write-text",
            Some(r#"{"path": "sub/created.txt", "content": "made by test"}"#),
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["ok"], true);
        assert_eq!(
            std::fs::read_to_string(dir.path().join("sub/created.txt")).unwrap(),
            "made by test"
        );

        // Write-text refuses missing parents.
        let (status, _) = request_json(
            app.clone(),
            "POST",
            "/api/fs/write-text",
            Some(r#"{"path": "nope/missing.txt", "content": "x"}"#),
            "sekret",
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Read-data-url round-trips.
        let (status, body) = get_json(
            app.clone(),
            "/api/fs/read-data-url?path=hello.txt",
            Some("sekret"),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["dataUrl"]
            .as_str()
            .unwrap()
            .starts_with("data:text/plain;base64,"));

        // Git-root on a git-less temp dir is null; default-cwd reports cwd.
        let (status, body) = get_json(app.clone(), "/api/fs/git-root?path=.", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["root"].is_null() || body["root"].is_string());
        let (status, body) = get_json(app.clone(), "/api/fs/default-cwd", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["cwd"].as_str().is_some());

        // Missing path errors are structured.
        let (status, _) = get_json(app.clone(), "/api/fs/list", Some("sekret")).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        std::env::set_current_dir(saved_cwd).unwrap();
        match saved_home {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_mcp_catalog_endpoints() {
        let _guard = crate::models_dev::test_env_lock();
        let tmp = tempfile::tempdir().unwrap();
        let prev = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", tmp.path());

        let app = router(test_state());
        let token = "sekret";

        // Catalog lists curated entries, none installed yet.
        let (status, body) = get_json(app.clone(), "/api/mcp/catalog", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let entries = body["entries"].as_array().unwrap().clone();
        assert!(entries.len() >= 8);
        let memory = entries
            .iter()
            .find(|entry| entry["name"] == "memory")
            .unwrap();
        assert_eq!(memory["installed"], false);
        let github = entries
            .iter()
            .find(|entry| entry["name"] == "github")
            .unwrap();
        assert_eq!(github["required_env"][0]["name"], "GITHUB_TOKEN");

        // Unknown entry 404s.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/mcp/catalog/install",
            Some(token),
            json!({"name": "no-such"}),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        // Install memory, then see it flagged installed.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/mcp/catalog/install",
            Some(token),
            json!({"name": "memory"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let on_disk = std::fs::read_to_string(tmp.path().join("config.toml")).unwrap();
        assert!(on_disk.contains("name = \"memory\""), "{on_disk}");
        let (status, body) = get_json(app.clone(), "/api/mcp/catalog", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let memory = body["entries"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["name"] == "memory")
            .cloned()
            .unwrap();
        assert_eq!(memory["installed"], true);
        assert_eq!(memory["enabled"], true);

        // Install with env vars stores them; duplicate install is rejected.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/mcp/catalog/install",
            Some(token),
            json!({"name": "github", "env": {"GITHUB_TOKEN": "ghp-test-token"}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let on_disk = std::fs::read_to_string(tmp.path().join("config.toml")).unwrap();
        assert!(on_disk.contains("GITHUB_TOKEN"), "{on_disk}");
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/mcp/catalog/install",
            Some(token),
            json!({"name": "github"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        match prev {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_model_auxiliary_endpoints() {
        let _guard = crate::models_dev::test_env_lock();
        let tmp = tempfile::tempdir().unwrap();
        let prev = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", tmp.path());

        let app = router(test_state());
        let token = "sekret";

        // Default: four slots, all "auto", main slot reported.
        let (status, body) = get_json(app.clone(), "/api/model/auxiliary", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let tasks = body["tasks"].as_array().unwrap().clone();
        assert_eq!(tasks.len(), crate::provider::auxiliary::TASK_SLOTS.len());
        assert!(tasks.iter().all(|task| task["provider"] == "auto"));
        assert!(body["main"]["model"].is_string());

        // Pin compression to a different provider/model.
        let (status, body) = send_json(
            app.clone(), "POST", "/api/model/set", Some(token),
            json!({"scope": "auxiliary", "task": "compression", "provider": "anthropic", "model": "claude-test"}),
        ).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["reset"], false);
        let on_disk = std::fs::read_to_string(tmp.path().join("config.toml")).unwrap();
        assert!(on_disk.contains("[auxiliary.compression]"), "{on_disk}");
        assert!(on_disk.contains("claude-test"), "{on_disk}");
        let (status, body) = get_json(app.clone(), "/api/model/auxiliary", Some(token)).await;
        assert_eq!(status, StatusCode::OK);
        let compression = body["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["task"] == "compression")
            .cloned()
            .unwrap();
        assert_eq!(compression["provider"], "anthropic");
        assert_eq!(compression["model"], "claude-test");

        // Unknown task and unknown scope are rejected.
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/model/set",
            Some(token),
            json!({"scope": "auxiliary", "task": "nope", "provider": "openai", "model": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        let (status, _) = send_json(
            app.clone(),
            "POST",
            "/api/model/set",
            Some(token),
            json!({"scope": "bogus", "provider": "openai", "model": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);

        // Reset removes the slot.
        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/api/model/set",
            Some(token),
            json!({"scope": "auxiliary", "task": "compression", "provider": "auto"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(body["reset"], true);
        let on_disk = std::fs::read_to_string(tmp.path().join("config.toml")).unwrap();
        assert!(!on_disk.contains("[auxiliary.compression]"), "{on_disk}");

        match prev {
            Some(value) => std::env::set_var("ULNCLAW_HOME", value),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

