    #[tokio::test]
    async fn test_get_session_includes_lineage_and_token_totals() {
        let state = test_state();
        let token = "sekret";
        let app = router(state.clone());

        let (status, body) =
            send_json(app.clone(), "POST", "/api/sessions", Some(token), json!({})).await;
        assert_eq!(status, StatusCode::CREATED, "{body}");
        let parent = body["id"].as_str().unwrap().to_string();

        // A fresh session has no children and zero tokens.
        let (_, row) = get_json(app.clone(), &format!("/api/sessions/{parent}"), Some(token)).await;
        assert_eq!(row["child_session_ids"], json!([]));
        assert_eq!(row["total_tokens"], 0);

        // Forking adds the child to the parent's lineage (P553).
        let (status, body) = send_json(
            app.clone(),
            "POST",
            &format!("/api/sessions/{parent}/fork"),
            Some(token),
            json!({}),
        )
        .await;
        assert!(status.is_success(), "{status} {body}");
        let child = body["session"]["id"].as_str().expect("fork id").to_string();

        // Message census counts each role separately (P561).
        state
            .store
            .append_message(
                &parent,
                &Message {
                    role: Role::User,
                    content: Some("hello".to_string()),
                    tool_calls: None,
                    tool_call_id: None,
                    name: None,
                },
            )
            .expect("user message");
        let (_, row) = get_json(app, &format!("/api/sessions/{parent}"), Some(token)).await;
        assert_eq!(row["child_session_ids"], json!([child]));
        assert_eq!(row["message_counts"], json!({"user": 1}));
        // Content snippets for at-a-glance context (P564).
        assert_eq!(row["first_user_message"], "hello");
        assert_eq!(row["last_message"], "hello");
        // P627: live context-in-use summary (conversation estimate +
        // static payload against the agent's budget).
        assert!(row["context"]["max"].as_u64().unwrap() > 0, "{row}");
        assert!(row["context"]["used"].as_u64().unwrap() > 0, "{row}");
        assert!(row["context"]["percent"].as_u64().unwrap() <= 100, "{row}");
    }

