    #[tokio::test]
    async fn test_run_settle_publishes_desktop_event() {
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());

        // Subscribe before the run starts so the settle event can't slip by.
        let mut rx = crate::desktop_bridge::subscribe();

        let (status, body) = send_json(
            app.clone(),
            "POST",
            "/v1/runs",
            Some(token),
            json!({"message": "settle me"}),
        )
        .await;
        assert_eq!(status, StatusCode::ACCEPTED);
        let run_id = body["run_id"].as_str().expect("run id").to_string();

        // The provider is unreachable, so the run settles to failed.
        let mut settled = String::new();
        for _ in 0..60 {
            let (_, run) =
                get_json(app.clone(), &format!("/v1/runs/{}", run_id), Some(token)).await;
            settled = run["status"].as_str().unwrap_or("").to_string();
            if settled == "completed" || settled == "failed" {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
        assert_eq!(settled, "failed");

        // The settle published a desktop bridge envelope for this run
        // (filter by run_id: parallel tests share the process-wide bus).
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut found = false;
        while std::time::Instant::now() < deadline && !found {
            match rx.try_recv() {
                Ok(envelope)
                    if envelope.payload["run_id"] == json!(run_id)
                        && matches!(envelope.event.as_str(), "run.completed" | "run.failed") =>
                {
                    assert_eq!(envelope.payload["status"], json!("failed"));
                    found = true;
                }
                Ok(_) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Empty) => {
                    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
                }
                Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_)) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Closed) => break,
            }
        }
        assert!(found, "run settle event not published on the desktop bus");
    }

    #[tokio::test]
    async fn test_approval_pump_publishes_desktop_event() {
        let (state, _temp) = jobs_state();
        let mut rx = crate::desktop_bridge::subscribe();
        let run_id = "run-approval-test".to_string();
        let session_id = "sess-approval-test".to_string();

        state.runs.lock().await.insert(
            run_id.clone(),
            RunState {
                run_id: run_id.clone(),
                status: "running".to_string(),
                session_id: Some(session_id.clone()),
                message: "needs approval".to_string(),
                created_at: now_secs(),
                finished_at: None,
                result: None,
                error: None,
                iterations: None,
                stop_requested: false,
                approval: None,
                job_id: None,
            },
        );

        spawn_approval_pump(state.clone(), run_id.clone(), session_id.clone());

        // Agent side raises a dangerous-command approval.
        let router = state.router.clone();
        let request_run_id = run_id.clone();
        let request = tokio::spawn(async move {
            router
                .request(
                    &request_run_id,
                    "dangerous command".into(),
                    "rm -rf /".into(),
                )
                .await
        });

        // The pump publishes a run.approval envelope for this run.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut found = false;
        while std::time::Instant::now() < deadline && !found {
            match rx.try_recv() {
                Ok(envelope)
                    if envelope.payload["run_id"] == json!(run_id)
                        && envelope.event == "run.approval" =>
                {
                    assert_eq!(envelope.payload["command"], json!("rm -rf /"));
                    found = true;
                }
                Ok(_) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Empty) => {
                    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
                }
                Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_)) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Closed) => break,
            }
        }
        assert!(found, "approval event not published on the desktop bus");

        // The run row flipped to waiting_for_approval with the pending detail.
        {
            let runs = state.runs.lock().await;
            let run = &runs[&run_id];
            assert_eq!(run.status, "waiting_for_approval");
            assert_eq!(run.approval.as_ref().unwrap()["command"], json!("rm -rf /"));
        }

        // Resolve like POST /v1/runs/:id/approval would; the agent unblocks.
        let respond = state
            .pending_approvals
            .lock()
            .await
            .remove(&run_id)
            .expect("parked respond");
        let _ = respond.send("once".to_string());
        assert!(request.await.unwrap());
    }

