    #[tokio::test]
    async fn test_session_patch_and_delete_publish_desktop_events() {
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());
        let mut rx = crate::desktop_bridge::subscribe();

        let id = state.store.create_session("gateway", None, None).unwrap();

        let (status, _) = send_json(
            app.clone(),
            "PATCH",
            &format!("/api/sessions/{}", id),
            Some(token),
            json!({"title": "renamed"}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        let (status, _) = send_json(
            app.clone(),
            "DELETE",
            &format!("/api/sessions/{}", id),
            Some(token),
            json!({}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        // The bus received both session.updated and session.deleted.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut saw_updated = false;
        let mut saw_deleted = false;
        while std::time::Instant::now() < deadline && !(saw_updated && saw_deleted) {
            match rx.try_recv() {
                Ok(envelope) if envelope.payload["session_id"] == json!(id) => {
                    if envelope.event == "session.updated" {
                        saw_updated = true;
                    }
                    if envelope.event == "session.deleted" {
                        saw_deleted = true;
                    }
                }
                Ok(_) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Empty) => {
                    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
                }
                Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_)) => {}
                Err(tokio::sync::broadcast::error::TryRecvError::Closed) => break,
            }
        }
        assert!(saw_updated, "session.updated not published");
        assert!(saw_deleted, "session.deleted not published");
    }

    #[tokio::test]
    async fn test_compress_slash_short_session_and_failed_provider() {
        use crate::provider::{Message, Role};
        let (state, _temp) = jobs_state();
        let session_id = state.store.create_session("gateway", None, None).unwrap();

        // Too short to compress.
        for i in 0..3 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("message {i}")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        match resolve_gateway_slash(&state, &session_id, "/compress").await {
            Some(GatewaySlash::Direct(text)) => {
                assert!(text.starts_with("nothing to compress"), "got: {text}")
            }
            _ => panic!("expected GatewaySlash::Direct"),
        }

        // Long enough, but the provider is unreachable — compression
        // reports failure instead of corrupting the transcript.
        for i in 3..24 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("message {i} with some padding content")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        match resolve_gateway_slash(&state, &session_id, "/compress").await {
            Some(GatewaySlash::Direct(text)) => {
                assert!(text.starts_with("compression failed"), "got: {text}")
            }
            _ => panic!("expected GatewaySlash::Direct"),
        }
        // Transcript untouched.
        assert_eq!(state.store.load_messages(&session_id).unwrap().len(), 24);
    }

    #[tokio::test]
    async fn test_session_messages_limit_tail() {
        use crate::provider::{Message, Role};
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());
        let session_id = state.store.create_session("gateway", None, None).unwrap();
        for i in 0..5 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("m{i}")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        // Plain tail.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?limit=2", session_id),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["content"], json!("m3"));
        assert_eq!(rows[1]["content"], json!("m4"));
        // Timestamped tail keeps the envelope.
        let (_, body) = get_json(
            app.clone(),
            &format!(
                "/api/sessions/{}/messages?limit=3&timestamps=true",
                session_id
            ),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0]["content"], json!("m2"));
        assert!(rows[0]["timestamp"].as_f64().is_some());
        // Limit larger than the transcript is a no-op.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?limit=99", session_id),
            Some(token),
        )
        .await;
        assert_eq!(body["data"].as_array().expect("rows").len(), 5);
    }

    #[tokio::test]
    async fn test_session_messages_before_cursor() {
        use crate::provider::{Message, Role};
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());
        let session_id = state.store.create_session("gateway", None, None).unwrap();
        for i in 0..10 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("m{i}")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        // `before` + `limit` yields the window ending just before the cursor.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?before=6&limit=3", session_id),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0]["content"], json!("m3"));
        assert_eq!(rows[2]["content"], json!("m5"));
        assert_eq!(body["total"], json!(10));
        // Cursor past the end clamps to the transcript length.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?before=99&limit=2", session_id),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows[0]["content"], json!("m8"));
        assert_eq!(rows[1]["content"], json!("m9"));
        // `before=0` is empty; the timestamped branch honors the cursor too.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?before=0&limit=5", session_id),
            Some(token),
        )
        .await;
        assert!(body["data"].as_array().expect("rows").is_empty());
        let (_, body) = get_json(
            app.clone(),
            &format!(
                "/api/sessions/{}/messages?before=4&limit=2&timestamps=true",
                session_id
            ),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["content"], json!("m2"));
        assert!(rows[0]["timestamp"].as_f64().is_some());
        assert_eq!(body["total"], json!(10));
    }

    #[tokio::test]
    async fn test_session_messages_after_cursor() {
        use crate::provider::{Message, Role};
        let (state, _temp) = jobs_state();
        let token = "sekret";
        let app = router(state.clone());
        let session_id = state.store.create_session("gateway", None, None).unwrap();
        for i in 0..10 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("m{i}")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        // `after` returns messages from the index onward (tail appends).
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?after=8", session_id),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0]["content"], json!("m8"));
        assert_eq!(rows[1]["content"], json!("m9"));
        assert_eq!(body["total"], json!(10));
        // `after` + `before` bound an interior slice.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?after=2&before=5", session_id),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0]["content"], json!("m2"));
        assert_eq!(rows[2]["content"], json!("m4"));
        // `after` past the end is empty; the timestamped branch agrees.
        let (_, body) = get_json(
            app.clone(),
            &format!("/api/sessions/{}/messages?after=10", session_id),
            Some(token),
        )
        .await;
        assert!(body["data"].as_array().expect("rows").is_empty());
        let (_, body) = get_json(
            app.clone(),
            &format!(
                "/api/sessions/{}/messages?after=7&timestamps=true",
                session_id
            ),
            Some(token),
        )
        .await;
        let rows = body["data"].as_array().expect("rows");
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0]["content"], json!("m7"));
        assert!(rows[0]["timestamp"].as_f64().is_some());
    }

    #[test]
    fn test_replace_messages_roundtrip() {
        use crate::provider::{Message, Role};
        let (state, _temp) = jobs_state();
        let session_id = state.store.create_session("gateway", None, None).unwrap();
        for i in 0..5 {
            state
                .store
                .append_message(
                    &session_id,
                    &Message {
                        role: if i % 2 == 0 {
                            Role::User
                        } else {
                            Role::Assistant
                        },
                        content: Some(format!("old {i}")),
                        tool_calls: None,
                        tool_call_id: None,
                        name: None,
                    },
                )
                .unwrap();
        }
        let replacement: Vec<Message> = (0..2)
            .map(|i| Message {
                role: if i == 0 { Role::User } else { Role::Assistant },
                content: Some(format!("new {i}")),
                tool_calls: None,
                tool_call_id: None,
                name: None,
            })
            .collect();
        state
            .store
            .replace_messages(&session_id, &replacement)
            .unwrap();
        let loaded = state.store.load_messages(&session_id).unwrap();
        assert_eq!(loaded.len(), 2);
        assert_eq!(loaded[0].content.as_deref(), Some("new 0"));
        assert_eq!(loaded[1].content.as_deref(), Some("new 1"));
        let row = state.store.get_session_row(&session_id).unwrap().unwrap();
        assert_eq!(row.message_count, 2);
    }

    #[tokio::test]
    async fn test_plugins_endpoints_inventory_and_toggle() {
        // Isolate ULNCLAW_HOME: disable/enable write config.toml.
        let _guard = crate::models_dev::test_env_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        let saved_home = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", dir.path());

        let app = router(test_state());

        let (status, _) = get_json(app.clone(), "/api/plugins", None).await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);

        let (status, body) = get_json(app.clone(), "/api/plugins", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["plugins"].as_array().is_some());
        assert!(body["config_hooks"].as_object().is_some());
        assert!(body["disabled"].as_array().is_some());

        // Disable writes the deny-list entry; the inventory reflects it.
        let (status, body) =
            post_json(app.clone(), "/api/plugins/demo/disable", "{}", "sekret").await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["message"].as_str().unwrap().contains("demo"));
        let (_, body) = get_json(app.clone(), "/api/plugins", Some("sekret")).await;
        let disabled: Vec<String> = body["disabled"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect();
        assert!(disabled.contains(&"demo".to_string()));

        // Enable removes it again.
        let (status, _) = post_json(app, "/api/plugins/demo/enable", "{}", "sekret").await;
        assert_eq!(status, StatusCode::OK);

        match saved_home {
            Some(v) => std::env::set_var("ULNCLAW_HOME", v),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

