    #[tokio::test]
    async fn test_drain_endpoint_lifecycle() {
        // P728: begin/cancel drain round-trip through the ops surface
        // (marker lives under ULNCLAW_HOME — isolate it).
        let _env_guard = crate::models_dev::test_env_lock();
        let temp = tempfile::tempdir().unwrap();
        let prev = std::env::var("ULNCLAW_HOME").ok();
        std::env::set_var("ULNCLAW_HOME", temp.path());

        let app = router(test_state());
        let (status, body) = get_json(app, "/api/drain", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["requested"], false, "{body}");
        assert_eq!(body["draining"], false, "{body}");
        assert!(body["marker"].is_null(), "{body}");

        // Begin drain via POST.
        let app = router(test_state());
        let request = axum::http::Request::builder()
            .uri("/api/drain")
            .method("POST")
            .header("authorization", "Bearer sekret")
            .header("content-type", "application/json")
            .body(axum::body::Body::from(
                r#"{"principal": "doctor-panel", "suppress_notification": true}"#,
            ))
            .unwrap();
        let response = tower::ServiceExt::oneshot(app, request).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body: Value = serde_json::from_slice(
            &axum::body::to_bytes(response.into_body(), usize::MAX)
                .await
                .unwrap(),
        )
        .unwrap();
        assert_eq!(body["ok"], true, "{body}");
        assert_eq!(body["payload"]["principal"], "doctor-panel", "{body}");

        // Status now reflects the active marker.
        let app = router(test_state());
        let (status, body) = get_json(app, "/api/drain", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["requested"], true, "{body}");
        assert_eq!(body["suppress_notification"], true, "{body}");
        assert_eq!(body["stale"], false, "{body}");
        assert_eq!(body["marker"]["principal"], "doctor-panel", "{body}");

        // Cancel drain via DELETE.
        let app = router(test_state());
        let request = axum::http::Request::builder()
            .uri("/api/drain")
            .method("DELETE")
            .header("authorization", "Bearer sekret")
            .body(axum::body::Body::empty())
            .unwrap();
        let response = tower::ServiceExt::oneshot(app, request).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body: Value = serde_json::from_slice(
            &axum::body::to_bytes(response.into_body(), usize::MAX)
                .await
                .unwrap(),
        )
        .unwrap();
        assert_eq!(body["existed"], true, "{body}");

        let app = router(test_state());
        let (_, body) = get_json(app, "/api/drain", Some("sekret")).await;
        assert_eq!(body["requested"], false, "{body}");

        match prev {
            Some(home) => std::env::set_var("ULNCLAW_HOME", home),
            None => std::env::remove_var("ULNCLAW_HOME"),
        }
    }

    #[tokio::test]
    async fn test_stall_watch_endpoint_shape() {
        // P716: the stall-watch ops surface reports the resolved
        // timeout + parked-inbound rows joined with activity stamps
        // (empty directory → zero rows). Global registries involved —
        // serialize with the env-lock family.
        let _env_guard = crate::models_dev::test_env_lock();
        crate::messaging::clear_pending_inbound_for_tests();
        crate::session_activity::clear_for_tests();
        let app = router(test_state());
        let (status, body) = get_json(app, "/api/stall-watch", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert!(body["timeout_seconds"].is_number(), "{body}");
        assert!(body["watcher_enabled"].is_boolean(), "{body}");
        assert_eq!(body["pending_count"], 0);
        assert!(body["rows"].is_array(), "{body}");

        // A parked session with a stale activity stamp renders stalled.
        let key = "platform-stallwatch-chat-1";
        crate::messaging::register_pending_inbound(key, "stallwatch", "chat-1");
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs_f64();
        crate::session_activity::touch_at(key, "tool call: shell", "agent.progress", now - 3600.0);
        let app = router(test_state());
        let (status, body) = get_json(app, "/api/stall-watch", Some("sekret")).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["pending_count"], 1, "{body}");
        let row = &body["rows"][0];
        assert_eq!(row["platform"], "stallwatch");
        assert!(row["idle_seconds"].as_f64().unwrap() >= 3500.0, "{row}");
        // Default timeout is 300s → an hour-idle parked chat is stalled.
        assert_eq!(row["stalled"], true, "{row}");
        assert_eq!(row["description"], "tool call: shell", "{row}");
        crate::messaging::clear_pending_inbound_for_tests();
        crate::session_activity::clear_for_tests();
    }

